INSERT INTO `places` (`id`, `place_code`, `place_name`, `description`, `opening_time`, `closing_time`, `latitude`, `longitude`, `subdistrict`, `district`, `province`, `created_at`, `updated_at`, `word_count`, `photo_count`, `expected_read_time`, `images_json`) VALUES
('1', 'PK290', 'ต้นตาล', 'ภาพของต้นตาลที่ยืนต้นสูงสง่าท่ามกลางทุ่งนาอันกว้างใหญ่ คือสัญลักษณ์ที่ขาดไม่ได้ของภูมิทัศน์ทุ่งกุลาร้องไห้และบ่อพันขัน ต้นตาลเป็นพืชที่ทนทานต่อความแห้งแล้งและดินเค็มได้อย่างดีเยี่ยม เปรียบเสมือนความอดทนของคนอีสานที่ไม่ย่อท้อต่อสภาพธรรมชาติประโยชน์อเนกประสงค์: ต้นตาลให้ประโยชน์แก่ชาวบ้านรอบบึงพันขันในทุกส่วน ตั้งแต่ \"ผลตาล\" ที่นำมาทำขนมตาลหรือจันอับ \"น้ำตาลโตนด\" ที่ให้ความหวานละมุน ใบตาลที่นำมาจักสานเป็นหมวกหรือพัด และลำต้นที่แข็งแรงนำมาทำเสาเรือนหรือสะพานข้ามคลองปลาค้าว ในสมัยโบราณต้นตาลยังถูกใช้เป็นหลักเขตที่ดินและทิศทางในการเดินทางผ่านทุ่งกว้างคุณค่าทางจิตใจ: ต้นตาลมักถูกกล่าวถึงในวรรณกรรมท้องถิ่นและบทเพลงที่สื่อถึงความคิดถึงบ้าน การอนุรักษ์ต้นตาลไว้ริมบึงพันขันจึงเป็นการรักษาภาพจำทางวัฒนธรรมให้นักท่องเที่ยวได้สัมผัสถึงความรุ่มรวยของทรัพยากรที่บรรพบุรุษมอบไว้ให้ เป็นพืชที่เชื่อมดินเข้ากับฟ้าอย่างสง่างาม', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '183', '2', '58', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk290/2026-04-29_10-00-46_IMG_7838.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk290/2026-04-29_10-00-51_IMG_20190512_174122.jpg\"]'),
('2', 'PK280', 'หญ้าหน่อง', '\"หญ้าหน่อง\" เป็นพืชล้มลุกท้องถิ่นที่เคยขึ้นอยู่อย่างหนาแน่นในบริเวณที่ลุ่มรอบบึงพันขัน ความสำคัญของพืชชนิดนี้ไม่ได้อยู่ที่สรรพคุณทางยาเพียงอย่างเดียว แต่อยู่ที่การเป็นที่มาของชื่อ \"หมู่บ้านหญ้าหน่อง\" ซึ่งเป็นชุมชนหลักที่ดูแลรักษาบ่อพันขันในปัจจุบัน การคงอยู่ของชื่อหญ้าหน่องจึงเป็นการรักษาอัตลักษณ์และรากเหง้าของบรรพบุรุษที่ตั้งถิ่นฐานตามลักษณะพืชพรรณธรรมชาตินิเวศวิทยาและความหลากหลาย: หญ้าหน่องมักเจริญเติบโตได้ดีในพื้นที่ที่มีน้ำขังหรือดินมีความชื้นสูงรอบพื้นที่ชุ่มน้ำ ในอดีตหญ้าชนิดนี้ถูกนำมาใช้ประโยชน์ในการเป็นอาหารสัตว์หรือใช้ปูรองพื้นคอกปศุสัตว์ การศึกษาเรื่องหญ้าหน่องในปัจจุบันจึงเป็นการย้อนกลับไปทำความเข้าใจระบบนิเวศดั้งเดิมของทุ่งกุลาร้องไห้ก่อนที่จะมีการปรับเปลี่ยนสภาพพื้นที่เพื่อทำนาปรังและอ่างเก็บน้ำการอนุรักษ์พรรณไม้ชื่อบ้าน: แม้ปัจจุบันหญ้าหน่องจะพบน้อยลงตามสภาพการใช้ที่ดินที่เปลี่ยนไป แต่ชุมชนหญ้าหน่องยังคงรักษาเรื่องราวของพืชชนิดนี้ไว้ในฐานะ \"พรรณไม้อัตลักษณ์\" เพื่อให้นักท่องเที่ยวได้เข้าใจถึงความสัมพันธ์ระหว่างชื่อสถานที่กับทรัพยากรธรรมชาติ เป็นการสร้างความภาคภูมิใจในถิ่นกำเนิดให้แก่คนรุ่นหลัง', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '230', '5', '79', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk280/2026-04-29_09-29-13_IMG_6523.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk280/2026-04-29_09-29-18_IMG_6608.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk280/2026-04-29_09-29-22_IMG_6690.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk280/2026-04-29_09-29-26_IMG_6810.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk280/2026-04-29_09-29-30_IMG_6877.jpg\"]'),
('3', 'PK279', 'ศูนย์เรียนรู้เกลือสินเธาว์', 'เกลือสินเธาว์ (Rock Salt) คือเกลือที่ผลิตจากดินเค็มในภาคอีสาน เป็นสินค้าที่มีมูลค่ามหาศาลในสมัยโบราณจนถูกขนานนามว่าเป็น \"ทองคำสีขาว\" (White Gold) บ่อพันขันเคยเป็นศูนย์กลางการผลิตเกลือสินเธาว์ที่ใหญ่ที่สุดแห่งหนึ่ง มีบันทึกว่าในอดีตมีผู้คนนับร้อยครัวเรือนมาตั้งกระท่อมเพื่อต้มเกลือกันที่นี่ เกลือเป็นสื่อกลางในการแลกเปลี่ยนสินค้าและเป็นหัวใจของการถนอมอาหารอีสานคุณสมบัติและรสนัวอันเป็นเอกลักษณ์: ความโดดเด่นของเกลือสินเธาว์บ่อพันขันคือมีความสะอาด บริสุทธิ์ และมีรสชาติที่ชาวบ้านเรียกว่า \"รสนัว\" (กลมกล่อม) ไม่เค็มจัดจนเกินไป เนื่องจากแร่ธาตุที่มากับชั้นหินทรายแดง เกลือชนิดนี้จึงนิยมนำมาใช้ทำปลาร้าสูตรดั้งเดิมและใช้ในการถนอมอาหารที่ต้องการรสชาติที่ลุ่มลึก นอกจากนี้ยังนำมาใช้ในกิจกรรม \"สปาสมุนไพร\" เพื่อการบำบัดสุขภาพในปัจจุบันสัญญะของความพากเพียร: เกลือสินเธาว์คือบทสรุปของภูมิปัญญาชาวบ่อพันขันที่ดึงเอาประโยชน์จากธรรมชาติที่ดูเหมือนจะเป็นลบ (ดินเค็ม) มาสร้างเป็นสิ่งที่มีค่าสูงสุด การได้สัมผัสและเรียนรู้การทำเกลือจะช่วยให้นักท่องเที่ยวเห็นคุณค่าของทรัพยากรและความเฉลียวฉลาดของบรรพบุรุษทุ่งกุลาร้องไห้', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '226', '1', '68', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk279/2026-04-29_09-25-29_LINE_ALBUM_ภาพบ่อพันขัน_250804_11.jpg\"]'),
('4', 'PK278', 'ดินเอียด, ส่าเกลือ', '\"ดินเอียด\" หรือ \"ส่าเกลือ\" คือคราบเกลือสีขาวที่ผุดขึ้นมาปกคลุมผิวดินในช่วงฤดูแล้งในพื้นที่บ่อพันขันและทุ่งกุลาร้องไห้ ปรากฏการณ์นี้เกิดจากน้ำใต้ดินที่มีความเค็มระเหยขึ้นสู่ผิวหน้าดินและทิ้งผลึกเกลือไว้ ตามตำนานท้องถิ่นเชื่อว่าส่าเกลือคือ \"พิษพญานาค\" ที่ซึมผ่านจีวรของพระมหาโมคคัลลานะ แต่ในทางวิทยาศาสตร์นี่คือขุมทรัพย์ทางแร่ธาตุที่สร้างเศรษฐกิจให้ชุมชนมานานภูมิปัญญาการนำไปใช้: ชาวบ้านมีภูมิปัญญาในการ \"ขูดดินเอียด\" มาใส่ในรางกรองที่ทำจากไม้หรือถังดิน นำน้ำสะอาดมาราดเพื่อละลายเอาความเค็มออกมาเป็นน้ำเกลือเข้มข้น ก่อนจะนำไปต้มจนได้ \"เกลือสินเธาว์\" ดินเอียดจึงเป็นวัตถุดิบต้นทางที่แสดงถึงความอุตสาหะและการสังเกตธรรมชาติของคนอีสานที่เปลี่ยน \"วิกฤตดินเค็ม\" ให้กลายเป็น \"โอกาสสร้างรายได้\"ตัวบ่งชี้ทางนิเวศวิทยา: การปรากฏของส่าเกลือยังเป็นเครื่องช่วยระบุประเภทของพืชพรรณที่จะเติบโตได้ในพื้นที่ เช่น พืชทนเค็มอย่างสะแกนา ดินเอียดจึงเป็นส่วนหนึ่งของวิถีชีวิตและภูมิทัศน์วัฒนธรรมของบ่อพันขันที่เป็นเอกลักษณ์ไม่เหมือนที่ใดในโลก', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '212', '3', '69', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk278/2026-04-29_09-15-17_IMG_20200210_113214.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk278/2026-04-29_09-15-20_Salt Heritage of Bo Phan Khan - 1.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk278/2026-04-29_09-15-24_DSC06700-EDIT.jpg\"]'),
('5', 'PK277', 'บ่อศิลาแลง', 'บ่อศิลาแลง หรือแหล่งขุดศิลาแลง เป็นพื้นที่ที่พบหินศิลาแลง (Laterite) ในชั้นดิน ซึ่งคนโบราณรู้จักนำมาใช้เป็นวัสดุก่อสร้างฐานรากของปราสาทหินและกู่ต่างๆ ในพื้นที่บ่อพันขันและทุ่งกุลาร้องไห้ ศิลาแลงเป็นหินที่เกิดจากการสะสมของแร่เหล็กและอลูมิเนียมในสภาพอากาศเขตร้อน มีคุณสมบัติพิเศษคือเมื่อขุดขึ้นมาใหม่จะนิ่ม แต่เมื่อถูกอากาศจะแข็งตัวและทนทานมากหลักฐานการจัดการทรัพยากร: ร่องรอยการขุดในบ่อศิลาแลงแสดงให้เห็นถึงความเข้าใจใน \"วัสดุศาสตร์\" ของช่างโบราณ ที่รู้จักเลือกใช้ทรัพยากรท้องถิ่นมาสร้างศาสนสถานศักดิ์สิทธิ์ การพบรอยตัดหินในลักษณะเดียวกับแหล่งหินตัดหินทรายแดง บ่งบอกถึงระบบการจัดการแรงงานและการช่างที่รุ่งเรืองมากในอดีต บ่อศิลาแลงเหล่านี้ในปัจจุบันบางแห่งกลายเป็นแหล่งน้ำธรรมชาติที่ช่วยรักษาความชุ่มชื้นให้แก่ผืนดินคุณค่าเชิงโบราณคดีและการเรียนรู้: การศึกษาบ่อศิลาแลงช่วยให้นักท่องเที่ยวและเยาวชนเข้าใจถึงวิวัฒนาการของการก่อสร้างในสมัยอารยธรรมขอม และเชื่อมโยงความสัมพันธ์ระหว่างทรัพยากรธรณีเข้ากับสถาปัตยกรรม เป็นการเรียนรู้วิทยาศาสตร์โบราณคดีที่น่าทึ่งผ่านร่องรอยที่ปรากฏอยู่บนพื้นดินบ่อพันขัน', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '219', '6', '78', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk277/2026-04-29_09-12-39_IMG_0576.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk277/2026-04-29_09-12-44_IMG_0581.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk277/2026-04-29_09-12-48_IMG_9790.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk277/2026-04-29_09-12-53_IMG_9802.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk277/2026-04-29_09-12-57_IMG_9804.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk277/2026-04-29_09-13-02_IMG_20190907_213003 สำเนา.JPG\"]'),
('6', 'PK276', 'สะพานเด่นราษฎร์', 'สะพานเด่นราษฎร์ เป็นสะพานข้ามลำน้ำหรือพื้นที่ลุ่มต่ำในตำบลเด่นราษฎร์ อำเภอหนองฮี มีบทบาทสำคัญในการเชื่อมโยงการสัญจรระหว่างหมู่บ้านรอบบ่อพันขัน สะพานแห่งนี้ไม่ได้เป็นเพียงสิ่งก่อสร้างทางวิศวกรรม แต่เป็นสัญลักษณ์ของความเจริญที่แผ่ขยายเข้ามาสู่พื้นที่ที่เคยห่างไกล ช่วยให้การขนส่งผลผลิตทางการเกษตร โดยเฉพาะข้าวหอมมะลิและเกลือ เป็นไปได้อย่างสะดวกและรวดเร็วจุดชมวิวและอัตลักษณ์ท้องถิ่น: บนสะพานเด่นราษฎร์ นักท่องเที่ยวจะได้เห็นภาพมุมกว้างของท้องทุ่งกุลาร้องไห้ที่สวยงามสุดสายตา ในช่วงฤดูทำนาจะเห็นนาข้าวเขียวขจี และในช่วงฤดูหนาวจะเห็นทุ่งสีทองเหลืองอร่าม สะพานแห่งนี้จึงเป็นจุดถ่ายภาพที่นิยมและเป็นที่พักผ่อนหย่อนใจของคนในพื้นที่ในช่วงเย็น ซึ่งลมพัดเย็นสบายจากอ่างเก็บน้ำและบึงใกล้เคียงความสำคัญเชิงยุทธศาสตร์: สะพานเด่นราษฎร์ช่วยลดความเหลื่อมล้ำในการเข้าถึงบริการพื้นฐานของรัฐและตลาดชุมชน ทำให้ชาวบ้านสามารถนำภูมิปัญญาและสินค้าจากบ่อพันขันออกไปสู่โลกภายนอกได้มากขึ้น เป็นฟันเฟืองสำคัญที่ขับเคลื่อนโครงการเส้นทางท่องเที่ยวชุมชนให้เติบโตอย่างมั่นคง', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:00:57', '208', '2', '65', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk276/2026-04-29_09-06-54_IMG_4161.JPG\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk276/2026-04-29_09-06-58_IMG_6505.jpg\"]'),
('7', 'PK275', 'อ่างเก็บน้ำหนองผำ', 'เป็นแหล่งน้ำจืดขนาดใหญ่ที่เป็นส่วนหนึ่งของระบบจัดการน้ำรอบบ่อพันขัน ชื่อ \"หนองผำ\" มาจากพืชน้ำขนาดเล็กที่มีชื่อว่า \"ผำ\" หรือ \"ไข่น้ำ\" (Wolffia) ซึ่งมักพบขึ้นอยู่อย่างหนาแน่นในน้ำที่ใสสะอาดและนิ่ง ผำเป็นพืชน้ำที่มีโปรตีนสูงและเป็นอาหารพื้นบ้านที่มีค่า อ่างเก็บน้ำแห่งนี้จึงเป็นตัวชี้วัดความสะอาดและความอุดมสมบูรณ์ของระบบนิเวศในพื้นที่ได้เป็นอย่างดีบทบาทต่อการเกษตรและความมั่นคงทางอาหาร: หนองผำทำหน้าที่กักเก็บน้ำสำรองไว้ใช้ในช่วงฤดูแล้งที่ยาวนานของทุ่งกุลาร้องไห้ ช่วยหล่อเลี้ยงพื้นที่ทำนาปรังและสวนสมุนไพรของหมู่บ้านหญ้าหน่อง นอกจากนี้ยังเป็นแหล่งทำประมงพื้นบ้านที่สำคัญ ชาวบ้านมักมาหาปลาและเก็บผักน้ำไปบริโภคและจำหน่ายใน Green Market เป็นแหล่งความมั่นคงทางอาหารที่พึ่งพาตนเองได้อย่างยั่งยืนคุณค่าเชิงนันทนาการและสิ่งแวดล้อม: ทัศนียภาพของอ่างเก็บน้ำหนองผำที่มีน้ำนิ่งสงบสะท้อนเงาท้องฟ้าเป็นจุดชมวิวที่สวยงาม นักท่องเที่ยวนิยมมาเดินสำรวจระบบนิเวศริมน้ำและสังเกตสิ่งมีชีวิตเล็กๆ ในหนองน้ำ เป็นการเรียนรู้เรื่อง \"ชีวภาค\" (Biosphere) ที่สัมพันธ์กับวิถีชีวิตชาวนาบ่อพันขันอย่างแยกไม่ออก', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '218', '3', '70', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk275/2026-04-29_08-52-44_IMG_8596.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk275/2026-04-29_08-52-49_IMG_8674.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk275/2026-04-29_08-52-53_IMG_8680.jpg\"]'),
('8', 'PK274', 'ศาลาไม้ริมน้ำ', 'เป็นอาคารโปร่งโล่งที่สร้างด้วยไม้เนื้อแข็งตามแบบสถาปัตยกรรมท้องถิ่น ตั้งอยู่ตามริมบึงพันขัน ศาลาเหล่านี้ออกแบบมาเพื่อรับลมธรรมชาติที่พัดผ่านผิวน้ำ ช่วยระบายความร้อนได้ดีเยี่ยม หลังคามักมุงด้วยหญ้าคาหรือใบสะแบงตามภูมิปัญญาโบราณ สร้างบรรยากาศที่อบอุ่นและกลมกลืนกับสภาพแวดล้อมพื้นที่ชุ่มน้ำพื้นที่เอนกประสงค์ของคนและธรรมชาติ: ศาลาไม้ไม่ได้เป็นเพียงที่นั่งพักเหนื่อยสำหรับนักท่องเที่ยว แต่ยังเป็นพื้นที่สำหรับจัดกิจกรรม \"ศิลปะบำบัด\" การนั่งสมาธิ หรือการจิบน้ำสมุนไพรดอกบัวแดง ความเงียบสงบในศาลาช่วยให้ผู้มาเยือนได้หยุดพักความวุ่นวายและเฝ้าสังเกตนกน้ำหรือความสวยงามของบัวสายที่บานสะพรั่ง ศาลาเหล่านี้จึงเปรียบเสมือน \"ห้องรับแขกธรรมชาติ\" ที่เปิดรับทุกคนด้วยความเป็นกันเองจุดเชื่อมโยงสังคม: ในยามเย็น ศาลาไม้ริมน้ำมักเป็นที่รวมตัวของปราชญ์ชาวบ้านและเยาวชนเพื่อแลกเปลี่ยนเรื่องราวตำนานบ่อพันขัน เป็นพื้นที่ที่มีความรื่นรมย์และสร้างแรงบันดาลใจในการอนุรักษ์ธรรมชาติ ทำให้บึงพันขันเป็นสถานที่ท่องเที่ยวที่เปี่ยมไปด้วยสุนทรียภาพและรอยยิ้ม', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '207', '1', '62', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk274/2026-04-29_08-47-02_IMG_20191231_121848.jpg\"]'),
('9', 'PK272', 'ศูนย์พลังงานแสงอาทิตย์', 'ศูนย์พลังงานแสงอาทิตย์ในพื้นที่บ่อพันขัน เป็นสถานีสาธิตการนำพลังงานจากดวงอาทิตย์มาเปลี่ยนเป็นพลังงานไฟฟ้าเพื่อใช้ในสาธารณูปโภคและการเกษตร เนื่องจากทุ่งกุลาร้องไห้เป็นพื้นที่ที่มีความเข้มของแสงแดดสูงเกือบตลอดปี นวัตกรรมนี้จึงมีความเหมาะสมอย่างยิ่งในการแก้ไขปัญหาเรื่องต้นทุนพลังงานที่สูงสำหรับเกษตรกรในการสูบน้ำขึ้นมาใช้ในไร่นาการประยุกต์ใช้งานจริง: ศูนย์แห่งนี้มีการติดตั้งแผงโซลาร์เซลล์เพื่อขับเคลื่อนระบบสูบน้ำบาดาลและระบบจัดการน้ำในอ่างเก็บน้ำหนองผำและบึงพันขัน นอกจากนี้ยังใช้พลังงานแสงอาทิตย์ในการให้แสงสว่างรอบแหล่งท่องเที่ยวและหอคอยชมวิวในเวลากลางคืน เป็นการลดภาระค่าไฟฟ้าของชุมชนและส่งเสริมภาพลักษณ์การท่องเที่ยวสีเขียว (Green Tourism) ที่เป็นมิตรต่อชั้นบรรยากาศ', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '147', '3', '50', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk272/2026-04-29_08-43-08_4768923542813346371.17bff37357693eb7e68279345e1fc7b6.22070505.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk272/2026-04-29_08-43-14_IMG_20191203_082339.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk272/2026-04-29_08-43-18_IMG_20191203_082355.jpg\"]'),
('10', 'PK270', 'ศูนย์เรียนรู้ภูมิปัญญาการเผาถ่านไม้', 'การเผาถ่านไม้เป็นภูมิปัญญาโบราณที่ได้รับการพัฒนาสู่มาตรฐานใหม่ที่ศูนย์เรียนรู้บ้านหญ้าหน่อง โดยเน้นการใช้ \"เตาเผาถ่านแบบน้ำส้มควันไม้\" ที่มีประสิทธิภาพสูงกว่าเตาหลุมแบบเดิม เทคนิคนี้ช่วยให้สามารถควบคุมอุณหภูมิและการไหลเวียนของอากาศภายในเตาได้อย่างแม่นยำ ทำให้ได้ถ่านไม้ที่มีคุณภาพสูง ให้ความร้อนสม่ำเสมอ ควันน้อย และมีอายุการใช้งานนานกว่าถ่านทั่วไปผลพลอยได้ที่เป็นประโยชน์: หัวใจสำคัญของศูนย์แห่งนี้คือการเก็บ \"น้ำส้มควันไม้\" (Wood Vinegar) ที่ได้จากการควบแน่นของควันที่เกิดระหว่างกระบวนการเผาถ่าน น้ำส้มควันไม้เป็นสารอเนกประสงค์ที่มีประโยชน์มหาศาลในเกษตรอินทรีย์ ทั้งใช้ไล่แมลงศัตรูพืช กระตุ้นการเจริญเติบโตของพืช และใช้ดับกลิ่นในคอกปศุสัตว์ เป็นการลดการพึ่งพาสารเคมีทางการเกษตรได้อย่างยั่งยืนและลดต้นทุนให้แก่เกษตรกรในพื้นที่บ่อพันขันการจัดการทรัพยากรอย่างคุ้มค่า: ไม้ที่นำมาเผาถ่านส่วนใหญ่มาจากไม้โตเร็วอย่างยูคาลิปตัสหรือกิ่งไม้ที่เหลือจากการตัดแต่งต้นไม้ในชุมชน เป็นการจัดการวัสดุเหลือใช้อย่างมีประสิทธิภาพ ศูนย์เรียนรู้แห่งนี้จึงเป็นสถานที่สอนเรื่องพลังงานทางเลือกและนวัตกรรมชาวบ้านที่เข้าใจง่ายและนำไปทำตามได้จริงในระดับครัวเรือน', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '230', '2', '71', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk270/2026-04-29_08-38-17_IMG_20191228_113542.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk270/2026-04-29_08-38-22_IMG_20191228_113912.jpg\"]'),
('11', 'PK267', 'รอยพระพุทธบาทจำลอง', 'รอยพระพุทธบาทจำลองที่ประดิษฐานอยู่ในบริเวณวัดเกาะบ่อพันขันรัตนโสภณหรือศาสนสถานในพื้นที่ เป็นสิ่งศักดิ์สิทธิ์ที่สร้างขึ้นตามคติความเชื่อเรื่องการจาริกธุดงค์ของพระพุทธเจ้า เพื่อเป็นเครื่องระลึกถึงพระธรรมคำสอนและการเข้าถึงความสงบ เป็นจุดศูนย์กลางที่ชาวบ้านและนักท่องเที่ยวเดินทางมากราบไหว้เพื่อความเป็นสิริมงคลก่อนจะเริ่มต้นทำกิจกรรมอื่นๆพุทธศิลป์และการเชื่อมโยงตำนาน: รอยพระพุทธบาทจำลองในพื้นที่นี้มักถูกสร้างขึ้นให้สัมพันธ์กับตำนานพระมหาโมคคัลลานะปราบพญานาค การประดิษฐานรอยพระพุทธบาทเป็นการตอกย้ำว่าพื้นที่บ่อพันขันเป็น \"พุทธภูมิ\" ที่ได้รับความเมตตาจากพระพุทธศาสนาในการเปลี่ยนดินแดนอาถรรพ์ให้กลายเป็นแผ่นดินทอง ลวดลายมงคล 108 ประการบนรอยพระพุทธบาทเป็นจุดที่นักท่องเที่ยวสามารถศึกษาเรื่องงานศิลปกรรมและการสื่อความหมายทางธรรมบทบาทต่อจิตใจและการท่องเที่ยว: สำหรับผู้มาเยือน การได้ปิดทองหรือสักการะรอยพระพุทธบาทจำลองคือกิจกรรมที่ช่วยสร้างสมาธิและทำให้จิตใจผ่องใส เป็นการเตรียมความพร้อมทางจิตวิญญาณก่อนจะไปซึมซับความสวยงามของบึงพันขัน รอยพระพุทธบาทจึงเป็นสัญลักษณ์ของรอยทางที่นำพาชุมชนไปสู่ทางสว่างและความสงบสุขอย่างยั่งยืน', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:03:43', '227', '2', '70', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk267/2026-04-29_08-30-33_Copy of image (3).jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk267/2026-04-29_08-30-38_Copy of IMG_20190415_160531_1_1.jpg\"]'),
('12', 'PK265', 'โนนไฮ', '\"โนนไฮ\" ในบริบทของพื้นที่รอบบ่อพันขันและทุ่งกุลาร้องไห้ หมายถึงเนินดินหรือที่ดอนขนาดใหญ่ที่น้ำท่วมไม่ถึง ซึ่งบรรพบุรุษได้เลือกใช้เป็นพื้นที่ยุทธศาสตร์ในการปลูกพืชไร่มาตั้งแต่อดีต ชื่อ \"โนนไฮ\" อาจมีที่มาจากลักษณะภูมิประเทศที่เป็นเนินสูงที่เหมาะแก่การทำ \"ไร่\" (ในภาษาอีสานมักออกเสียงใกล้เคียงกับคำว่า ไฮ) ภูมิประเทศแบบโนนหรือที่ดอนนี้เปรียบเสมือนโอเอซิสกลางทุ่งกว้างที่ใช้สำหรับทำการเกษตรนอกเหนือจากการทำนาข้าวในที่ลุ่มคลังเส้นใยและพืชไร่โบราณ: ในสมัยก่อน โนนไฮคือแหล่งปลูกพืชเศรษฐกิจที่สำคัญอย่าง \"ต้นปอ\" ซึ่งเป็นพืชที่ให้เส้นใยเหนียวทนทาน สำหรับนำมาทอเป็นกระสอบป่านหรือเชือกที่ใช้ในวิถีชีวิตเกษตรกรรม นอกจากนี้ยังเป็นพื้นที่ปลูกพืชไร่อื่นๆ เช่น ถั่วลิสง ข้าวโพด และหม่อนเพื่อเลี้ยงไหม การเลือกปลูกพืชบนโนนไฮสะท้อนถึงภูมิปัญญาการจัดการพื้นที่อย่างชาญฉลาด โดยเลือกพืชที่ต้องการการระบายน้ำดีและทนต่อสภาพอากาศบนที่สูงได้ดีกว่าข้าว ทำให้ชุมชนมีความมั่นคงทางอาหารและมีวัสดุสำหรับงานหัตถกรรมอย่างครบถ้วนกลุ่มโนนเหล่านี้เป็นหัวใจของการศึกษา \"ชั้นดินทางวัฒนธรรม\" และวิทยาศาสตร์ปฐพีวิทยา นักท่องเที่ยวสามารถเรียนรู้เรื่องการเปลี่ยนสีของดินที่เกิดจากการกัดเซาะและกิจกรรมของคนโบราณ เช่น การทำเกลือและการทำประมง การคงอยู่ของชื่อและสภาพพื้นที่เหล่านี้ช่วยให้เห็นโครงสร้างสังคมโบราณที่อาศัยอยู่ร่วมกันเป็นเครือข่ายคุณค่าเชิงการเรียนรู้: การสำรวจกลุ่มโนนและหนองน้ำเหล่านี้เป็นส่วนหนึ่งของเส้นทางท่องเที่ยวเชิงวิทยาศาสตร์ที่น่าตื่นเต้น ทำให้นักท่องเที่ยวได้สวมบทบาทเป็นนักโบราณคดีน้อยเพื่อสำรวจร่องรอยอดีต และเข้าใจว่าทุ่งกุลาร้องไห้ไม่ใช่พื้นที่รกร้าง แต่เป็นแผ่นดินที่มีชีวิตและมีประวัติศาสตร์ทับซ้อนกันหลายมิติ', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:04:39', '336', '2', '101', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk265/2026-04-29_08-24-07_IMG_8511.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk265/2026-04-29_08-24-12_IMG_8558.jpg\"]'),
('13', 'PK263', 'โนนจารย์น้อย', 'พื้นที่รอบบ่อพันขันประกอบด้วยเนินดินโบราณหลายแห่งที่มีชื่อเรียกตามอัตลักษณ์เฉพาะตัว เนินดินเหล่านี้คือฐานที่มั่นของอารยธรรมทุ่งกุลาในอดีตโนนจารย์น้อย: สื่อถึงเนินดินที่มีความเกี่ยวข้องกับ \"อาจารย์\" หรือผู้ทรงความรู้ในสมัยโบราณ มักพบร่องรอยเศษภาชนะดินเผากระจัดกระจายกลุ่มโนนเหล่านี้เป็นหัวใจของการศึกษา \"ชั้นดินทางวัฒนธรรม\" และวิทยาศาสตร์ปฐพีวิทยา นักท่องเที่ยวสามารถเรียนรู้เรื่องการเปลี่ยนสีของดินที่เกิดจากการกัดเซาะและกิจกรรมของคนโบราณ เช่น การทำเกลือและการทำประมง การคงอยู่ของชื่อและสภาพพื้นที่เหล่านี้ช่วยให้เห็นโครงสร้างสังคมโบราณที่อาศัยอยู่ร่วมกันเป็นเครือข่ายคุณค่าเชิงการเรียนรู้: การสำรวจกลุ่มโนนและหนองน้ำเหล่านี้เป็นส่วนหนึ่งของเส้นทางท่องเที่ยวเชิงวิทยาศาสตร์ที่น่าตื่นเต้น ทำให้นักท่องเที่ยวได้สวมบทบาทเป็นนักโบราณคดีน้อยเพื่อสำรวจร่องรอยอดีต และเข้าใจว่าทุ่งกุลาร้องไห้ไม่ใช่พื้นที่รกร้าง แต่เป็นแผ่นดินที่มีชีวิตและมีประวัติศาสตร์ทับซ้อนกันหลายมิติ', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:06:06', '194', '3', '63', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk263/2026-04-29_08-18-16_IMG_9802.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk263/2026-04-29_08-18-20_IMG_20200608_210141.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk263/2026-04-29_08-18-26_P2302280.JPG\"]'),
('14', 'PK261', 'ลานจามจุรี', 'ลานจามจุรีเป็นพื้นที่กิจกรรมริมบึงพันขันที่มีต้นจามจุรี (ต้นก้ามปู) ขนาดใหญ่แผ่กิ่งก้านสาขาให้ร่มเงาครอบคลุมบริเวณกว้าง ต้นจามจุรีเป็นไม้ที่เติบโตได้ดีในพื้นที่ใกล้แหล่งน้ำและมีใบที่ช่วยบำรุงดินได้เยี่ยม ลานแห่งนี้จึงมีความร่มรื่นตลอดทั้งปีและเป็นจุดที่อากาศถ่ายเทสะดวกที่สุดจุดหนึ่งในชุมชนหญ้าหน่องบทบาทต่อชุมชนและนักท่องเที่ยว: ลานจามจุรีทำหน้าที่เป็น \"ศาลาอเนกประสงค์กลางแจ้ง\" ที่ใช้สำหรับจัดกิจกรรม \"ตลาดชุมชน Green Market\" ซึ่งเป็นที่จำหน่ายสินค้าเกษตรอินทรีย์และหัตถกรรมจากฝีมือชาวบ้าน นอกจากนี้ยังเป็นพื้นที่สำหรับจัดกิจกรรม \"ศิลปะบำบัด\" และ \"โยคะริมบึง\" ร่มเงาที่กว้างใหญ่ช่วยสร้างสภาวะที่ผ่อนคลาย (Relaxation) ทำให้นักท่องเที่ยวรู้สึกปลอดภัยและเป็นมิตรกับสิ่งแวดล้อมสัญลักษณ์ของการอยู่ร่วมกัน: ต้นจามจุรีที่แผ่กิ่งก้านปกคลุมลานกิจกรรมสื่อถึงการโอบอุ้มของธรรมชาติที่มีต่อมนุษย์ ลานจามจุรีจึงเป็นพื้นที่แห่งความสุขที่ไร้กำแพงขวางกั้น เป็นสถานที่ที่คนในชุมชนและผู้มาเยือนสามารถมานั่งสนทนา แลกเปลี่ยนเรียนรู้ และซึมซับวิถีชีวิตที่เรียบง่ายแต่เปี่ยมด้วยพลังชีวิต', NULL, NULL, NULL, NULL, '', '', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:06:39', '216', '3', '70', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk261/2026-04-29_08-10-52_IMG_1015.JPG\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk261/2026-04-29_08-10-56_IMG_8186-EDIT.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk261/2026-04-29_08-11-00_LINE_ALBUM_ค่ายร้อยเอ็ด_231117_46.jpg\"]'),
('15', 'PK260', 'สะพานมิตรภาพบ่อพันขัน', 'สะพานมิตรภาพบ่อพันขันเป็นโครงสร้างที่สร้างขึ้นเพื่อเชื่อมต่อการเดินทางระหว่างอำเภอหนองฮีและอำเภอสุวรรณภูมิเหนือผืนน้ำบึงพันขัน สะพานแห่งนี้ไม่ได้ทำหน้าที่เพียงการสัญจร แต่เป็นสัญลักษณ์ของ \"มิตรภาพ\" และการร่วมมือกันของคนในท้องถิ่นในการพัฒนาพื้นที่ท่องเที่ยว เป็นจุดที่นักท่องเที่ยวนิยมมาถ่ายภาพ โดยเฉพาะช่วงเช้าที่เห็นดอกบัวแดงบานสะพรั่งอยู่ใต้สะพานคุณค่าเชิงการท่องเที่ยว: พื้นที่บริเวณโนนคอคีบและสะพานมิตรภาพฯ ได้รับการพัฒนาให้เป็นจุดพักรถและจุดชมดวงอาทิตย์ตกดินที่สวยงาม มีหอคอยไม้ชมวิวสามชั้นที่สร้างจากวัสดุธรรมชาติ ช่วยให้ผู้มาเยือนได้เห็นความกว้างใหญ่ของทุ่งกุลาร้องไห้ในมุมมองแบบ 360 องศา สะท้อนความสวยงามของระบบนิเวศพื้นที่ชุ่มน้ำที่ยิ่งใหญ่', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:07:07', '144', '4', '52', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk260/2026-04-29_08-04-52_IMG_1713.JPG\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk260/2026-04-29_08-04-57_IMG_5674-EDIT.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk260/2026-04-29_08-05-00_IMG_20200608_211103.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk260/2026-04-29_08-05-05_IMG_20200608_211445.jpg\"]'),
('16', 'PK259', 'โนนคอคีบ', 'เป็นลักษณะภูมิประเทศที่เป็นเนินดินขนาดเล็กตั้งอยู่บริเวณส่วนที่คอดกิ่วที่สุดของบึงพันขัน ลักษณะคล้ายลำคอที่คอดเข้าหากัน จึงเป็นที่มาของชื่อ \"คอคีบ\" จุดนี้ถือเป็นชัยภูมิที่สวยงามที่สุดแห่งหนึ่งในการชมทัศนียภาพรอบบึง เนื่องจากสามารถมองเห็นผืนน้ำได้ทั้งสองฝั่ง และเป็นจุดที่รับลมธรรมชาติได้ดีที่สุด เหมาะสำหรับการพักผ่อนและจัดกิจกรรมสันทนาการคุณค่าเชิงการท่องเที่ยว: พื้นที่บริเวณโนนคอคีบและสะพานมิตรภาพฯ ได้รับการพัฒนาให้เป็นจุดพักรถและจุดชมดวงอาทิตย์ตกดินที่สวยงาม มีหอคอยไม้ชมวิวสามชั้นที่สร้างจากวัสดุธรรมชาติ ช่วยให้ผู้มาเยือนได้เห็นความกว้างใหญ่ของทุ่งกุลาร้องไห้ในมุมมองแบบ 360 องศา สะท้อนความสวยงามของระบบนิเวศพื้นที่ชุ่มน้ำที่ยิ่งใหญ่', NULL, NULL, NULL, NULL, 'จำปาขัน', 'สุวรรณภูมิ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:09:35', '142', '2', '46', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk259/2026-04-29_07-59-31_IMG_20191228_122904.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk259/2026-04-29_08-00-29_IMG_1251.jpg\"]'),
('17', 'PK258', 'พญานาค ปู่ศรีสุวรรณ ย่าศรีคำแก้ว', 'ในพื้นที่บ่อพันขัน ความเชื่อเรื่องพญานาคมีความเข้มข้นอย่างมาก เนื่องจากมีปรากฏการณ์น้ำผุดและดินเค็มซึ่งตามตำนานเชื่อว่าเกิดจากพิษพญานาค พญานาคปู่ศรีสุวรรณ (หรือนาคาธิบดีศรีสุวรรณมณีนาโค) และย่าศรีคำแก้ว ถูกเชื่อว่าเป็นผู้ปกปักรักษาขุมทรัพย์และแหล่งน้ำจืดใต้ลานหินทรายแดงแห่งนี้ องค์ปู่ศรีสุวรรณมักถูกกล่าวถึงในฐานะพญานาคสีทองที่มีบารมีสูงเปี่ยมด้วยความเมตตาสถาปัตยกรรมและสัญลักษณ์: รูปปั้นพญานาคที่สง่างามริมบ่อพันขันที่เริ่มก่อสร้างอย่างโดดเด่นในปี พ.ศ. 2564 เป็นงานศิลปกรรมร่วมสมัยที่สร้างขึ้นจากแรงศรัทธา ลำตัวที่คดเคี้ยวสอดประสานกันสื่อถึงความเชื่อมโยงของสายน้ำใต้ดินและการปกป้องคุ้มครองบ่อพันขัน สีสันและลวดลายขององค์พญานาคสะท้อนถึงความรุ่มรวยทางศิลปะและความศรัทธาที่ชาวบ้านมีต่อโลกเร้นลับที่คอยค้ำจุนระบบนิเวศความหมายในเชิงวิถีชีวิต: การเคารพปู่ศรีสุวรรณและย่าศรีคำแก้วคือการแสดงความเคารพต่อ \"น้ำ\" ซึ่งเป็นปัจจัยหลักในการดำรงชีวิตของคนในทุ่งกุลาร้องไห้ ความเชื่อนี้ช่วยให้ชาวบ้านเกิดความยำเกรงต่อธรรมชาติ ไม่กล้าทำลายแหล่งน้ำ และร่วมกันรักษาความสะอาดของบึงพันขัน พญานาคจึงเปรียบเสมือนสัญลักษณ์ของการอนุรักษ์ธรรมชาติที่ถูกห่อหุ้มด้วยศรัทธา', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:10:03', '234', '3', '75', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk258/2026-04-29_07-56-24_IMG_0370.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk258/2026-04-29_07-56-28_LINE_ALBUM_ภาพบ่อพันขัน_250217_124.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk258/2026-04-29_07-56-31_LINE_ALBUM_ภาพบ่อพันขัน_250217_126.jpg\"]'),
('18', 'PK257', 'เจ้าปู่ผ่าน, ศาลเจ้าพ่อบ่อพันขัน', 'เจ้าปู่ผ่าน หรือ \"เจ้าพ่อบ่อพันขัน\" คือสิ่งศักดิ์สิทธิ์ชั้นสูงที่ชาวบ้านในทุ่งกุลาร้องไห้ให้ความเคารพนับถืออย่างยิ่ง เชื่อว่าท่านเป็นเทพารักษ์หรือบรรพบุรุษผู้ทรงฤทธิ์ที่คอยปกปักรักษาบ่อพันขันและบึงพันขันไม่ให้เสื่อมสลาย ชื่อ \"ปู่ผ่าน\" สื่อถึงบารมีที่แผ่ไพศาลผ่านพ้นขอบเขตพื้นที่ คุ้มครองผู้ที่มาสักการะให้แคล้วคลาดปลอดภัยและมีความร่มเย็นเป็นสุขศาลเจ้าพ่อบ่อพันขัน: ศูนย์รวมจิตใจ: ศาลเจ้าพ่อบ่อพันขันเป็นอาคารที่ตั้งอยู่ริมบ่อพันขัน (น้ำส่างครก) ภายในเป็นที่ประดิษฐานรูปเคารพของเจ้าปู่ผ่าน ศาลแห่งนี้เป็นสถานที่สำคัญที่ชาวบ้านจะเดินทางมาบวงสรวงกราบไหว้ในโอกาสสำคัญ เช่น งานบุญประเพณี หรือเมื่อมีการเริ่มต้นโครงการใหม่ๆ ในชุมชน พิธีกรรมบวงสรวงเจ้าพ่อบ่อพันขันเป็นภาพสะท้อนของความกตัญญูที่มนุษย์มีต่อสิ่งศักดิ์สิทธิ์ที่ดูแลทรัพยากรธรรมชาติ (น้ำและดินเค็ม) ให้คงอยู่สืบไปบทบาทในเชิงวัฒนธรรมและการท่องเที่ยว: สำหรับนักท่องเที่ยว การแวะสักการะศาลเจ้าพ่อบ่อพันขันคือจุดเริ่มต้นของการเข้าถึง \"ใจ\" ของชุมชน เรื่องเล่าและตำนานเกี่ยวกับเจ้าปู่ผ่านช่วยเพิ่มมนต์เสน่ห์ให้กับบ่อพันขัน ทำให้พื้นที่แห่งนี้ไม่ได้เป็นเพียงบ่อน้ำจืดมหัศจรรย์ในทางวิทยาศาสตร์เท่านั้น แต่เป็นพื้นที่ที่มีจิตวิญญาณและเรื่องราวความเชื่อที่หยั่งรากลึก', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:10:46', '251', '5', '85', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk257/2026-04-29_07-49-54_LINE_ALBUM_ภาพบ่อพันขัน_250217_142.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk257/2026-04-29_07-49-57_LINE_ALBUM_ภาพบ่อพันขัน_250217_145.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk257/2026-04-29_07-50-01_LINE_ALBUM_ภาพบ่อพันขัน_250217_146.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk257/2026-04-29_07-50-04_LINE_ALBUM_ภาพบ่อพันขัน_250217_152.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk257/2026-04-29_07-50-07_LINE_ALBUM_ภาพบ่อพันขัน_250217_156.jpg\"]'),
('19', 'PK256', 'โบราณสถานโนนขันหมาก', 'โนนขันหมาก เป็นเนินดินโบราณ (ภาษาอีสานเรียกเนินดินว่า \"โนน\") ที่มีความสำคัญทางโบราณคดีและประวัติศาสตร์ ตั้งอยู่ไม่ไกลจากบึงพันขัน ชื่อ \"ขันหมาก\" สื่อถึงความเชื่อท้องถิ่นที่เกี่ยวกับการประกอบพิธีกรรมหรือตำนานพื้นบ้านที่มักเชื่อมโยงกับเรื่องราวการหมั้นหมายหรือพิธีมงคลในอดีต เนินดินแห่งนี้เป็นพยานหลักฐานสำคัญที่แสดงให้เห็นว่าพื้นที่รอบบ่อพันขันมีการตั้งถิ่นฐานของมนุษย์มาอย่างยาวนานและมีการใช้ประโยชน์ในเชิงพื้นที่ศักดิ์สิทธิ์หลักฐานทางโบราณคดีและความสำคัญ: จากการสำรวจในเบื้องต้นพบว่าโนนขันหมากมีร่องรอยของสิ่งก่อสร้างโบราณที่อาจเป็นศาสนสถานในวัฒนธรรมขอมหรือวัฒนธรรมล้านช้างที่แผ่อิทธิพลเข้ามาในทุ่งกุลาร้องไห้ พบเศษอิฐและเศษภาชนะดินเผากระจัดกระจายอยู่ทั่วไป ซึ่งเป็นตัวบ่งชี้ถึงกิจกรรมของมนุษย์ในสมัยประวัติศาสตร์ เนินดินนี้ยังทำหน้าที่เป็นจุดยุทธศาสตร์ที่น้ำท่วมไม่ถึงในช่วงฤดูน้ำหลาก ทำให้เป็นที่พักพิงและที่ตั้งของสถานประกอบพิธีกรรมของชุมชนโบราณรอบบึงพันขันบทบาทในปัจจุบัน: ปัจจุบันโบราณสถานโนนขันหมากได้รับการดูแลโดยชุมชนและหน่วยงานที่เกี่ยวข้องในฐานะแหล่งท่องเที่ยวเชิงประวัติศาสตร์ นักท่องเที่ยวสามารถเดินสำรวจร่องรอยอดีตและสัมผัสความสงบเงียบของป่าชุมชนที่ปกคลุมเนินดินแห่งนี้ เป็นจุดที่ช่วยเชื่อมโยงเรื่องราวของคนโบราณเข้ากับสภาพภูมิศาสตร์พื้นที่ชุ่มน้ำได้อย่างชัดเจน', NULL, NULL, NULL, NULL, 'จำปาขัน', 'สุวรรณภูมิ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:11:31', '263', '3', '83', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk256/2026-04-29_07-45-23_image (2).jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk256/2026-04-29_07-45-26_image (4).jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk256/2026-04-29_07-45-31_IMG_0154.jpg\"]'),
('20', 'PK255', 'ฐานรูปเคารพ, จารึกพระเจ้าจิตรเสน, อักษรปัลลวะ, ศาสนาพราหมณ์-ฮินดู, ลัทธิไศวนิกาย,', 'จารึกที่เกี่ยวเนื่องกับพระเจ้าจิตรเสน (หรือพระเจ้ามเหนทรวรมัน) แห่งอาณาจักรเจนละ เป็นหลักฐานชิ้นสำคัญที่พบในเขตอีสาน รวมถึงร่องรอยความเชื่อมโยงในพื้นที่ทุ่งกุลาร้องไห้ จารึกนี้ระบุถึงการแผ่ขยายพระราชอำนาจและการสถาปนาศิวลึงค์เป็นสัญลักษณ์แห่งชัยชนะและการนับถือศาสนาฮินดู เป็นกุญแจสำคัญที่ทำให้นักประวัติศาสตร์ทราบว่าพื้นที่บ่อพันขันเคยเป็นส่วนหนึ่งของขอบเขตอิทธิพลการปกครองในพุทธศตวรรษที่ 11-12อักษรปัลลวะ: รากฐานอักขระโบราณ: อักษรที่ใช้ในจารึกเหล่านี้คือ \"อักษรปัลลวะ\" ซึ่งได้รับอิทธิพลมาจากอินเดียใต้ เป็นต้นแบบของอักษรขอมโบราณและพัฒนามาเป็นอักษรไทยในเวลาต่อมา ลักษณะตัวอักษรมีความสวยงามและทรงพลัง มักจารึกลงบนแผ่นหินทรายหรือผนังถ้ำ การพบร่องรอยอักษรชนิดนี้ในพื้นที่บ่อพันขันเป็นการยืนยันสถานะของชุมชนโบราณที่นี่ว่ามีการติดต่อสื่อสารและได้รับอารยธรรมขั้นสูงมาจากภายนอกบทบาทในเชิงวิชาการและการท่องเที่ยว: จารึกพระเจ้าจิตรเสนและอักษรปัลลวะเป็นสื่อกลางที่พานักท่องเที่ยวเดินย้อนเวลากลับไปสู่ยุคเริ่มต้นของประวัติศาสตร์ไทย การเรียนรู้เรื่องอักษรโบราณบนศิลาทรายแดงช่วยสร้างแรงบันดาลใจและทำให้เห็นความสำคัญของการอนุรักษ์มรดกจารึก ซึ่งเป็นหลักฐานชั้นต้นที่น่าเชื่อถือที่สุดในการศึกษาเรื่องรากเหง้าของท้องถิ่น', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:12:01', '247', '3', '79', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk255/2026-04-29_07-19-50_IMG_2485.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk255/2026-04-29_07-19-55_IMG_2486.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk255/2026-04-29_07-19-59_IMG_2490.jpg\"]'),
('21', 'PK254', 'รางระบายน้ำหิน', 'รางระบายน้ำหินที่ขุดพบในโบราณสถานบ้านหนองคูณและพื้นที่โดยรอบ เป็นประจักษ์พยานถึงความฉลาดในการจัดการน้ำของคนโบราณ รางเหล่านี้สกัดมาจากหินทรายแดง มีลักษณะเป็นร่องยาวสำหรับให้น้ำไหลผ่าน ใช้ในสองวัตถุประสงค์หลัก คือการระบายน้ำออกจากตัวอาคารเพื่อป้องกันการกัดเซาะ และการใช้ในพิธีกรรมทางศาสนาที่เรียกว่า \"โสมสูตร\" เพื่อให้น้ำที่ผ่านการสรงรูปเคารพไหลออกสู่ภายนอกศาสนสถานฐานรูปเคารพ: ศูนย์กลางแห่งความศรัทธา: ฐานรูปเคารพที่พบในบริเวณกู่โบราณ มักเป็นฐานศิลาสำหรับประดิษฐานศิวลึงค์หรือเทวรูปสำคัญ ฐานเหล่านี้ถูกออกแบบให้มีร่องรองรับน้ำมนต์เพื่อเชื่อมต่อกับรางระบายน้ำหิน ฐานรูปเคารพสะท้อนถึงบทบาทของบ่อพันขันในฐานะศูนย์กลางจิตวิญญาณในอดีต เพราะการประดิษฐานรูปเคารพบนฐานที่มั่นคงแข็งแรงคือการยืนยันถึงความศรัทธาที่หยั่งรากลึกในลัทธิไศวนิกายคุณค่าเชิงประวัติศาสตร์และวัสดุศาสตร์: ทั้งรางระบายน้ำหินและฐานรูปเคารพเป็นหลักฐานที่แสดงถึงทักษะ \"วัสดุศาสตร์\" ของคนโบราณที่รู้จักเลือกใช้หินทรายแดงจากบ่อพันขันมาสกัดเป็นเครื่องมือที่มีความละเอียดสูง สิ่งเหล่านี้ไม่ได้เป็นเพียงก้อนหิน แต่เป็นเครื่องมือสื่อสารทางวัฒนธรรมที่บอกเล่าถึงลำดับขั้นตอนพิธีกรรมและความรุ่งเรืองของอารยธรรมในทุ่งกุลาร้องไห้เมื่อนับพันปีก่อน', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:13:28', '245', '4', '80', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk254/2026-04-29_07-14-13_Thumb_2025-12-09_09-38-09_LINE_ALBUM_20241019-บ่อพันขัน-พระธาตุ_250703_16.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk254/2026-04-29_07-14-10_Thumb_2025-12-09_09-38-05_LINE_ALBUM_20241019-บ่อพันขัน-พระธาตุ_250703_15.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk254/2026-04-29_07-14-07_Thumb_2025-12-09_09-38-00_LINE_ALBUM_20241019-บ่อพันขัน-พระธาตุ_250703_14.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk254/2026-04-29_07-14-03_2025-12-09_09-38-17_LINE_ALBUM_20241019-บ่อพันขัน-พระธาตุ_250703_17.jpg\"]'),
('22', 'PK253', 'บึงพันขัน', 'บึงพันขัน เดิมเป็นพื้นที่ลุ่มต่ำที่มีน้ำขังตามธรรมชาติ เป็นบ่อเกลือสินเธาว์โบราณที่ตั้งอยู่ในบริเวณบ่อพันขัน (บ่อพันขัณฑ์) ต่อมามีการพัฒนาทางวิศวกรรมชลประทานโดยการสร้างฝายกั้นลำน้ำคลองปลาค้าว เพื่อกักเก็บน้ำไว้ใช้ในการเกษตรกรรมอย่างยั่งยืนในพื้นที่แห้งแล้งของทุ่งกุลาร้องไห้ จนกลายเป็นอ่างเก็บน้ำขนาดใหญ่ที่ครอบคลุมพื้นที่กว้างขวาง บึงแห่งนี้จึงเป็นจุดบรรจบระหว่างความอุดมสมบูรณ์ของน้ำตามธรรมชาติกับภูมิปัญญาการจัดการน้ำของมนุษย์สมัยใหม่ระบบนิเวศและห้องเรียนธรรมชาติ: ปัจจุบันบึงพันขันถูกขนานนามว่าเป็น \"บึงแห่งชีวิต\" เนื่องจากเป็นแหล่งอาศัยของความหลากหลายทางชีวภาพที่สูงมาก เป็นที่อยู่อาศัยของนกน้ำนานาชนิด ทั้งนกประจำถิ่นและนกอพยพ รวมถึงปลาพื้นเมืองและพืชน้ำอย่างบัวแดงและบัวสาย บึงพันขันทำหน้าที่เป็น \"ห้องเรียนธรรมชาติขนาดใหญ่\" ที่เปิดโอกาสให้นักท่องเที่ยวและเยาวชนได้มาทดลองวัดค่า pH ของน้ำ ศึกษาสิ่งมีชีวิตขนาดเล็กผ่านกล้องจุลทรรศน์ และสำรวจระบบนิเวศพื้นที่ชุ่มน้ำอย่างใกล้ชิดคุณค่าเชิงเศรษฐกิจและนันทนาการ: บึงพันขันเปรียบเสมือนเส้นเลือดใหญ่ที่หล่อเลี้ยงอาชีพประมงพื้นบ้านและการปลูกข้าวหอมมะลิในตำบลเด่นราษฎร์และพื้นที่ใกล้เคียง นอกจากประโยชน์ด้านเกษตรกรรมแล้ว บึงแห่งนี้ยังเป็นสถานที่พักผ่อนหย่อนใจที่มีทัศนียภาพงดงาม โดยเฉพาะในช่วงพระอาทิตย์ตกดินที่มีแสงสะท้อนผิวน้ำตัดกับเงาของหอคอยชมวิวและต้นจามจุรี ทำให้บึงพันขันเป็นจุดหมายปลายทางสำคัญของการท่องเที่ยวเชิงนิเวศที่สมบูรณ์ที่สุดแห่งหนึ่งในจังหวัดร้อยเอ็ด', NULL, NULL, NULL, NULL, 'เด่นราษฎร์', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:14:48', '294', '3', '92', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk253/2026-04-29_07-04-46_34EBD1DD-D858-40AB-B8DC-20D36D48A215-EDIT.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk253/2026-04-29_07-04-50_IMG_20190106_103317.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk253/2026-04-29_07-04-55_P1619150.JPG\"]'),
('23', 'PK252', 'น้ำสร่างครกคู่แฝด', 'น้ำสร่างครกคู่แฝด คือบ่อน้ำผุดที่มีลักษณะทางธรณีวิทยาและกายภาพคล้ายคลึงกับบ่อพันขันหลัก ตั้งอยู่ในบริเวณลานหินทรายแดงของลานหินต่าง ปรากฏการณ์นี้แสดงให้เห็นเฉพาะในฤดูแล้งที่น้ำในบึงพันขันได้ลดลงเท่านั้น น้ำสร่างครกนี้ สันนิษฐานว่าเป็น กุมภลักษณ์ (Pothole) ซึ่งเป็นปรากฏการณ์ทางธรณีวิทยาที่เกิดจากกระแสน้ำพัดพาเอากรวด หิน หรือทราย ลงไปปั่นวนอยู่ในแอ่งหรือรอยแตกของพื้นหิน เมื่อเวลาผ่านไปนับพันนับหมื่นปี การขัดสีของกรวดหินเหล่านั้นจะกัดเซาะพื้นหินให้ลึกและกว้างขึ้นจนมีลักษณะเป็นหลุมรูปทรงกระบอกหรือรูปชามที่เรียบเนียน คล้ายกับ \"หม้อ\" หรือ \"ครก\"น้ำสร่างครกคู่แฝดเป็นจุดเรียนรู้ที่สำคัญในเส้นทางท่องเที่ยวเชิงวิทยาศาสตร์ ช่วยให้นักท่องเที่ยวได้ศึกษาเรียนรู้ลักษณะทางธรณีวิทยา เป็นการขยายขอบเขตการสำรวจจากจุดเดียวสู่ภาพรวมของระบบนิเวศลานหินทราย ทำให้ผู้มาเยือนเข้าใจว่า \"น้ำสร่างครก\" ไม่ได้เป็นเพียงบ่อเดี่ยวๆ แต่เป็นส่วนหนึ่งของโครงสร้างทางธรรมชาติที่ยิ่งใหญ่และเชื่อมโยงกันทั่วทั้งพื้นที่', NULL, NULL, NULL, NULL, 'กู่กาสิงห์ ', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:15:09', '196', '3', '64', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk252/2026-04-29_02-24-19_IMG_0066-EDIT.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk252/2026-04-29_02-24-27_IMG_8849.JPG\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk252/2026-04-29_02-24-33_IMG_20190414_151656.jpg\"]'),
('24', 'PK249', 'ฤาษี', 'องค์ฤๅษี (ปู่ฤๅษี) พบที่ พระธาตุโนนสะอาด ตำบลดูกอึ่ง อำเภอหนองฮี จังหวัดร้อยเอ็ด ชาวบ้านนิยมกราบไหว้ เพื่อความเป็นสิริมงคลและขอพรด้านสติปัญญา การงาน และโชคลาภในความเชื่อไทย-อีสาน ฤๅษี ถือเป็นผู้ทรงศีล ผู้มีวิชา เป็นครูบาอาจารย์ฝ่ายพราหมณ์ คนจึงนิยมกราบไหว้เพื่อขอพรเกี่ยวกับความรู้ วิชา การเรียนเมตตามหานิยมการงาน ความสำเร็จป้องกันสิ่งไม่ดีเสริมดวง เสริมบารมี', NULL, NULL, '15.5513283', '104.0461378', 'ดูกอึ่ง', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '78', '1', '25', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk249/2026-04-20_10-03-14_S__35577874.jpg\"]'),
('25', 'PK248', 'พระธาตุบ้านโนนสะอาด', 'พระธาตุบ้านโนนสะอาด (พระธาตุโนนสะอาด) เป็นพระธาตุศักดิ์สิทธิ์ประจำชุมชน ตั้งอยู่ที่ บ้านโนนสะอาด หมู่ 9 ตำบลดูกอึ่ง อำเภอหนองฮี จังหวัดร้อยเอ็ด นับเป็นสถานที่สำคัญทางศาสนาที่ชาวบ้านให้ความเคารพศรัทธามาอย่างยาวนานพระธาตุแห่งนี้ถือเป็น พระธาตุประจำหมู่บ้าน ที่ประชาชนในพื้นที่และผู้ที่เดินทางผ่านไปมา มักเข้ามาสักการะเพื่อ ขอพรและความเป็นสิริมงคล อีกทั้งยังเป็นศูนย์รวมจิตใจของชุมชน และเป็นสถานที่หลักในการจัดกิจกรรมทางพระพุทธศาสนา รวมถึงประเพณีสำคัญของตำบลดูกอึ่งนอกจากนี้ พระธาตุบ้านโนนสะอาดยังเป็นสถานที่จัดงานบุญประจำปีของชุมชน เช่น งานสรงน้ำพระธาตุ ซึ่งจัดขึ้นเป็นประจำ เพื่อสืบสานวัฒนธรรมและความศรัทธาทางพระพุทธศาสนา', NULL, NULL, '15.5513283', '104.0461378', 'ดูกอึ่ง', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '136', '4', '49', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk248/2026-04-20_09-40-18_S__35577869_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk248/2026-04-20_09-40-21_S__35577870_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk248/2026-04-20_09-42-26_S__35577868_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk248/2026-04-20_09-42-22_S__35577867_0.jpg\"]'),
('26', 'PK247', 'พระพุทธรัตนมหามงคลศรีศากยมุนี วัดดูกอึ่ง', 'พระพุทธรัตนมหามงคลศรีศากยมุนี วัดดูกอึ่ง เป็นพระพุทธรูปองค์ใหญ่ที่ประดิษฐานอยู่ภายใน วัดดูกอึ่ง ซึ่งเป็นอีกหนึ่งสถานที่สำคัญของชุมชนในพื้นที่จังหวัดร้อยเอ็ดพระใหญ่ถือเป็นจุดศูนย์รวมศรัทธาของชาวบ้านและผู้ที่เดินทางผ่านไปมา โดยมักเข้ามา กราบไหว้ขอพร ทำบุญ และปิดทอง เพื่อความเป็นสิริมงคลในชีวิต ทั้งด้านสุขภาพ การงาน และครอบครัว', '08:00:00', '18:00:00', '15.5739292', '104.0240634', 'ดูกอึ่ง', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '70', '3', '28', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk247/2026-04-20_09-13-01_S__35569672_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk247/2026-04-20_09-13-04_S__35569673_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk247/2026-04-20_09-13-08_S__35569674_0.jpg\"]'),
('27', 'PK246', 'วัดดูกอึ่ง', 'วัดดูกอึ่ง ตั้งอยู่ใน ตำบล ดูกอึ่ง อำเภอหนองฮี จังหวัดร้อยเอ็ด ป็น วัดราษฎร์ ประจำชุมชนดูกอึ่ง ที่ชาวบ้านในละแวกนั้นใช้เป็นศูนย์กลางทางศาสนาและกิจกรรมชุมชน โดยพระใหญ่นั้นมักเป็นหนึ่งในพระพุทธรูปองค์สำคัญที่ผู้คนเคารพบูชาและมากราบไหว้เพื่อความเป็นสิริมงคล', '08:00:00', '18:00:00', '15.5742485', '104.0241879', 'ดูกอึ่ง', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '55', '1', '19', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk246/2026-04-20_09-10-13_S__35569679.jpg\"]'),
('28', 'PK245', 'สมเด็จพระพุฒาจารย์ (โต พฺรหฺมรํสี)', 'รูปเคารพ สมเด็จพระพุฒาจารย์ (โต พฺรหฺมรํสี) ที่ประดิษฐานอยู่ใน วัดสระโพธิ์ (หนองฮี) จังหวัดร้อยเอ็ดสมเด็จพระพุฒาจารย์ (โต พรหมรังสี) นับเป็นพระมหาเถระผู้มีบทบาทสำคัญในประวัติศาสตร์พระพุทธศาสนาไทยยุครัตนโกสินทร์ตอนต้น ถึงกลางรัชสมัย มีชื่อเสียงทั้งด้านวัตรปฏิบัติ ความแตกฉานในพระธรรมวินัย และบทบาทด้านการเผยแผ่ธรรมะสู่สาธารณชน ท่านเกิดเมื่อวันที่ 17 เมษายน พ.ศ. 2331 ณ บ้านไก่จ้น หรือบ้านท่าหลวง อำเภอท่าเรือ จังหวัดพระนครศรีอยุธยา ในสมัยรัชกาลที่ 1 ต่อมาได้บรรพชาเมื่อ พ.ศ. 2343 และอุปสมบทใน พ.ศ. 2350 ซึ่งถือเป็นช่วงเวลาที่พระพุทธศาสนาอยู่ในระยะฟื้นฟูหลังการเสียกรุงศรีอยุธยาไม่นานบุคลิกของท่านมีลักษณะโดดเด่นคือความเรียบง่าย ไม่ยึดติดในยศตำแหน่งทางคณะสงฆ์ ทั้งยังปฏิเสธการเข้าสอบเปรียญธรรม แม้จะมีความรู้ทางพระพุทธศาสนาลึกซึ้งเป็นพิเศษ ในรัชกาลที่ 3 แม้มีพระราชประสงค์จะสถาปนาท่านเป็นพระราชาคณะ ท่านก็ยังปฏิเสธและคงสถานะเป็นเพียงพระมหาโตตลอดรัชกาล ซึ่งสะท้อนเจตคติที่มุ่งเน้นการปฏิบัติและการเผยแผ่ธรรมะมากกว่าการยอมรับตำแหน่งเชิงสถาบันเมื่อเข้าสู่รัชกาลที่ 4 พระบาทสมเด็จพระจอมเกล้าเจ้าอยู่หัวทรงมีพระราชศรัทธาในพระปฏิปทาของท่าน จึงโปรดเกล้าฯ แต่งตั้งให้เป็นพระราชาคณะที่ “พระธรรมกิติ” พร้อมทั้งให้ดำรงตำแหน่งเจ้าอาวาสวัดระฆังโฆสิตารามในช่วงเวลาที่ท่านมีอายุ 65 ปี ต่อมาท่านได้รับการเลื่อนเป็นพระเทพกระวีในปี พ.ศ. 2397 และในปี พ.ศ. 2407 ได้รับสถาปนาเป็นสมเด็จพระพุฒาจารย์ ซึ่งเป็นสมณศักดิ์สูงสุดของคณะสงฆ์ไทยในเวลานั้น ราชทินนามที่จารึกในหิรัญบัฏสะท้อนเกียรติคุณด้านพระไตรปิฎก ความบริสุทธิ์แห่งศีลาจารวัตร และบทบาทผู้นำสงฆ์ในระดับสูงสุดของยุคสมัยในช่วงบั้นปลายชีวิต ท่านมีบทบาทสำคัญด้านปูชนียสถาน โดยเป็นประธานในการริเริ่มก่อสร้างพระพุทธรูปหลวงพ่อโต หรือพระศรีอริยเมตไตรย ณ วัดอินทรวิหาร ซึ่งเป็นหนึ่งในพุทธศิลป์สำคัญแห่งกรุงรัตนโกสินทร์ อย่างไรก็ตาม การก่อสร้างยังไม่แล้วเสร็จ โดยทำได้ถึงระดับพระนาภีก่อนที่ท่านจะมรณภาพเมื่อวันที่ 22 มิถุนายน พ.ศ. 2415 บนศาลาเก่าของวัดอินทรวิหาร รวมอายุได้ 84 ปี พรรษา 64 และดำรงตำแหน่งเจ้าอาวาสวัดระฆังโฆสิตารามรวม 20 ปีภายหลังมรณภาพ สมเด็จพระพุฒาจารย์ (โต พรหมรังสี) ได้รับการยกย่องอย่างกว้างขวางทั้งในฐานะนักปราชญ์ทางพุทธศาสนา พระปฏิบัติดีปฏิบัติชอบ และครูบาอาจารย์ผู้เป็นที่เคารพของพุทธศาสนิกชนไทย นอกจากนี้ ความเชื่อเกี่ยวกับบทบาทของท่านในฐานะพระเถระผู้มีเมตตาและศักดิ์สิทธิ์ยังแพร่หลายสู่ทุกภูมิภาค และสืบทอดผ่านพุทธศิลป์', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '485', '3', '147', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk245/2026-04-20_08-34-25_S__26107944_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk245/2026-04-20_08-34-29_S__26107945_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk245/2026-04-20_08-34-32_S__26107946_0.jpg\"]'),
('29', 'PK243', 'วัดสระโพธิ์', 'วัดสระโพธิ์ ตั้งอยู่ที่ตำบลหนองฮี อำเภอหนองฮี จังหวัดร้อยเอ็ด เป็นวัดราษฎร์ในพื้นที่ภาคอีสาน ซึ่งทำหน้าที่เป็นศูนย์กลางทางจิตใจของชุมชนภายในหมู่บ้าน ภายในวัดมีทั้งศาลาการเปรียญ พระอุโบสถ และลานกิจกรรมสำหรับประกอบพิธีกรรมทางพระพุทธศาสนา ชาวบ้านจะมาทำบุญและร่วมกิจกรรมสำคัญต่าง ๆ เป็นประจำ เช่น การตักบาตร การฟังธรรม การทำบุญในวันพระ และประเพณีประจำปีของท้องถิ่น', '08:00:00', '18:00:00', '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '77', '2', '27', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk243/2026-04-20_08-21-10_S__35553302.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk243/2026-04-20_08-21-14_S__35553309_0.jpg\"]'),
('30', 'PK242', 'พระมหาธาตุเจดีย์ศรีทศพลญาณเฉลิมราชชัยมงคล วัดป่าทุ่งกุลาเฉลิมราช', 'พระมหาธาตุเจดีย์ศรีทศพลญาณเฉลิมราชชัยมงคล ตั้งอยู่ภายในวัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด ได้รับการก่อสร้างขึ้นเพื่อเป็นสถานที่ประดิษฐานพระบรมสารีริกธาตุ ซึ่งสมเด็จพระญาณสังวร สมเด็จพระสังฆราช สกลมหาสังฆปรินายก ได้พระราชทานเมื่อวันที่ 19 พฤษภาคม พ.ศ. 2550 ทั้งนี้เพื่อให้พุทธศาสนิกชนและพุทธบริษัทได้มีโอกาสสักการบูชา องค์พระมหาธาตุเจดีย์ออกแบบเป็นสถาปัตยกรรมแบบเดียวกับพระธาตุพนม โดยมีขนาดฐานกว้าง 9.9 x 9.9 เมตร และมีความสูง 54 เมตร โดดเด่นด้วยรูปทรงที่สง่างามและมีคุณค่าทางศิลปวัฒนธรรมสถานที่แห่งนี้ทำหน้าที่เป็นศูนย์กลางสำหรับการปฏิบัติวิปัสสนากรรมฐาน และเป็นแหล่งสำคัญในการเผยแผ่พระพุทธศาสนาแก่พุทธศาสนิกชน', '08:00:00', '18:00:00', '15.4857543', '103.4726203', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '144', '3', '49', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk242/2026-04-10_17-02-55_S__5955590_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk242/2026-04-10_17-02-59_S__5955591_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk242/2026-04-10_17-03-03_S__5955592_0.jpg\"]'),
('31', 'PK240', 'พระพุทธเจ้ากกุสันโธ วัดป่าทุ่งกุลา', 'พระพุทธเจ้ากกุสันโธ ประดิษฐานภายในวัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ดพระกกุสันธพุทธเจ้า หรือพระกกุสันโธ เป็นพระพุทธเจ้าองค์แรกในจำนวนห้าพระองค์แห่งภัทรกัป ทรงตรัสรู้ในยุคที่อายุมนุษย์โดยเฉลี่ยประมาณ 40,000 ปี ทรงประสูติในตระกูลพราหมณ์ ณ เมืองเขมนคร และนับเป็นพระพุทธเจ้าลำดับที่ 22 ตามพุทธวงศ์ โดยมี “ไก่” เป็นสัญลักษณ์ประจำพระองค์สาระสำคัญเกี่ยวกับพระกกุสันธพุทธเจ้าสถานที่ตรัสรู้: ใต้ต้นนิโครธ (ต้นไทร)พุทธบิดา–พุทธมารดา: พระอัคคิทัตตพราหมณ์ และพระวิสาขาพราหมณีคติความเชื่อสำคัญ: ทรงเพิกภพทั้งปวง ทำที่สุดแห่งจริยา และทำลายกิเลสดุจราชสีห์ทำลายกรงความสำคัญทางพุทธศาสนา: เป็นผู้เปิดยุคภัทรกัป เป็นพระพุทธเจ้าพระองค์แรกในกัปปัจจุบัน', '08:00:00', '18:00:00', '15.4858327', '103.4728555', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '151', '2', '49', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk240/2026-04-10_16-51-16_S__35487821_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk240/2026-04-10_16-51-24_IMG_1396.JPG\"]'),
('32', 'PK239', 'พระพุทธเจ้าโกนาคมโน วัดป่าทุ่งกุลา', 'พระพุทธเจ้าโกนาคมโน ที่ประดิษฐานใน วัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด คือพระพุทธรูปที่แทน พระโกนาคมนพุทธเจ้า ถือเป็นพระพุทธเจ้า ลำดับที่ 2 ซึ่งเป็นหนึ่งใน พระพุทธเจ้าห้าพระองค์ในภัทรกัป ตามคติพุทธศาสนาเถรวาทพระพุทธเจ้าโกนาคมโน (โกนาคมนพุทธเจ้า) เป็นหนึ่งในพระพุทธเจ้าตามคติพระพุทธศาสนาเถรวาท ซึ่งปรากฏในคัมภีร์พุทธวงศ์ โดยมีรายละเอียดสำคัญดังนี้ข้อมูลทั่วไปของพระพุทธเจ้าโกนาคมโนพระนาม: พระโกนาคมนพุทธเจ้าลำดับ: เป็นพระพุทธเจ้าลำดับที่ 2 แห่งภัทรกัปจำนวนพระพุทธเจ้าทั้งหมดในภัทรกัป: 5 พระองค์ ได้แก่พระกกุสันธพุทธเจ้าพระโกนาคมนพุทธเจ้าพระกัสสปพุทธเจ้าพระโคตมพุทธเจ้า (องค์ปัจจุบัน)พระศรีอารยเมตไตรย (อนาคต)พระประวัติและคุณลักษณะสำคัญการบำเพ็ญบารมี: ทรงบำเพ็ญบารมี 10 ประการจนสมบูรณ์ก่อนการตรัสรู้พุทธพยากรณ์: ได้รับพยากรณ์ว่าจะเป็นพระพุทธเจ้าจากพระพุทธเจ้าองค์ก่อนหน้าในชาติที่ยังเป็นผู้บำเพ็ญเพียรสถานที่ประสูติ: เมืองโกนาคมนครวงศ์ตระกูล: ประสูติในวงศ์พราหมณ์พระชายา: พระนางโรหิณีพระโอรส: พระวชิตตวุทธิระยะเวลาตรัสรู้: ภายใต้ควงไม้มะเดื่อพระชนมายุ: ประมาณ 30,000 ปีการประกาศพระธรรม: ทรงแสดงปฐมเทศนาแก่ภิยโยสราชกุมารและอุดรราชกุมาร พร้อมบริวารจำนวนมาก', '08:00:00', '18:00:00', '15.4858327', '103.4728555', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '251', '2', '77', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk239/2026-04-10_16-45-33_S__35487819_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk239/2026-04-10_16-45-39_IMG_1396.JPG\"]'),
('33', 'PK238', 'พระพุทธเจ้ากัสสโป วัดป่าทุ่งกุลา', 'พระพุทธเจ้ากัสสโป วัดป่าทุ่งกุลา พระพุทธเจ้ากัสสโป เป็นหนึ่งใน พระพุทธเจ้าห้าพระองค์ในภัทรกัป ตามคติพุทธศาสนาเถรวาท เป็นพระพุทธเจ้าลำดับที่ 3 ในภัทรกัปตรัสรู้ก่อนพระโคตมพุทธเจ้า และเป็นหนึ่งในพระพุทธเจ้าที่มีการกล่าวถึงในพระไตรปิฎก พระกัสสปพุทธเจ้าเป็นพระพุทธเจ้าองค์ที่ 3 ในภัทรกัป ตรัสรู้ถัดจากพระโกนาคมนพุทธเจ้า ทรงประสูติในตระกูลพราหมณ์ ณ เมืองพาราณสี และครองเพศฆราวาสอยู่ถึง 2,000 ปี ก่อนเสด็จออกผนวช บำเพ็ญเพียรเพียง 7 วันก็ตรัสรู้เป็นพระสัมมาสัมพุทธเจ้า พระองค์เคยพยากรณ์ว่า “โชติปาลมานพ” ซึ่งภายหลังคือพระโคตมพุทธเจ้า จะได้ตรัสรู้เป็นพระพุทธเจ้าในอนาคตกาลสรุปประวัติโดยย่อของพระกัสสปพุทธเจ้าช่วงเวลา: ตรัสรู้หลังสิ้นพระศาสนาของพระโกนาคมนพุทธเจ้าพุทธบิดา–พุทธมารดา: พรหมทัตพราหมณ์ และนางธนวดีพราหมณีพระมเหสีและโอรส: พระนางสุนันทาพราหมณี และพระโอรสวิชิตเสนการออกผนวช: เสด็จออกบรรพชาหลังเห็นนิมิต 4 ประการ โดยเสด็จออกด้วยยานช้างระยะเวลาบำเพ็ญเพียร: 7 วันการตรัสรู้: ณ ควงไม้โพธิ์พฤกษ์นิโครธ (ต้นไทร)', '08:00:00', '18:00:00', '15.4858327', '103.4728555', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '205', '3', '67', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk238/2026-04-10_16-27-26_S__35487818_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk238/2026-04-10_16-27-32_IMG_1396.JPG\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk238/2026-04-10_16-46-45_S__35487820_0.jpg\"]'),
('34', 'PK237', 'พระพุทธเจ้าโคตโม วัดป่าทุ่งกุลา', 'พระพุทธเจ้าโคตโม หนึ่งในพระพุทธเจ้าห้าพระองค์ ที่ประดิษฐานในวัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด คือพระพุทธรูปที่แทน พระสัมมาสัมพุทธเจ้าองค์ปัจจุบัน หรือ พระโคตมพุทธเจ้า (พระพุทธเจ้าพระนามว่า “โคตมะ”) ตามความเชื่อในพุทธศาสนา พระโคตมพุทธเจ้า หรือพระสัมมาสัมพุทธเจ้าพระองค์ปัจจุบัน เป็นศาสดาของพระพุทธศาสนา ทรงประสูติเป็นกษัตริย์ศากยวงศ์ ณ กรุงกบิลพัสดุ์ พระนามเดิมว่า “สิทธัตถะ” และได้ตรัสรู้ ณ โคนต้นศรีมหาโพธิ์เมื่อพระชนมายุ 35 พรรษา ก่อนจะประกาศพระธรรมคำสอนและสถาปนาพระพุทธศาสนาจนสิ้นพระชนม์เมื่ออายุ 80 พรรษาประวัติโดยสรุปของพระโคตมพุทธเจ้าพระนาม: พระโคตมพุทธเจ้า หรือ สมณโคดม; นามกำเนิดคือ เจ้าชายสิทธัตถะพระชาติกำเนิด: ประสูติในลุมพินีวัน (ปัจจุบันอยู่ในประเทศเนปาล) พระราชโอรสของพระเจ้าสุทโธทนะ และพระนางสิริมหามายา แห่งแคว้นศากยะการออกผนวช: หลังทรงพบพุทธนิมิตหรือเทวทูต 4 ประการ (คนแก่ คนเจ็บ คนตาย สมณะ) จึงทรงละเพศฆราวาสเมื่ออายุ 29 พรรษา เพื่อตามหาหนทางพ้นทุกข์การตรัสรู้: ทรงทดลองบำเพ็ญทุกกรกิริยาเป็นเวลา 6 ปี ก่อนเปลี่ยนมาบำเพ็ญเพียรทางจิตอย่างถูกทาง และตรัสรู้เป็นพระสัมมาสัมพุทธเจ้าภายใต้ต้นศรีมหาโพธิ์ ในวันวิสาขบูชาพระธรรมคำสอนหลัก: อริยสัจ 4 อันประกอบด้วย ทุกข์ สมุทัย นิโรธ และมรรค เป็นแก่นธรรมแห่งการดับทุกข์และการหลุดพ้นจากวัฏสงสารการปรินิพพาน: ทรงประกาศพระธรรมเป็นเวลา 45 ปี ก่อนเสด็จดับขันธปรินิพพาน ณ สาลวโนทยาน เมืองกุสินารา เมื่อพระชนมายุ 80 พรรษาพระโคตมพุทธเจ้าได้รับการนับถือว่าเป็นพระพุทธเจ้าองค์ที่ 4 ในภัทรกัป และเป็นผู้สถาปนาพระพุทธศาสนาที่สืบทอดถึงปัจจุบัน', '08:00:00', '18:00:00', '15.4858327', '103.4728555', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '319', '2', '97', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk237/2026-04-10_16-24-27_S__35487817_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk237/2026-04-10_16-24-34_IMG_1396.JPG\"]'),
('35', 'PK236', 'หลวงพ่อทันใจ วัดป่าทุ่งกุลา', 'หลวงพ่อทันใจ วัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ดผู้คนมักไปกราบไหว้ นิยมขอพรเรื่องโชคลาภ การเงิน การค้าขาย และงาน', '08:00:00', '18:00:00', '15.4861432', '103.4724958', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '33', '3', '17', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk236/2026-04-10_16-18-12_S__35487809_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk236/2026-04-10_16-18-15_S__35487810_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk236/2026-04-10_16-18-19_S__35487811_0.jpg\"]'),
('36', 'PK235', 'องค์นาคพันธ์ปริวัตรนาคราช วัดป่าทุ่งกุลา', 'องค์นาคพันธ์ปริวัตรนาคราช ประดิษฐานภายในวัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ดท้าวนาคพันธ์ปริวัตร เป็นพญานาคในวรรณะนาคราช ผู้ครองนครหริหราลัยในภูมิทิพย์ ซึ่งเชื่อว่าเป็นภพภูมิซ้อนทับกับเมืองหริหราลัย เมืองหลวงของอาณาจักรเจนละที่สร้างขึ้นในสมัยพระเจ้าชัยวรมันที่ 2 ดังนั้นท้าวนาคพันธ์จึงถือว่ามีอายุยืนยาวตั้งแต่ยุคนั้นมาจนถึงปัจจุบันหลักฐานที่มักถูกกล่าวถึงว่าเกี่ยวข้องกับการมีอยู่ขององค์นาคพันธ์ คือปราสาท “นาคพัน” หรือ “เนียกปวน” (Neak Pean) ซึ่งสร้างขึ้นในสมัยพระเจ้าชัยวรมันที่ 7 ปราสาทแห่งนี้มีลักษณะโดดเด่นไม่เหมือนปราสาทอื่น ๆ ในยุคเดียวกัน เพราะตั้งอยู่กลางสระน้ำขนาดใหญ่ จึงมีความเชื่อมโยงกับเรื่องราวของพญานาคและน้ำในเชิงสัญลักษณ์ตำนานเล่าว่า ท้าวนาคพันธ์ปริวัตรเกิดแบบโอปปาติกะ เกิดขึ้นด้วยอานุภาพของพระฮะริฮะรา ซึ่งเป็นภาครวมของพระศิวะและพระนารายณ์ โดยแบ่งเสี้ยวจิตของพระองค์เป็นพลังตั้งต้น ทำให้นาคพันธ์มีสายสืบเชื้อทางจิตวิญญาณจากทั้งพระศิวะและพระนารายณ์โดยตรง จึงถือเป็นดั่ง “จิตตเทวะ” แห่งพระฮะริฮะราในภพภูมิพญานาคตำนานยังระบุว่า องค์นาคพันธ์ได้รับการกำหนดให้ทำหน้าที่เกี่ยวข้องกับพระพุทธศาสนา และสั่งสมบารมีเพื่อภารกิจสำคัญในยุคของพระศรีอาริยเมตไตรยในอนาคต', '08:00:00', '18:00:00', '15.4859947', '103.4728662', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '246', '2', '76', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk235/2026-04-10_16-14-42_S__35487803.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk235/2026-04-10_16-14-47_S__35487804.jpg\"]'),
('37', 'PK234', 'รอยพระพุทธบาท วัดป่าทุ่งกุลา', 'รอยพระพุทธบาท ภายในวัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ดรอยพระพุทธบาท เป็นสัญลักษณ์แทนองค์พระสัมมาสัมพุทธเจ้า มักพบเป็นรอยประทับบนแผ่นหินตามภูเขา เชื่อว่าเป็นเครื่องหมายแห่งการเผยแผ่ศาสนาและสิริมงคล มีทั้งรูปแบบรอยจำลองและรอยธรรมชาติที่ศักดิ์สิทธิ์', '08:00:00', '18:00:00', '15.4860981', '103.472618', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '62', '3', '26', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk234/2026-04-10_16-11-46_S__35487799_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk234/2026-04-10_16-11-50_S__35487800_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk234/2026-04-10_16-11-53_S__35487815.jpg\"]'),
('38', 'PK233', 'หอพระอุปคุต วัดป่าทุ่งกุลา', 'หอพระอุปคุต ภายในวัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ดพระอุปคุต หรือ พระอุปคุปต์ เป็นพระอรหันต์สำคัญในยุคหลังพุทธกาล โดยเฉพาะในสมัยพระเจ้าอโศกมหาราช ท่านเป็นที่รู้จักในฐานะพระอรหันต์ผู้ทรงฤทธิ์ มีบทบาทในการปกป้องพระพุทธศาสนา และได้รับความเคารพอย่างกว้างขวางในดินแดนสุวรรณภูมิคุณลักษณะและเรื่องราวสำคัญของพระอุปคุตพระอรหันต์ปราบมาร: ตามตำนาน ท่านเป็นผู้ปราบพญามารที่พยายามขัดขวางพิธีฉลองพระเจดีย์ 84,000 องค์ของพระเจ้าอโศกมหาราชพำนักใต้สะดือทะเล: เชื่อว่าท่านจำศีลอยู่ในกุฏิแก้วกลางมหาสมุทร เป็นพระผู้สงบสำรวมและหลีกเร้นจากโลกมนุษย์ประเพณีตักบาตรเที่ยงคืน (เป็งปุ๊ด): ตามความเชื่อล้านนา พระอุปคุตจะอุบัติขึ้นมาในรูปเณรน้อยในคืนวันเพ็ญพุธ ผู้ที่ได้ใส่บาตรจะได้รับความเป็นสิริมงคลและโชคลาภนามเรียก “พระบัวเข็ม”: ในไทยและพม่า นิยมเรียกพระอุปคุตปางจกบาตรว่า “พระบัวเข็ม” เชื่อว่าท่านคุ้มครองป้องกันภัยและนำความมั่งคั่งมาสู่ผู้บูชาพุทธคุณเด่นด้านโชคลาภ การงาน การเงินเสริมเมตตามหานิยมคุ้มครองป้องกันอันตรายช่วยขจัดอุปสรรคและภยันตรายต่าง ๆ', '08:00:00', '18:00:00', '15.486344', '103.4729649', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '215', '2', '67', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk233/2026-04-10_15-58-27_S__13287445_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk233/2026-04-10_15-58-31_S__13287446_0.jpg\"]'),
('39', 'PK232', 'พระสีวลี วัดป่าทุ่งกุลา', 'พระสีวลี ประดิษฐานภายในวัดป่าทุ่งกุลาเฉลิมราช บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด ระสีวลีเถระ เป็นพระอรหันต์สำคัญในสมัยพุทธกาล ผู้ได้รับการถวายสรรเสริญจากพระพุทธเจ้าว่าเป็น เอตทัคคะในทางผู้มีลาภมาก จึงได้รับการยกย่องว่าเป็นสัญลักษณ์แห่งความอุดมสมบูรณ์ โชคลาภ และความเจริญรุ่งเรือง ผู้คนนิยมบูชาเพื่อเสริมสิริมงคลด้านทรัพย์ การงาน และความก้าวหน้าในชีวิตประวัติและความสำคัญของพระสีวลีบุพกรรมและการสั่งสมบุญพระสีวลีได้ประกอบกุศลและทำทานมาอย่างต่อเนื่องในหลายชาติ โดยเฉพาะการอุปัฏฐากพระพุทธเจ้าในอดีต ผลบุญทำให้ท่านเป็นที่รักของมนุษย์และเทวดา ไปสู่ที่ใดก็มักได้รับลาภสักการะ แม้ในพื้นที่กันดารการบวชและการบรรลุธรรมท่านเป็นโอรสของพระนางสุปปวาสา แห่งโกลิยวงศ์ เข้าบรรพชาในสำนักของพระสารีบุตร และบรรลุพระอรหันต์ขณะปลงผม ถือเป็นผู้มีบารมีสูงตั้งแต่เริ่มต้นชีวิตทางธรรมลักษณะปางบูชารูปเคารพพระสีวลีมักสร้างเป็นรูปพระธุดงค์ถือร่มกลด สะพายบาตร หรือปางจกบาตร สื่อถึงความอุดมสมบูรณ์และโชคลาภที่หลั่งไหลไม่ขาดสายชาวพุทธเชื่อว่าการบูชาพระสีวลีทำให้เกิดความสำเร็จด้านการเงิน โชคลาภ การค้าขาย และช่วยให้การเดินทางราบรื่นปลอดภัย', '08:00:00', '18:00:00', '15.4863414', '103.4729645', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '223', '2', '69', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk232/2026-04-10_15-52-16_S__13287440_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk232/2026-04-10_15-52-20_S__13287441_0.jpg\"]'),
('40', 'PK231', 'ธนบดินทร์นาคา วัดป่าทุ่งกุลา', 'ธนบดินทร์นาคา ประดิษฐานภายในวัดป่าทุ่งกุลา บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด องค์เจ้าหล้าธนบดินทร์ศรีสัตตะนาคราช เป็นพระนามของพญานาคผู้สูงศักดิ์ที่ปรากฏในความเชื่อเรื่องพญานาค 7-9 พระองค์ ซึ่งผู้ศรัทถามักบูชาเพื่อขอความสำเร็จ ทรัพย์สิน และบารมี เชื่อว่าเป็นพญานาคราชที่ปกครองเมืองบาดาล มีความสง่างาม และมักถูกกล่าวถึงร่วมกับพระนางมณีจันทราฯ ในหมู่ผู้ศรัทธาบริบทการบูชา: เป็นที่เคารพในด้านความอุดมสมบูรณ์และทรัพย์บารมี', '08:00:00', '18:00:00', '15.4863414', '103.4729645', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '95', '2', '33', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk231/2026-04-10_15-36-58_S__13287435_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk231/2026-04-10_15-37-01_S__13287436_0.jpg\"]'),
('41', 'PK230', 'พระศรีอริยเมตไตรโย วัดป่าทุ่งกุลา', 'พระศรีอริยเมตไตรโย ประดิษฐานภายในวัดป่าทุ่งกุลา บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นหนึ่งใน พระพุทธเจ้าห้าพระองค์ โดย “พระศรีอริยเมตไตรโย” หมายถึง พระพุทธเจ้าในอนาคต ตามความเชื่อในพุทธศาสนาพระศรีอริยเมตไตรย หรือที่คนไทยรู้จักในชื่อ “พระศรีอาริย์” เป็นพระโพธิสัตว์ผู้กำลังบำเพ็ญบารมีในสวรรค์ชั้นดุสิต และได้รับการยกย่องว่าเป็นพระพุทธเจ้าองค์ที่ 5 และองค์สุดท้ายแห่งภัทรกัป ตามหลักพุทธศาสนาเถรวาท เชื่อว่าพระองค์จะอุบัติขึ้นเมื่อพระศาสนาของพระโคตมพุทธเจ้าเสื่อมสิ้นจากโลก และจะทรงฟื้นฟูพระธรรมให้รุ่งเรืองสว่างไสวอีกครั้งตามคำอธิบายในคัมภีร์ พระศรีอริยเมตไตรยจะลงมาตรัสรู้ในยุคที่มนุษย์มีอายุยืนประมาณแปดหมื่นปี สังคมในยุคนั้นจะสงบสุข คนมีเมตตา ไม่เบียดเบียนกัน บ้านเมืองอุดมสมบูรณ์ ไม่มีสงครามหรือความขัดแย้ง ผู้คนใช้ชีวิตด้วยสัจจะและศรัทธาในธรรม ตรงตามพระนาม “เมตไตรย” ซึ่งแปลว่า ความเมตตา กรุณา และความปรารถนาดี', '08:00:00', '18:00:00', '15.4858327', '103.4728555', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '184', '1', '56', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk230/2026-04-10_15-06-32_S__35487791.jpg\"]'),
('42', 'PK229', 'วัดป่าทุ่งกุลา', 'วัดป่าทุ่งกุลา ตั้งอยู่ที่ บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด วัดป่าทุ่งกุลาเฉลิมราช ตั้งอยู่เลขที่ 5 หมู่ที่ 5 บ้านโพนตูม ตำบลทุ่งทอง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด พื้นที่เดิมเป็นสันดอนขนาดใหญ่หลายร้อยไร่ มีลักษณะเป็นป่าโปร่ง ชาวบ้านเรียกกันว่า “ดอนหนามแท่ง” หรือ “โนนหนามแท่ง” ซึ่งเป็นเขตป่าธรรมชาติอันอุดมสมบูรณ์ แต่ไม่มีหน่วยงานดูแลอย่างชัดเจน ต่อมาประมาณปี พ.ศ. 2529 ชาวบ้านในพื้นที่เริ่มกังวลว่าจะมีผู้เข้ามาบุกรุกสันดอนผืนนี้ จึงร่วมกันปรึกษาหารือและเดินทางไปกราบเรียนพระศีลวิสุทธาจารย์ เจ้าคณะจังหวัดร้อยเอ็ด (ธรรมยุต) ณ วัดบึงพระลานชัย เพื่อขอความเมตตาช่วยดูแลรักษาพื้นที่เมื่อพระศีลวิสุทธาจารย์ได้รับทราบ จึงเมตตรารับพื้นที่ดังกล่าวไว้ในความดูแล พร้อมตั้งเจตนารมณ์ชัดเจนว่าจะพัฒนาให้เป็น “ป่าถาวรเฉลิมพระเกียรติพระบาทสมเด็จพระเจ้าอยู่หัว” และจัดตั้งให้เป็นวัดป่าสังกัดคณะธรรมยุต ซึ่งจะมีบทบาททั้งด้านการอนุรักษ์ป่าไม้ การปฏิบัติธรรม และการสืบทอดพระพุทธศาสนาอย่างเข้มแข็งในวันที่ 5 ธันวาคม พ.ศ. 2530 ตรงกับวันเฉลิมพระชนมพรรษา 60 พรรษาของพระบาทสมเด็จพระเจ้าอยู่หัวฯ พระศีลวิสุทธาจารย์ได้เริ่มดำเนินการก่อสร้างวัดเป็นปฐมฤกษ์ พร้อมทั้งได้รับความเห็นชอบให้ตั้งชื่อว่า “วัดป่าทุ่งกุลาเฉลิมราช” เพื่อเป็นสิริมงคลและสื่อถึงทำเลที่ตั้งซึ่งอยู่ในบริเวณทุ่งกุลาร้องไห้ ผืนดินประวัติศาสตร์ของภาคตะวันออกเฉียงเหนือวัดป่าทุ่งกุลาเฉลิมราชมีความโดดเด่นในฐานะวัดป่าสายธรรมยุต เน้นการปฏิบัติวิปัสสนากรรมฐานอย่างเคร่งครัด และยังเป็นศูนย์กลางการฟื้นฟูผืนป่าธรรมชาติในพื้นที่ทุ่งกุลาร้องไห้ให้กลับมามีความอุดมสมบูรณ์ วัดตั้งอยู่ท่ามกลางบรรยากาศเงียบสงบ ล้อมรอบด้วยป่าไม้ จึงเหมาะแก่การภาวนาเป็นอย่างยิ่ง นอกจากนี้ วัดยังทำหน้าที่เป็นศูนย์อบรมปฏิบัติธรรมแก่ประชาชนจากหลายจังหวัด และเป็นแหล่งเรียนรู้เรื่องการอยู่ร่วมกับธรรมชาติภายในวัดมีสิ่งก่อสร้างสำคัญ ได้แก่ พระมหาธาตุเจดีย์ศรีทศพลญาณเฉลิมราชชัยมงคล สร้างขึ้นเพื่อประดิษฐานพระบรมสารีริกธาตุที่สมเด็จพระญาณสังวรได้ประทานให้ เพื่อเป็นที่สักการบูชาของพุทธศาสนิกชน และเป็นศูนย์รวมจิตใจของชุมชนโดยรอบ นอกจากนี้ยังมีศาลาปฏิบัติธรรม เสนาสนะสำหรับพระสงฆ์ และพื้นที่ป่าธรรมชาติที่ได้รับการอนุรักษ์อย่างต่อเนื่องวัดป่าทุ่งกุลาเฉลิมราชจึงเป็นทั้งศูนย์กลางการภาวนาและการทำนุบำรุงพระพุทธศาสนา รวมทั้งเป็นแบบอย่างของวัดที่ผสานการอนุรักษ์ป่าไม้เข้ากับการปฏิบัติธรรมได้อย่างลงตัว พร้อมทำหน้าที่เป็นแหล่งศรัทธาของประชาชนในพื้นที่ทุ่งกุลาร้องไห้และจังหวัดใกล้เคียงอย่างยั่งยืน', '08:00:00', '18:00:00', '15.485612', '103.4755054', 'ทุ่งทอง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '493', '3', '149', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk229/2026-04-10_15-01-03_S__13287454_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk229/2026-04-10_15-01-07_S__35487788.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk229/2026-04-10_15-01-11_S__9625607.jpg\"]'),
('43', 'PK226', 'วัดบุบผาราม บ้านดอกรักน้อย', 'วัดบุปผาราม (บ้านดอกรักน้อย) ตั้งอยู่ในตำบลกำแพง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นวัดสำคัญประจำชุมชนที่มีบทบาททั้งด้านศาสนาและวัฒนธรรมพื้นบ้านของชาวอีสาน วัดแห่งนี้เป็นสถานที่ที่ชาวบ้านมารวมตัวทำกิจกรรมบุญประเพณีตลอดทั้งปี โดยเฉพาะงาน “ปริวาสกรรม” หรือที่ชาวบ้านเรียกกันว่า “เปิดป่า” ซึ่งจัดขึ้นในช่วงเดือนมิถุนายนของทุกปี ถือเป็นงานบุญใหญ่ที่ชาวบ้านจากหลายพื้นที่เดินทางมาร่วมปฏิบัติธรรม ทำให้วัดมีชีวิตชีวาและเต็มไปด้วยบรรยากาศแห่งศรัทธาวัดบุปผารามยังเป็นศูนย์กลางในการจัดกิจกรรมสืบสานประเพณี เช่น งานทำบุญประจำหมู่บ้าน งานบุญเข้าพรรษา-ออกพรรษา การฟังธรรมเทศนา รวมถึงเป็นสถานที่อบรมศีลธรรมให้แก่เยาวชนในช่วงเข้าค่ายพุทธบุตร ช่วยปลูกฝังคุณธรรมและความเป็นไทยให้กับคนรุ่นใหม่ นอกจากนี้ สภาพแวดล้อมของวัดยังร่มรื่นด้วยไม้ดอกไม้ประดับตามชื่อ “บุปผาราม” ทำให้บรรยากาศเหมาะแก่การสวดมนต์ ปฏิบัติธรรม และพักจิตใจให้สงบ', '08:00:00', '18:00:00', '15.5529958', '103.4784045', 'กำแพง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '183', '1', '55', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk226/2026-04-10_14-30-22_S__13279238.jpg\"]'),
('44', 'PK223', 'โบสถ์ขาว วัดบ้านดอกรัก', 'โบสถ์ขาว ภายใน วัดบ้านดอกรัก ตั้งอยู่ที่ตำบลกำแพง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นโบสถ์สีขาวสะอาดตาที่มีความงดงามโดดเด่นในแบบพุทธศิลป์', '08:00:00', '18:00:00', '15.5622811', '103.4698561', 'กำแพง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '30', '3', '17', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk223/2026-04-10_14-17-26_S__35487753_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk223/2026-04-10_14-20-38_S__9617460_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk223/2026-04-10_14-20-42_S__9617461_0.jpg\"]'),
('45', 'PK222', 'วัดบ้านดอกรัก', 'วัดบ้านดอกรัก ตั้งอยู่ในตำบลกำแพง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด สังกัดคณะสงฆ์มหานิกาย วัดแห่งนี้ก่อตั้งขึ้นเมื่อปี พ.ศ. 2450 และต่อมาได้รับพระราชทานวิสุงคามสีมาเมื่อวันที่ 22 ตุลาคม พ.ศ. 2513', '08:00:00', '18:00:00', '15.5625086', '103.4697272', 'กำแพง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '45', '1', '16', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk222/2026-04-10_14-07-39_S__13254664.jpg\"]'),
('46', 'PK220', 'ท้าวเวสสุวรรณ วัดบ้านหนองอ่าง', 'ท้าวเวสสุวรรณ อยู่ที่ วัดบ้านหนองอ่าง ตำบลกำแพง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ดท้าวเวสสุวรรณ เป็นหนึ่งในท้าวจตุโลกบาลผู้ยิ่งใหญ่ทั้งสี่ ผู้มีหน้าที่รักษาและคุ้มครองโลกมนุษย์ ทรงดำรงตำแหน่งเป็น “อธิบดีแห่งยักษ์และอสูร” แต่แม้จะเป็นผู้ปกครองพวกอสูร ท้าวเวสสุวรรณกลับเป็นเทพผู้ตั้งมั่นในธรรม ทำหน้าที่พิทักษ์พระพุทธศาสนาและป้องกันโลกจากภูตผีปีศาจและพลังชั่วร้ายต่าง ๆ ตามคติความเชื่อของชาวไทย ชาวลังกา และชาวเอเชียตะวันออกเฉียงใต้ท้าวเวสสุวรรณ หรือที่เรียกกันอีกนามว่า “ท้าวกุเวร” หรือ “ท้าวไพสพ” ยังได้รับการยกย่องว่าเป็นผู้ประทานความมั่งคั่งร่ำรวย เนื่องจากในคัมภีร์โบราณท่านเป็นเทพแห่งทรัพย์สมบัติ ผู้ดูแลความเจริญรุ่งเรืองของมนุษย์ ผู้ที่บูชาท่านจึงมักเชื่อว่าจะได้รับการคุ้มครองภัยและมีความก้าวหน้าในหน้าที่การงานข้อมูลเพิ่มเติมเกี่ยวกับท้าวเวสสุวรรณ• ตำแหน่งในท้าวจตุโลกบาลท้าวเวสสุวรรณเป็นเทพผู้รักษาทิศเหนือ มีหน้าที่คุ้มครองโลกมนุษย์จากภูตผีปีศาจและอมนุษย์ที่ประสงค์ร้าย• รูปลักษณ์ท่านมักปรากฏในรูปยักษ์ผู้ทรงอำนาจ ถือกระบองแก้วหรือไม้เท้า ถือเป็นสัญลักษณ์แห่งการขับไล่สิ่งอัปมงคล• ความเชื่อเรื่องการบูชาเชื่อว่าช่วยปัดเป่าอุปสรรค ป้องกันภัยอันตราย ภูตผีปีศาจ เสริมความมั่งคั่ง และคุ้มครองผู้ประกอบธุรกิจให้เจริญรุ่งเรือง• ความเกี่ยวข้องกับพระพุทธศาสนาตามพุทธประวัติ ท้าวเวสสุวรรณเป็นเทพผู้ปกป้องพระพุทธศาสนา เมื่อพระพุทธเจ้าทรงตรัสรู้ใหม่ ๆ ท่านได้มาถวาย “รัตนคทา” เพื่อใช้ในการแสดงธรรมแก่เหล่ายักษ์ที่ดื้อรั้น และช่วยคุ้มครองพระพุทธบริษัท', '08:00:00', '18:00:00', '15.5698777', '103.4758423', 'กำแพง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '300', '2', '91', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk220/2026-04-10_11-33-51_S__26075142_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk220/2026-04-10_11-33-55_S__26075143_0.jpg\"]'),
('47', 'PK218', 'วัดบ้านหนองอ่าง', 'วัดบ้านหนองอ่าง ตั้งอยู่ในพื้นที่อำเภอ เกษตรวิสัย จังหวัดร้อยเอ็ด เป็นวัดสำคัญประจำชุมชนที่มีบทบาทด้านการศึกษาพระพุทธศาสนาอย่างต่อเนื่องยาวนาน ภายในวัดมีโรงเรียนพระปริยัติธรรม แผนกธรรม เปิดทำการเรียนการสอนมาตั้งแต่ปี พ.ศ. 2492 เพื่อส่งเสริมการศึกษาพระภิกษุ สามเณร และพุทธศาสนิกชนให้มีความรู้ด้านพระพุทธธรรมอย่างถูกต้องตามหลักพระพุทธศาสนาต่อมาในปี พ.ศ. 2536 วัดได้จัดตั้งศูนย์ศึกษาพระพุทธศาสนาวันอาทิตย์ เพื่อให้เยาวชนและประชาชนในพื้นที่มีโอกาสศึกษาหลักธรรม ศีลธรรม และจริยธรรมอย่างเป็นระบบ จัดการเรียนการสอนต่อเนื่องมาจนถึงปัจจุบัน ทำให้วัดบ้านหนองอ่างเป็นศูนย์กลางด้านการปลูกฝังคุณธรรมแก่สังคมท้องถิ่น และเป็นแหล่งเรียนรู้พระพุทธศาสนาที่สำคัญของชุมชน', '08:00:00', '18:00:00', '15.5698777', '103.4758423', 'กำแพง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '144', '2', '47', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk218/2026-04-10_11-19-10_S__13246474_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk218/2026-04-10_11-19-14_S__13246475_0.jpg\"]'),
('48', 'PK217', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์นครกัณฑ์', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์นครกัณฑ์ วัดสระโพธิ์นครกัณฑ์ เป็นกัณฑ์ที่ 13 และเป็นบทอวสานของมหาเวสสันดรชาดก อันเป็นวรรณกรรมชั้นสูงที่เล่าถึงการบำเพ็ญบารมีอันยิ่งใหญ่ของพระเวสสันดร หลังจากผ่านบททดสอบและการเสียสละอันหนักหน่วง ในกัณฑ์สุดท้ายนี้เรื่องราวดำเนินไปสู่ความสมบูรณ์ ความชื่นชมยินดี และการกลับคืนสู่บ้านเมืองอย่างสง่างามเหตุการณ์สำคัญเริ่มจากกษัตริย์ทั้งหกพระองค์—พระเจ้าสญชัย พระนางผุสดี พระเวสสันดร พระนางมัทรี พระชาลี และพระกัณหา—เสด็จนิวัติกลับกรุงสีพีพร้อมขบวนพยุหยาตราอันตระการตา การกลับมาครั้งนี้ถูกต้อนรับด้วยความปีติของประชาชนทั้งเมือง และเป็นสัญลักษณ์ของการสิ้นสุดความทุกข์ยากที่แต่ละพระองค์เคยประสบเมื่อกลับถึงพระนคร พระเวสสันดรได้รับการอภิเษกขึ้นครองราชย์ ทรงปกครองบ้านเมืองด้วยทศพิธราชธรรม พร้อมทั้งบำเพ็ญทานอย่างไม่หยุดยั้ง ความเจริญรุ่งเรืองบังเกิดขึ้นทั่วเมือง และในวาระแห่งความเป็นสิริมงคล ทวยเทพยังบันดาลให้เกิด “ฝนทองโบกขรพรรษ” ตกลงมาเพื่อเฉลิมฉลองการกลับสู่เมืองของพระโพธิสัตว์ในคติความเชื่อของชาวไทย ผู้ที่ร่วมบูชาหรือฟังกัณฑ์นี้จะได้รับผลอันเป็นสิริมงคล คือความอุดมสมบูรณ์ ความพร้อมหน้าของญาติมิตร และความเจริญในชีวิตครอบครัว ทั้งยังสื่อถึงความกตัญญู การให้อภัย และการกลับคืนสู่ความสงบสุขหลังผ่านบททดสอบแห่งชีวิตนครกัณฑ์จึงไม่ใช่เพียงกัณฑ์ปิดท้ายของมหาชาติ แต่เป็น “บทสรุปแห่งบารมี” ที่ย้ำให้เห็นว่าความดี ความเสียสละ และความเมตตาย่อมนำพาสู่ความสมบูรณ์และความสงบสุขในที่สุด', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '288', '1', '85', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk217/2026-04-10_10-59-49_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_19.jpg\"]'),
('49', 'PK216', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ฉกษัตริย์', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ฉกษัตริย์ วัดสระโพธิ์กัณฑ์ฉกษัตริย์ (กัณฑ์ที่ 12) เป็นตอนใกล้จบของมหาเวสสันดรชาดกที่สะท้อนความรัก ความผูกพัน และความโศกสุขของสมาชิกในราชวงศ์ผู้พลัดพรากกันมานาน เนื้อเรื่องเริ่มต้นเมื่อพระเจ้ากรุงสญชัย พร้อมด้วยพระนางผุสดี เสด็จนำกองทัพขึ้นเขาวงกต เพื่อเชิญพระเวสสันดรและครอบครัวเสด็จนิวัตกลับเมือง หลังจากได้ยินข่าวเรื่องการบริจาคบุตรและการบำเพ็ญบารมีอันยิ่งใหญ่เมื่อทั้งหกพระองค์ได้พบกัน—พระเจ้าสญชัย พระนางผุสดี พระเวสสันดร พระนางมัทรี พระชาลี และพระกัณหา—ความโศก ความคิดถึง และความดีใจท่วมท้นจนต่างทรงร่ำไห้อย่างสุดอาลัย เหตุการณ์กินใจถึงขั้นที่ทุกพระองค์ทรงสลบสิ้นสติ เพราะความปิติและความเศร้าปะปนกันอย่างรุนแรง จนในที่สุดฝนโบกขรพรรษ ฝนทิพย์จากสวรรค์ตกลงมาปลุกให้ฟื้นคืนสติอีกครั้ง เป็นสัญลักษณ์แห่งการชำระล้างความทุกข์และประกาศการพบกันอย่างเป็นมงคลคำว่า “ฉกษัตริย์” อ่านว่า ฉอ-กะ-สัด อันสื่อถึงการรวมตัวของกษัตริย์ทั้งหกองค์ในฉากอันซาบซึ้งใจที่สุดตอนหนึ่งของมหาชาติกัณฑ์นี้ให้ข้อคิดสำคัญว่าความโกรธ ความไม่เข้าใจ หรือความพลัดพรากใด ๆ ล้วนมีวันคลี่คลายได้ด้วยการให้อภัยและความรักที่มั่นคงของครอบครัว ขณะเดียวกันยังสื่อให้เห็นว่าแม้ผู้คนจะพลาดพลั้งหรือตัดสินใจผิดพลาด แต่การกลับมาเข้าใจกันย่อมนำความสุขกลับคืนเสมอตามคติความเชื่อ การบูชากัณฑ์ฉกษัตริย์จะนำความร่มเย็นเป็นสุขให้ครอบครัว ทำให้คนในบ้านรักใคร่ ปรองดอง และหวนกลับมาพบกันในความผาสุก', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '282', '1', '84', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk216/2026-04-10_10-57-13_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_21.jpg\"]'),
('50', 'PK215', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์มหาราช', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์มหาราช วัดสระโพธิ์กัณฑ์มหาราช (กัณฑ์ที่ 11) เป็นตอนสำคัญในมหาเวสสันดรชาดก เล่าเหตุการณ์ระหว่างที่ชูชกพาพระกัณหาและพระชาลีเดินทางกลับเมือง หลังจากได้ตัวกุมารทั้งสองมาแล้ว ชูชกมีนิสัยเห็นแก่ตัว มัดเด็กไว้ที่โคนไม้และปีนขึ้นไปนอนเอง ปล่อยให้เด็กเผชิญความเหนื่อยยากตามลำพัง ด้วยความสงสาร เทวดาจึงจำแลงกายเป็นพระเวสสันดรและพระนางมัทรี มาป้อนอาหารทิพย์และกล่อมให้ทั้งสองหลับสบายตลอดคืนรุ่งขึ้นเหล่าเทพยดาได้ดลใจให้ชูชกพากุมารเดินทางหลงเข้าไปในกรุงเชตุดรของพระเจ้าสญชัย ผู้เป็นพระอัยกา เมื่อพบเด็กทั้งสอง พระเจ้าสญชัยจำได้ทันทีและทรงทราบเรื่องการบริจาคบุตร จึงขอไถ่ตัวพระชาลีด้วยทองคำหนึ่งร้อยแท่ง และพระกัณหาด้วยทองคำอีกหนึ่งร้อยแท่ง พร้อมทาส ทาสี และสิ่งของอีกมากอย่างละหนึ่งร้อยรายการ ชูชกได้รับทรัพย์สมบัติมหาศาล แต่เพราะความโลภบริโภคอาหารมากเกินไปจนท้องแตกตายในเวลาต่อมากัณฑ์มหาราชมีทั้งสิ้น 69 พระคาถา เป็นตอนที่แสดงถึงจุดสิ้นสุดแห่งความพลัดพรากของสองกุมาร และเป็นจุดเริ่มต้นของเหตุการณ์ที่จะนำไปสู่การเสด็จกลับเมืองของพระเวสสันดร นอกจากนี้ยังสอนให้เห็นโทษของความโลภและอานิสงส์ของผู้บูชากัณฑ์ ซึ่งเชื่อว่าจะได้รับทั้งมนุษย์สมบัติ สวรรค์สมบัติ และนิพพานสมบัติ', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '238', '1', '71', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk215/2026-04-10_10-54-42_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_17.jpg\"]')
INSERT INTO `places` (`id`, `place_code`, `place_name`, `description`, `opening_time`, `closing_time`, `latitude`, `longitude`, `subdistrict`, `district`, `province`, `created_at`, `updated_at`, `word_count`, `photo_count`, `expected_read_time`, `images_json`) VALUES
('51', 'PK214', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์สักกบรรพ', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์สักกบรรพ วัดสระโพธิ์กัณฑ์สักกบรรพ (กัณฑ์ที่ 10) ในมหาเวสสันดรชาดก มีความยาว 43 พระคาถา เป็นตอนสำคัญที่กล่าวถึงท้าวสักกเทวราช (พระอินทร์) เสด็จลงมาทดสอบบารมีของพระเวสสันดรและคุ้มครองไม่ให้มีผู้มาขอพระนางมัทรีอีก หลังจากที่พระเวสสันดรได้มอบพระชาลีและพระกัณหาแก่ชูชกไปในกัณฑ์ก่อนหน้าเมื่อรุ่งเช้า ท้าวสักกะแปลงกายเป็นพราหมณ์เฒ่า มาทูลขอพระนางมัทรี พระเวสสันดรแม้จะรักพระมเหสีเพียงใด แต่เพื่อความบริสุทธิ์แห่งทานบารมี พระองค์ก็ยังทรงยอมถวายให้ด้วยใจเด็ดเดี่ยว การให้ทานครั้งนี้ยิ่งใหญ่จนผืนแผ่นดินหวั่นไหวไปถึงเทวโลกเมื่อเห็นความตั้งมั่นของพระโพธิสัตว์ ท้าวสักกะจึงสำแดงพระวรกายแท้จริงคืน พร้อมมอบพระนางมัทรีกลับ และถวายพรทั้ง 8 ประการ เช่น ให้พระบิดาเมตตา ปล่อยนักโทษ อุปถัมภ์คนยากจน ขอให้ฝนแก้วตกในเมือง และขอให้พระเวสสันดรไปบังเกิดในสวรรค์ชั้นดุสิตเมื่อสิ้นพระชนม์ตามคติความเชื่อ การบูชากัณฑ์สักกบรรพจะทำให้ผู้ฟังเจริญด้วยลาภยศ สุขภาพแข็งแรง ผิวพรรณผ่องใส และมีจิตใจผ่องแผ้ว', NULL, NULL, '15.6139477', '103.9964108', '', '', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '199', '1', '60', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk214/2026-04-10_10-52-08_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_16.jpg\"]'),
('52', 'PK213', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์มัทรี', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์มัทรี วัดสระโพธิ์กัณฑ์มัทรี (กัณฑ์ที่ 9) เป็นหนึ่งในตอนที่กินใจที่สุดของมหาเวสสันดรชาดก ถ่ายทอดความรัก ความโศกเศร้า และความเสียสละของพระนางมัทรี ผู้เป็นคู่พระทัยของพระเวสสันดร วันหนึ่งขณะออกไปหาผลไม้ นางเกิดฝันร้ายและพบลางร้ายหลายประการ ไม่ว่าจะเป็นสัตว์ปีกปีกหัก ต้นไม้ที่ไร้ผล และความเงียบงันผิดธรรมชาติ สิ่งเหล่านี้ยิ่งทำให้นางระทมกังวลถึงโอรสธิดาในขณะเดียวกัน เหล่าเทพยดาก็แปลงกายเป็นสัตว์ร้ายสามตน—เสือโคร่ง เสือเหลือง และสิงห์—มาขวางเส้นทาง เพื่อถ่วงเวลาไม่ให้นางกลับถึงอาศรมทันการณ์ ทั้งหมดเป็นไปเพื่อเปิดโอกาสให้พระเวสสันดรได้บริจาคพระชาลีและพระกัณหาแก่ชูชกโดยไม่มีสิ่งใดขัดขวางเมื่อพระนางมัทรีกลับถึงอาศรมและพบว่าลูกทั้งสองหายไป นางออกตามหาอย่างสุดหัวใจ ร้องไห้จนสิ้นสติด้วยความเจ็บปวด แต่เมื่อฟื้นขึ้นมาและได้รับฟังเหตุผลจากพระเวสสันดร นางจึงค่อย ๆ สงบใจ เปลี่ยนความเศร้าจากการพรากลูกเป็นความปีติในบารมีของพระสวามี พร้อมอนุโมทนาทานด้วยความศรัทธาข้อคิดของกัณฑ์นี้ คือภาพแท้จริงของความรักแม่ ความกล้าหาญในการยอมรับความจริง และการเสียสละสิ่งที่รักที่สุดเพื่อประโยชน์อันยิ่งใหญ่ของโลกอานิสงส์ที่เชื่อกัน คือความมั่งคั่ง อายุยืน และความงดงามสำหรับผู้บูชากัณฑ์นี้กัณฑ์มัทรีจึงเป็นตอนที่สะท้อนความลึกซึ้งของหัวใจมนุษย์ได้อย่างงดงาม ทั้งในด้านความรัก ความทุกข์ และความสูงส่งของการปล่อยวาง หากต้องการฉบับสั้นลงหรือสำนวนแบบนิทาน บอกได้เลยครับ!', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '279', '1', '83', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk213/2026-04-10_10-48-45_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_15.jpg\"]'),
('53', 'PK212', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์กุมาร', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์กุมาร วัดสระโพธิ์กัณฑ์กุมาร (กัณฑ์ที่ 8) มีความยาว 101 พระคาถา แต่งโดยเจ้าพระยาพระคลัง (หน) เล่าเหตุการณ์สำคัญเมื่อชูชกมาทูลขอพระชาลีและพระกัณหาจากพระเวสสันดร เพื่อพาไปเป็นทาสตามความต้องการของนางอมิตตดา พระเวสสันดรทรงมอบทั้งสองกุมารด้วยใจบริสุทธิ์ เพื่อบำเพ็ญบุตรทานบารมีแม้จะต้องทนเห็นความทุกข์ของลูกก็ตามขณะที่ชูชกมาทูลขอ พระกุมารทั้งสองได้ยินและพากันหนีไปซ่อนตัวในสระบัว แต่พระเวสสันดรทรงตามเรียกออกมาและยืนยันจะมอบให้ตามคำขอ พร้อมทั้งกำหนดค่าไถ่ หากมีผู้ประสงค์จะไถ่คืน ทั้งทองคำ ช้าง ม้า โค และทรัพย์สิ่งของจำนวนมากหลังได้รับตัวเด็กทั้งสอง ชูชกก็แสดงความโหดร้ายทันที ทั้งมัดด้วยเถาวัลย์และเฆี่ยนตีระหว่างทาง พระเวสสันดรแม้จะเศร้าใจแต่ทรงอดกลั้น ไม่ให้ความโทสะบดบังการบำเพ็ญบารมีกัณฑ์นี้ใช้เพลง “โอดเชิดฉิ่ง” เป็นทำนองประจำ และมีความเชื่อว่า ผู้บูชาจะสำเร็จสมประสงค์ มีปัญญาเฉลียวฉลาด และได้ไปเกิดในฉกามาพจรสวรรค์', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '187', '1', '56', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk212/2026-04-10_10-45-04_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_14.jpg\"]'),
('54', 'PK211', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์มหาพน', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์มหาพน วัดสระโพธิ์กัณฑ์มหาพน (กัณฑ์ที่ ๗) เล่าเหตุการณ์ที่ชูชกเดินทางเข้าสู่ป่าใหญ่ มหาพน อันอุดมด้วยพรรณไม้และสัตว์ป่านานาชนิด ระหว่างทางเขาพบพระอัจจุตฤาษี จึงแสร้งทำเป็นทูตมาจากเมืองเพื่อขอพักแรมและขอเส้นทางไปยังอาศรมพระเวสสันดรแรกเริ่มพระฤาษีระแวงและไม่ยอมบอกทาง แต่ท้ายที่สุดก็หลงเชื่อถ้อยคำอ่อนหวานของชูชก จนยอมบอกเส้นทางอย่างละเอียดในวันรุ่งขึ้น กัณฑ์นี้จึงสะท้อนความเจ้าเล่ห์ของชูชกและความหูเบาของฤาษี ผู้แม้จะมีปัญญาแต่ขาดความรอบคอบข้อคิดสำคัญ: ผู้มีสติปัญญาแต่ไม่ไตร่ตรองให้รอบคอบ อาจตกเป็นเหยื่อของคนเจ้าเล่ห์ได้ง่าย และความเชื่อคนเพียงเพราะความสงสารนำมาซึ่งความเดือดร้อนในภายหลัง', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '138', '1', '42', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk211/2026-04-10_10-16-24_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_13.jpg\"]'),
('55', 'PK210', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์จุลพน', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์จุลพน วัดสระโพธิ์กัณฑ์จุลพน เป็นกัณฑ์ที่ 6 ในมหาเวสสันดรชาดก เล่าเหตุการณ์เมื่อชูชกเดินทางลึกเข้าสู่ป่าโปร่งซึ่งเรียกว่า “จุลพน” ระหว่างทางเขาถูกหมาของพรานเจตบุตรไล่จนต้องหนีขึ้นต้นไม้ จากนั้นจึงใช้ไหวพริบหลอกพรานเจตบุตรว่าตนเป็นราชทูตของพระเจ้าสญชัย นำพระราชสาส์นมาเชิญพระเวสสันดรกลับเมืองพรานเจตบุตรหลงเชื่อ จึงให้การต้อนรับและนำชูชกมุ่งหน้าไปยังเขาวงกตที่พระเวสสันดรประทับอยู่ กัณฑ์นี้สะท้อนความเจ้าเล่ห์ของชูชกและความซื่อสัตย์ของพรานที่ทำหน้าที่เฝ้าป่าอย่างแข็งขันกัณฑ์จุลพนมีจำนวน 35 พระคาถา และใช้เพลง “คุกพาทย์” หรือ “รัวสามลา” เป็นทำนองประจำกัณฑ์ เชื่อกันว่าผู้บูชากัณฑ์นี้จะได้รับบริวารสมบูรณ์และมีทรัพย์สมบัติอันร่มเย็นดุจอุทยานงดงาม', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '153', '1', '47', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk210/2026-04-10_10-01-20_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_12.jpg\"]'),
('56', 'PK209', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ชูชก', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ชูชก วัดสระโพธิ์กัณฑ์ชูชก เป็นกัณฑ์ที่ 5 ในมหาเวสสันดรชาดก เล่าเรื่องพราหมณ์เฒ่าชูชก ผู้มีนิสัยโลภและเห็นแก่ตัว แม้ยากจนแต่ขยันและมัธยัสถ์จนมีทรัพย์สะสมมาก ต่อมานำทรัพย์ไปฝากเพื่อนพราหมณ์ แต่เพื่อนใช้เงินหมด จึงยกลูกสาวชื่อ นางอมิตตดา ให้ชูชกเป็นภรรยาเพื่อใช้หนี้เมื่อแต่งงานแล้ว นางอมิตตดาปรนนิบัติสามีอย่างดีจนเป็นที่อิจฉาของพราหมณีในหมู่บ้าน พวกนางรุมด่าทอและทำให้เธอเกิดความคับแค้น จึงบังคับให้ชูชกไปขอสองกุมาร คือ พระชาลี และ พระกัณหา จากพระเวสสันดร มาเป็นทาสรับใช้เพื่อยกฐานะให้เทียมหน้าภรรยาของผู้อื่นชูชกจึงออกเดินทางอย่างยากลำบาก และใช้ความเจ้าเล่ห์หลอกพราน เจตบุตร ว่าตนเป็นทูตจากเมืองสีพีมาเชิญพระเวสสันดรกลับเมือง เพื่อขอทางผ่านเข้าไปถึงเขาวงกตกัณฑ์นี้สะท้อนให้เห็นโทษของความโลภ ความริษยา และผลเสียจากการฝากทรัพย์ไว้กับผู้อื่น ขณะเดียวกันก็กล่าวถึงความดีของภรรยาที่ซื่อสัตย์และปรนนิบัติสามีอย่างเต็มใจอานิสงส์ตามคติความเชื่อ เชื่อว่าผู้บูชากัณฑ์ชูชกจะมีโภคทรัพย์สมบูรณ์ เจริญด้วยบริวาร และเป็นที่รักใคร่ของผู้คนในสังคม', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '209', '1', '63', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk209/2026-04-10_09-30-13_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_11.jpg\"]'),
('57', 'PK208', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ วนปเวศน์', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์วนปเวศน์ วัดสระโพธิ์กัณฑ์วนประเวศน์ (กัณฑ์ที่ 4) เป็นตอนที่กษัตริย์ทั้ง 4 องค์ (พระเวสสันดร, พระนางมัทรี, ชาลี, กัณหา) เดินทางดงมุ่งสู่เขาวงกต ผ่านเมืองเจตราช กษัตริย์เจตราชเชิญครองเมืองแต่ปฏิเสธ จึงทรงส่งเสด็จถึงเขาวงกต และเนรมิตศาลาอาศรมให้ทรงบำเพ็ญพรตเป็นฤาษี โดยเทพยดาย่นระยะทางให้ถึงที่หมายในวันเดียวเนื้อเรื่องย่อกัณฑ์วนประเวศน์การเดินทางสุดลำบาก: หลังจากพระเวสสันดรบริจาคสัตตสดกมหาทานและรถม้าแล้ว ได้พากันเดินเท้าผ่านป่าพบเจตราช: เดินทางถึงแคว้นเจตราษฎร์ กษัตริย์เจตราชและประชาชนทราบข่าวได้มาเฝ้ากราบทูลเชิญเสด็จไปครองเมืองเพื่ออนุเคราะห์พระประสงค์มั่นคง: พระเวสสันดรปฏิเสธและชี้แจงจุดประสงค์ที่แน่วแน่จะไปบำเพ็ญพรต ณ เขาวงกตถึงเขาวงกต: กษัตริย์เจตราชส่งเสด็จจนถึงเขาวงกต ซึ่งท้าวสักกะเทวราชสั่งให้ท้าววิษณุกรรมเนรมิตศาลาอาศรมถวาย เพื่อทรงบำเพ็ญเพียรในฐานะฤาษีอานิสงส์: ผู้บูชากัณฑ์นี้จะได้รับความสุขทั้งโลกนี้และโลกหน้า ตำแหน่งหน้าที่การงานดีข้อคิดประจำกัณฑ์: ยามเจ็บ ยามจาก ควรได้รับความเหลียวแล และน้ำใจมิตรแท้ที่ไม่ทอดทิ้งกันในยามตกต่ำ', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '222', '1', '66', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk208/2026-04-10_09-26-00_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_10.jpg\"]'),
('58', 'PK207', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ทานกัณฑ์', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ทานกัณฑ์ วัดสระโพธิ์ทานกัณฑ์ เป็นกัณฑ์ที่ 3 ในมหาเวสสันดรชาดก เล่าเหตุการณ์สำคัญเมื่อพระเวสสันดรทรงประกอบ “มหาสัตสดกทาน” การให้ทานครั้งใหญ่ประกอบด้วยทรัพย์ 7 ประเภท อย่างละ 700 ก่อนเสด็จออกจากเมืองสีพี ทั้งนี้เป็นผลจากการที่ชาวเมืองไม่พอใจที่พระองค์พระราชทานช้างมงคลปัจจัยนาเคนทร์ให้แก่เมืองอื่น จนพากันร้องขอพระเจ้าสญชัยให้เนรเทศพระองค์ออกจากนครก่อนจะจากไป พระเวสสันดรได้ทูลขอจัดพิธีบริจาคครั้งสุดท้าย แจกช้าง ม้า โคนม ทาสชาย ทาสหญิง รถ และสตรีอย่างละ 700 ด้วยจิตอันเต็มไปด้วยเมตตาและความตั้งใจแน่วแน่ แม้จะถูกขับไล่ พระองค์ก็ไม่หวั่นไหว ไม่โกรธเคืองผู้คน และยังคงมุ่งมั่นในทานบารมีเพื่อสั่งสมบุญเพื่อพระโพธิญาณในอนาคตกาลสาระของกัณฑ์นี้เน้นเรื่องความมั่นคงในความดี การเสียสละประโยชน์ส่วนตนเพื่อผู้อื่น และการยอมรับผลแห่งกรรมอย่างสงบ ส่วนอานิสงส์ของการฟังทานกัณฑ์เชื่อกันว่าจะทำให้ผู้ฟังอุดมด้วยทรัพย์ บริวาร และมีวาสนาไปเกิดในสวรรค์ชั้นดาวดึงส์', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '192', '1', '58', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk207/2026-04-10_09-21-44_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_9.jpg\"]'),
('59', 'PK206', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์หิมพานต์', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์หิมพานต์ วัดสระโพธิ์กัณฑ์หิมพานต์ ซึ่งเป็นกัณฑ์ที่สองของมหาเวสสันดรชาดก เป็นตอนที่เปิดฉากเหตุใหญ่ในชีวิตของพระเวสสันดร เมื่อทรงบริจาคช้างปัจจัยนาเคนทร์ ช้างมงคลคู่บ้านคู่เมืองที่ทำให้ฝนตกต้องตามฤดูกาล แก่พราหมณ์จากเมืองกลิงคราษฎร์ การให้ทานครั้งนี้ทำให้ชาวเมืองสีพีพากันโกรธเคือง เพราะเห็นว่าเป็นการทำให้บ้านเมืองเสียความอุดมสมบูรณ์ จึงพากันกราบทูลพระเจ้าสัญชัยให้เนรเทศพระเวสสันดรออกจากเมืองแม้จะถูกต่อต้านอย่างรุนแรง พระเวสสันดรยังคงมั่นคงในทานบารมี ก่อนออกจากเมืองพระองค์ยังทรงประกอบสัตตสดกมหาทาน คือ ทานอย่างละเจ็ดร้อยด้วยความตั้งใจบริสุทธิ์ สร้างความเลื่อมใสให้ประชาชนจำนวนมากเมื่อถึงเวลาต้องออกเดินทาง พระนางมัทรีพร้อมด้วยพระชาลีและพระกัณหาได้ขอติดตามไปด้วย เพื่อร่วมบำเพ็ญเพียรในป่าหิมพานต์ ณ เขาวงกต เส้นทางนี้จึงไม่ใช่เพียงการเนรเทศ แต่เป็นการเดินสู่การสั่งสมบารมีขั้นสูงสุดของพระโพธิสัตว์ข้อคิดสำคัญของกัณฑ์นี้คือการทำความดีมักมีอุปสรรค ความเสียสละที่ยิ่งใหญ่ต้องแลกด้วยความกล้าหาญ และผู้สร้างบารมีจริงแท้ย่อมไม่หวั่นไหวต่อคำครหาใด ๆ', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '212', '1', '64', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk206/2026-04-10_09-01-29_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_8.jpg\"]'),
('60', 'PK205', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ทศพร', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก กัณฑ์ทศพร วัดสระโพธิ์ กัณฑ์ทศพร เป็นกัณฑ์แรกของมหาเวสสันดรชาดกทั้ง 13 กัณฑ์ มีจำนวน 19 พระคาถา เล่าเรื่องราวก่อนการประสูติของพระเวสสันดร โดยกล่าวถึง พระนางผุสดี เทพอัปสรผู้สิ้นบุญจากสวรรค์ชั้นดาวดึงส์ และเตรียมจะจุติลงมายังโลกมนุษย์ เพื่อเป็นพระราชมารดาของพระเวสสันดร ผู้ที่จะบำเพ็ญทานบารมีอันยิ่งใหญ่ก่อนที่พระนางจะลงจุติ ท้าวสักกะเทวราช (พระอินทร์) ทรงประทาน “พร 10 ประการ” แก่พระนางผุสดี ได้แก่ การได้เกิดในโลกมนุษย์ มีดวงตาและคิ้วงาม มีนามว่าผุสดี มีรูปร่างงดงาม มีโอรสผู้ยิ่งใหญ่ (พระเวสสันดร) ไม่มีความยากจน เป็นที่รักของพระสวามี มีใจประกอบด้วยกุศล และสามารถจัดการสิ่งที่จำเป็นในชีวิตได้เมื่อถึงเวลาจุติ พระนางผุสดีได้มาเกิดเป็นพระราชธิดาแห่งกรุงมัทราช และภายหลังอภิเษกกับพระเจ้าสัญชัยแห่งกรุงสีพี จึงได้เป็นพระราชมารดาของพระเวสสันดรตามพุทธพยากรณ์กัณฑ์ทศพรจึงเป็นกัณฑ์ที่เน้นเรื่อง ผลแห่งบุญ การตั้งความปรารถนาดี และปัจจัยที่เกื้อหนุนให้พระโพธิสัตว์ได้บำเพ็ญบารมี อันเป็นพื้นฐานของเรื่องราวในมหาเวสสันดรชาดกทั้งหมด', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '209', '1', '63', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk205/2026-04-10_08-46-33_LINE_ALBUM_จิตรกรรมวัดสระโพธิ์_260402_7.jpg\"]'),
('61', 'PK204', 'จิตรกรรมฝาผนัง พระเวสสันดรชาดก ปฐมเหตุพระเวสสันดร', 'จิตรกรรมฝาผนัง ปฐมเหตุพระเวสสันดร วัดสระโพธิ์ปฐมเหตุพระเวสสันดร 13 กัณฑ์ หมายถึง เรื่องราวพระเวสสันดรชาดก (มหาชาติ) ที่แบ่งออกเป็น 13 ตอน (13 กัณฑ์) ซึ่งเล่าเหตุการณ์สำคัญของพระเวสสันดร ผู้บำเพ็ญ “ทานบารมี” จนถึงขั้นสูงสุดปฐมเหตุของพระเวสสันดรชาดก เป็นเหตุการณ์ที่อธิบายว่าเพราะเหตุใดพระเวสสันดรจึงทรงเป็นผู้มีทานบารมีสูงสุด และทำไมเหตุการณ์ต่าง ๆ ในชาดกจึงเกิดขึ้นกล่าวกันว่า ในอดีตกาลอันยาวไกล พระโพธิสัตว์ (ผู้ที่จะได้เกิดมาเป็นพระเวสสันดร) ได้ตั้งความปรารถนาจะบำเพ็ญทานบารมีให้ยิ่งใหญ่ที่สุดในหมู่มนุษย์และเทพ เพื่อให้ถึงพระโพธิญาณในอนาคตกาล เมื่อถือกำเนิดเป็นพระเวสสันดร จึงทรงมีนิสัยแห่งการให้เป็นทุนเดิม ทั้งยังอภิบาลบ้านเมืองด้วยการแจกทานมากมายไม่เลือกผู้ใดเหตุการณ์สำคัญที่ถือเป็น “ปฐมเหตุ” ได้แก่พระเวสสันดรทรงบริจาค ช้างปัจจัยนาค ซึ่งเป็นช้างคู่บ้านคู่เมืองแก่พราหมณ์จากเมืองกลิงคราษฎร์การทานครั้งนั้นทำให้บ้านเมืองเดือดร้อน เพราะช้างเป็นเครื่องหมายแห่งความอุดมสมบูรณ์ชาวเมืองจึงบีบให้พระเจ้าสญชัย พระราชบิดา ส่งพระเวสสันดรออกจากเมืองไปอยู่ป่าหิมพานต์เหตุการณ์ทั้งหมดนี้เป็นจุดเริ่มต้นที่นำไปสู่เรื่องราวการบำเพ็ญทานบารมีขั้นสูงสุดของพระเวสสันดร ได้แก่การบริจาคทรัพย์ศฤงคารการบริจาคพระชาลีและพระกัณหาและการบริจาคพระนางมัทรีในที่สุดทั้งหมดนี้คือปฐมเหตุที่ทำให้พระเวสสันดรชาดกถูกยกย่องว่าเป็นชาดกสูงสุดแห่งทานบารมี', NULL, NULL, '15.6139477', '103.9964108', 'หนองฮี', 'หนองฮี', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '273', '1', '81', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk204/2026-04-10_08-42-46_01_ปฐมเหตพระเวสสันดร.jpg\"]'),
('62', 'PK201', 'กุฏิพระอริยะภูมิหอพระอุปคุต', 'กุฏิพระอริยะภูมิหอพระอุปคุต ตั้งอยู่ในวัดป่าหนองสะแนน ตำบลเหล่าหลวง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ดหอพระอุปคุต หรือ กุฏิพระอุปคุต เป็นสถานที่สร้างขึ้นเพื่อจำลองที่ประทับของพระอุปคุตเถระ พระอรหันต์ผู้มีฤทธิ์มากในยุคหลังพุทธกาล ตามคติความเชื่อของชาวอีสานและล้านนาเชื่อว่าพระอุปคุตจำพรรษาอยู่ ณ “กลางสะดือทะเล” หรือท้องทะเลหลวง ทำหน้าที่คุ้มครองพระพุทธศาสนาและปราบมารที่มาขัดขวางการทำบุญการสร้างหอพระอุปคุตมักพบในพื้นที่ภาคเหนือและภาคอีสาน โดยสร้างขึ้นเพื่อความเป็นสิริมงคลและเป็นที่พึ่งทางใจของชุมชน โดยเฉพาะในงานบุญใหญ่ เช่น บุญผะเหวด หรือ บุญเดือนสี่ ซึ่งเป็นประเพณีสำคัญของชาวอีสาน เชื่อว่าการมีหอพระอุปคุตประดิษฐานจะช่วยปกปักรักษางานบุญให้ราบรื่น ปราศจากอุปสรรค และช่วยขจัดภยันตรายทั้งปวง', NULL, NULL, '15.7228926', '103.5341761', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '150', '4', '53', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk201/2026-04-09_16-37-50_S__9617433_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk201/2026-04-09_16-37-54_S__9617434_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk201/2026-04-09_16-37-58_S__9617435_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk201/2026-04-09_16-38-01_S__9617436_0.jpg\"]'),
('63', 'PK200', 'วัดป่าหนองสะแนน', 'วัดป่าหนองสะแนน ตั้งอยู่ในตำบลเหล่าหลวง อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นวัดสำคัญทางประวัติศาสตร์และพระพุทธศาสนา ปัจจุบันได้รับการแต่งตั้งให้เป็นสำนักปฏิบัติธรรมประจำจังหวัดร้อยเอ็ด แห่งที่ 16 โดยมีพระครูวิสุทธิสมณกิจ อายุ 72 พรรษา ผู้ทรงคุณวุฒิทางพระพุทธศาสนา (น.ธ.เอก, พธ.บ.) ดำรงตำแหน่งเจ้าอาวาส ทำหน้าที่ดูแลกิจการของวัดและคณะสงฆ์อย่างใกล้ชิดตามหลักฐานจากประวัติศาสตร์ท้องถิ่นสันนิษฐานว่า วัดป่าหนองสะแนนถูกก่อตั้งขึ้นตั้งแต่ช่วงปลายกรุงศรีอยุธยา นับเป็นเวลากว่า 200–300 ปี วัดแห่งนี้ได้รับการบูรณะ พัฒนา และสืบทอดศรัทธามาอย่างต่อเนื่องจากรุ่นสู่รุ่น สะท้อนถึงความร่วมแรงร่วมใจของชาวบ้านและพุทธศาสนิกชนที่มุ่งมั่นรักษามรดกทางวัฒนธรรมและศาสนาให้คงอยู่จนถึงปัจจุบันภายในวัดเป็นที่ประดิษฐานพระประธานอันเป็นสิริมงคล และยังมีพระบรมสารีริกธาตุซึ่งถือเป็นศูนย์รวมแห่งศรัทธาของชาวอำเภอเกษตรวิสัย รวมถึงผู้ศรัทธาจากพื้นที่ต่าง ๆ ที่เดินทางมากราบสักการะเพื่อความเป็นสิริมงคล', '08:00:00', '18:00:00', '15.7405541', '103.5490726', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '193', '2', '61', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk200/2026-04-09_16-34-56_S__13213704_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk200/2026-04-09_16-34-59_S__13213705_0.jpg\"]'),
('64', 'PK198', 'วัดศรีอริยวงศ์', 'วัดศรีอริยวงศ์ ตั้งอยู่ที่ ตำบลเมืองบัว อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นวัดราษฎร์สังกัดคณะสงฆ์มหานิกาย ตั้งอยู่ที่บ้านเมืองบัว ตำบลเมืองบัว อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด สร้างขึ้นเมื่อวันที่ 12 มิถุนายน พ.ศ. 2479 นับเป็นวัดสำคัญประจำชุมชนที่มีบทบาททั้งด้านศาสนา การศึกษา และการอนุรักษ์วัฒนธรรมพื้นถิ่น', '08:00:00', '18:00:00', '15.6061984', '103.5900936', 'เมืองบัว', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '67', '1', '22', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk198/2026-04-09_16-23-09_S__13197342.jpg\"]'),
('65', 'PK197', 'ทับหลังรูปพระอินทร์ทรงช้างเอราวัณ', 'ทับหลังรูปพระอินทร์ทรงช้างเอราวัณ ศิลปะเขมรแบบบาปวน อายุพุทธศตวรรษที่ 17 ตั้งอยู่ บริเวณ ของกู่เมืองบัว', NULL, NULL, '15.6038977', '103.5925972', 'เมืองบัว', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '23', '2', '12', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk197/2026-04-09_16-08-28_S__13197319_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk197/2026-04-09_16-08-31_S__9617423_0.jpg\"]'),
('66', 'PK196', 'กู่เมืองบัว', 'กู่เมืองบัว ตั้งอยู่ที่บ้านเมืองบัว ตำบลเมืองบัว อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด บนเนินดงปู่ตาหรือ “ดอนกู่” ใกล้คูน้ำทางทิศตะวันตกเฉียงใต้ของเมืองโบราณบ้านเมืองบัว ซึ่งมีประวัติความเป็นมาย้อนไปถึงสมัยก่อนประวัติศาสตร์ลักษณะสถานที่เป็นเนินดินขนาดประมาณ 200 × 250 เมตร สูงราว 5–6 เมตรจากพื้นราบ ติดกับคูน้ำด้านใต้ของเมืองโบราณ แหล่งน้ำสำคัญใกล้เคียง ได้แก่ ลำเสียวใหญ่ อยู่ทางเหนือประมาณ 500 เมตร และลำเตา อยู่ทางใต้ราว 2 กิโลเมตรกู่เมืองบัวได้รับการขึ้นทะเบียนเป็นโบราณสถานของชาติ ประกาศในราชกิจจานุเบกษา เล่ม 114 ตอนพิเศษ 80ง ลงวันที่ 12 กันยายน พ.ศ. 2540 กำหนดพื้นที่โบราณสถานประมาณ 9 ไร่ 91.43 ตารางวาปัจจุบันพื้นที่กู่เมืองบัวใช้เป็นศาลปู่ตาประจำหมู่บ้าน', NULL, NULL, '15.6038977', '103.5925972', 'เมืองบัว', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '146', '3', '50', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk196/2026-04-09_16-02-17_S__9617420_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk196/2026-04-09_16-02-21_S__9617421_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk196/2026-04-09_16-03-46_S__13197322_0.jpg\"]'),
('67', 'PK195', 'ศาลเจ้าเมืองเจียม', 'ศาลเจ้าเมืองเจียมเป็นศาลที่สร้างขึ้นเพื่อบูชาเจ้าปู่เมืองเจียม ผีปู่ตาผู้คุ้มครองบ้านเมืองบัว ซึ่งเชื่อกันว่าเป็นอดีตเจ้าเมืองที่ดูแลปกปักรักษาชุมชนมาตั้งแต่สมัยโบราณ ชาวบ้านจึงร่วมกันตั้งศาลขึ้นบริเวณดอนกู่เมืองบัวเพื่อเป็นที่สักการะและประกอบพิธีกรรมประจำท้องถิ่น', NULL, NULL, '15.6035807', '103.5926715', 'เมืองบัว', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '58', '2', '22', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk195/2026-04-09_15-40-20_S__13197333_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk195/2026-04-09_15-40-23_S__13197334_0.jpg\"]'),
('68', 'PK194', 'เจ้าปู่เมืองเจียม', 'เจ้าปู่เมืองเจียม ผีปู่ตาประจำบ้านเมืองบัว เจ้าปู่เมืองเจียมเป็นอดีตเจ้าเมืองที่ปกปักรักษาบ้านเมืองบัวมาตั้งแต่ครั้งโบราณ ชุมชนทำรูปเคารพไว้ บริเวณดอนกู่เมืองบัว', NULL, NULL, '15.6034529', '103.5953455', 'เมืองบัว', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '35', '3', '18', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk194/2026-04-09_15-35-43_S__13197327_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk194/2026-04-09_15-35-46_S__13197328_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk194/2026-04-09_15-35-50_S__13197329_0.jpg\"]'),
('69', 'PK193', 'โปง', 'โปง (พบที่ วัดป่าศรีปทุมวนาราม ตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด)“โปง” คือระฆังไม้โบราณที่ใช้กันในวัดไทยมาแต่สมัยก่อน ทำจากไม้เนื้อแข็งที่เจาะให้เป็นโพรงเพื่อให้เกิดเสียงกังวานเมื่อถูกตี เสียงโปงที่ทุ้มลึกเป็นเอกลักษณ์นั้นทำให้ผู้คนในชุมชนรับรู้ได้ทันทีว่าเป็นสัญญาณจากวัด ไม่ว่าจะเป็นการบอกเวลาออกบิณฑบาตในตอนเช้า ซึ่งเรียกว่า “โปงเช้า” หรือสัญญาณทำวัตรสวดมนต์ในตอนเย็นที่เรียกว่า “โปงแลง” นอกจากนี้ยังถูกใช้เพื่อเรียกประชุมชาวบ้านหรือแจ้งเหตุสำคัญต่าง ๆ ภายในชุมชนอีกด้วย แม้จะเป็นเพียงเครื่องมือเรียบง่าย แต่โปงมีคุณค่าทางวัฒนธรรมอย่างยิ่ง เพราะเป็นสัญลักษณ์ของวิถีชีวิตแบบไทยในสังคมชนบทที่วัดเป็นศูนย์กลางของชุมชน เสียงโปงจึงไม่ใช่แค่เสียงเรียกเวลา แต่ยังเป็นเสียงที่เชื่อมโยงความเป็นอยู่ของผู้คนเข้ากับศาสนาและความสงบของวิถีชีวิตดั้งเดิ', NULL, NULL, '15.5833055', '103.6742972', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '169', '1', '51', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk193/2026-04-09_15-07-35_LINE_ALBUM_โปง_260402_1.jpg\"]'),
('70', 'PK192', 'วิหารหลวงปู่บำเพ็ญ ปสนโน', 'วิหารหลวงปู่บำเพ็ญ ปสนโน ตั้งอยู่ภายใน วัดป่าศรีปทุมวนาราม บ้านกู่กาสิงห์ ตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด', NULL, NULL, '15.5823539', '103.6728736', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '26', '2', '13', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk192/2026-04-09_14-59-16_S__13189129_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk192/2026-04-09_14-59-20_S__13189130_0.jpg\"]'),
('71', 'PK191', 'เจดีย์พิพิธภัณฑ์ศรีปทุม', 'เจดีย์พิพิธภัณฑ์ศรีปทุม ตั้งอยู่ในพื้นที่วัดวัดป่าศรีปทุมวนาราม ภายในเป็นที่ประดิษฐานพระพุทธรูปเพื่อให้ประชาชนได้เข้าไปศักการะ', '11:00:00', '16:00:00', '15.5825007', '103.673667', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '28', '2', '13', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk191/2026-04-09_14-49-16_LINE_ALBUM_เจดีย์พิพิธภัณ_260402_2.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk191/2026-04-09_14-49-20_LINE_ALBUM_เจดีย์พิพิธภัณ_260402_5.jpg\"]'),
('72', 'PK190', 'วัดป่าศรีปทุมวนาราม', 'วัดป่าศรีปทุมวนาราม ตั้งอยู่ที่บ้านกู่กาสิงห์ ตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นวัดป่าสายธรรมที่แวดล้อมด้วยบรรยากาศเงียบสงบและร่มรื่นตามธรรมชาติ เหมาะอย่างยิ่งสำหรับผู้ที่ต้องการมาปฏิบัติธรรม ทำบุญ หรือพักจิตใจจากความวุ่นวายของชีวิตประจำวัน ภายในวัดยังคงวิถีแบบเรียบง่ายตามแนววัดป่า ทำให้ผู้มาเยือนได้สัมผัสความสงบและความร่มเย็น', '08:00:00', '18:00:00', '15.5825007', '103.673667', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '75', '5', '34', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk190/2026-04-09_14-36-08_IMG_1350.JPG\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk190/2026-04-09_14-36-13_IMG_1347.JPG\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk190/2026-04-09_14-39-01_LINE_ALBUM_เจดีย์พิพิธภัณ_260402_9.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk190/2026-04-09_14-39-04_LINE_ALBUM_เจดีย์พิพิธภัณ_260402_3.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk190/2026-04-09_14-39-08_LINE_ALBUM_เจดีย์พิพิธภัณ_260402_4.jpg\"]'),
('73', 'PK189', 'กู่โพนวิจ', 'กู่โพนวิจ ตั้งอยู่บ้านกู่กาสิงห์ ตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด กู่โพนวิจ เป็นโบราณสถานแบบ “กู่” หรือปราสาทหินสถาปัตยกรรมขอมโบราณ สร้างขึ้นราวพุทธศตวรรษที่ 16–17 เพื่อใช้เป็นศาสนสถานประกอบพิธีกรรมทางศาสนา ลักษณะสำคัญคือปราสาทก่ออิฐบนฐานสี่เหลี่ยม มีบันไดทางขึ้นและมีฐานอาคารบริวารโดยรอบ ปัจจุบันกู่โพนวิจได้รับการขึ้นทะเบียนเป็นโบราณสถานแห่งชาติ และประกาศในราชกิจจานุเบกษาเมื่อวันที่ 17 ธันวาคม พ.ศ. 2545 โดยมีพื้นที่รวมประมาณ 15 ไร่ 1 งาน 20 ตารางวา', NULL, NULL, '15.5804456', '103.673507', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '104', '6', '45', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk189/2026-04-09_14-28-56_S__35471440_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk189/2026-04-09_14-29-00_S__35471441_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk189/2026-04-09_14-29-06_IMG_4806.jpeg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk189/2026-04-09_14-29-12_IMG_4807.jpeg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk189/2026-04-09_14-29-20_IMG_4808.jpeg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk189/2026-04-09_14-29-26_IMG_4809.jpeg\"]'),
('74', 'PK188', 'บรรณาลัย', 'บรรณาลัย หมายถึง ห้องสมุด หรือสถานที่ที่สร้างขึ้นเพื่อเก็บรักษาคัมภีร์และเอกสารสำคัญ โดยเฉพาะเอกสารทางศาสนา เช่น คัมภีร์ สมุด หรือใบลาน สำหรับบรรณาลัยในปราสาทกู่กาสิงห์ (ตั้งอยู่ในวัดบูรพากู่กาสิงห์) นั้น อาคารจะอยู่ด้านหลังของปราสาทประธาน และพบฐานอาคารมีลักษณะเป็นรูปสี่เหลี่ยมผืนผ้า', NULL, NULL, '15.576775', '103.676224', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '62', '2', '23', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk188/2026-04-09_14-20-47_S__35471427_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk188/2026-04-09_14-20-50_S__35471428_0.jpg\"]'),
('75', 'PK187', 'ประติมากรรมรูปบุคคล', 'ประติมากรรมรูปบุคคล พบที่ปราสาทกู่โพนวิจ ศิลป่ะเขมรแบบคลัง อายุราวพุทธศตวรรษที่ 16ปัจจุบันจัดแสดงที่ศูนย์จัดแสดงโบราณวัตถุ กู่กาสิงห์', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '29', '2', '14', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk187/2026-04-09_14-06-37_S__35471417_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk187/2026-04-09_14-06-41_S__35471418_0.jpg\"]'),
('76', 'PK186', 'ทับหลังสลักภาพพระไภษัชยคุร', 'ทับหลังสลักภาพพระไภษัชยคุร พบที่ปราสาทกู่โพนระฆัง ศิลปะเขมรแบบบายน อายุราวพุทธศตวรรษที่ ๑๘ปัจจุบันจัดแสดงที่ศูนย์จัดแสดงโบราณวัตถุ กู่กาสิงห์', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '31', '2', '14', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk186/2026-04-09_14-04-24_S__35471414_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk186/2026-04-09_14-04-28_S__35471415_0.jpg\"]'),
('77', 'PK185', 'ยอดซุ้มหน้าบัน', 'ยอดซุ้มหน้าบันพบที่ปราสาท์โพนระฆัง ศิลปะเขมรแบบบายน อายุราวพุทธศตวรรษที่ 18ปัจจุบันนำมาจัดแสดงที่ศูนย์จัดแสดงโบราณวัตถุ กู่กาสิงห์', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '29', '2', '14', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk185/2026-04-09_14-02-12_S__35471411_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk185/2026-04-09_14-02-15_S__35471412_0.jpg\"]'),
('78', 'PK184', 'ยอดซุ้มหน้าบัน', 'ยอดซุ้มหน้าบัน พบที่ปราสาทกูโพนระฆัง ศิลปะเขมรแบบนายน อายุราวพุทธศตวรรษที่ 18ปัจจุบันนำมาจัดแสดงที่ศูนย์จัดแสดงโบราณวัตถุ กู่กาสิงห์', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '29', '2', '14', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk184/2026-04-09_13-59-34_S__35471408_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk184/2026-04-09_13-59-38_S__35471409_0.jpg\"]'),
('79', 'PK163', 'จิตรกรรมฝาผนัง ฉกษัตริย์ 69 พระคาถา', 'จิตรกรรมฝาผนัง ฉกษัตริย์ 69 พระคาถา วัดป่าหนองสะแนนกัณฑ์ฉกษัตริย์ (กัณฑ์ที่ 12) กล่าวถึงช่วงที่พระเจ้าสญชัยและพระนางผุสดียกทัพขึ้นเขาวงกตเพื่อรับพระเวสสันดร ครั้นทั้งหกพระองค์—พระเจ้าสญชัย พระนางผุสดี พระเวสสันดร พระนางมัทรี พระชาลี และพระกัณหา—กลับมาพบกัน ต่างปลาบปลื้มปนโศกจนเป็นลมสิ้นสติ ก่อนจะฟื้นขึ้นด้วยฝนโบกขรพรรษจากเทพยดาใจความสำคัญ: การให้อภัย ความรักของครอบครัว และการกลับมาพบกันหลังการพลัดพรากอานิสงส์: ทำให้ครอบครัวร่มเย็นเป็นสุข', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '99', '1', '31', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk163/2026-04-08_17-01-19_013.jpg\"]'),
('80', 'PK162', 'จิตรกรรมฝาผนัง มหาราช 69 พระคาถา', 'จิตรกรรมฝาผนัง มหาราช 69 พระคาถา วัดป่าหนองสะแนน กัณฑ์มหาราช (กัณฑ์ที่ 11) เล่าเรื่องชูชกพาพระชาลี–พระกัณหาเดินทางกลับเมือง เทวดาแปลงกายมาเลี้ยงดูสองกุมารระหว่างทาง แล้วดลใจให้ชูชกหลงเข้าเมืองสีพี พระเจ้าสญชัยพบและจำหลานได้จึงไถ่ตัวด้วยทรัพย์จำนวนมาก ชูชกได้ลาภมหาศาลแต่ตายเพราะโลภกินอาหารมากเกินไปกัณฑ์นี้เป็นตอนที่สองกุมารได้กลับสู่อ้อมอกพระญาติ และเป็นจุดเริ่มต้นก่อนที่พระเวสสันดรจะเสด็จกลับเมือง.', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '90', '1', '29', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk162/2026-04-08_16-59-02_012.jpg\"]'),
('81', 'PK161', 'จิตรกรรมฝาผนัง สักกบรรพ์ ๔๓ พระคาถา', 'จิตรกรรมฝาผนัง สักกบรรพ์ ๔๓ พระคาถา วัดป่าหนองสะแนน กัณฑ์สักกบรรพ (กัณฑ์ที่ 10) เล่าถึงท้าวสักกะแปลงเป็นพราหมณ์มาขอพระนางมัทรี เพื่อทดสอบบารมีและป้องกันไม่ให้ใครมาขออีก พระเวสสันดรยอมถวายด้วยใจบริสุทธิ์จนแผ่นดินไหว ท้าวสักกะจึงคืนพระนางมัทรีและประทานพร 8 ประการ รวมถึงความเมตตาจากพระราชบิดา ฝนแก้ว 7 ประการ และการไปเกิดในสวรรค์ชั้นดุสิตอานิสงส์: ทำให้เจริญด้วยลาภยศ ผิวพรรณผ่องใส และสุขภาพแข็งแรง', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '87', '1', '28', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk161/2026-04-08_16-56-23_011.jpg\"]'),
('82', 'PK160', 'จิตรกรรมฝาผนัง มัทรี 90 พระคาถา', 'จิตรกรรมฝาผนัง มัทรี 90 พระคาถา วัดป่าหนองสะแนนกัณฑ์มัทรี (กัณฑ์ที่ 9) เล่าเหตุการณ์ที่พระนางมัทรีออกหาผลไม้แล้วพบลางร้ายต่าง ๆ ขณะเดียวกันเทพยดาแปลงกายเป็นสัตว์ร้ายมาขวางทางไม่ให้นางกลับอาศรมทัน เพื่อให้พระเวสสันดรได้บริจาคพระชาลี–พระกัณหาแก่ชูชก เมื่อกลับมาไม่พบลูก นางเสียใจจนสลบ แต่เมื่อฟังเหตุผลจึงยอมรับและอนุโมทนาบุญข้อคิด: ความรักของแม่ การปล่อยวาง และการเสียสละเพื่อประโยชน์อันยิ่งใหญ่อานิสงส์: เชื่อว่าจะมั่งคั่ง อายุยืน และงดงาม', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '98', '1', '31', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk160/2026-04-08_16-54-09_010.jpg\"]'),
('83', 'PK159', 'จิตรกรรมฝาผนัง กุมาร 101 พระคาถา', 'จิตรกรรมฝาผนัง กุมาร 101 พระคาถา วัดป่าหนองสะแนนกัณฑ์กุมาร (กัณฑ์ที่ 8) เล่าเหตุการณ์ที่ชูชกมาทูลขอพระชาลีและพระกัณหาจากพระเวสสันดร ขณะพระนางมัทรีไม่อยู่ พระกุมารทั้งสองพยายามหนีไปซ่อนในสระบัว แต่พระเวสสันดรทรงตามเรียกและมอบให้ด้วยใจเด็ดเดี่ยวเพื่อบำเพ็ญบุตรทานบารมี หลังจากนั้นชูชกมัดและเฆี่ยนตีเด็กทั้งสองระหว่างทาง ทำให้พระเวสสันดรต้องทรงอดกลั้นความเศร้าไว้', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '79', '1', '26', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk159/2026-04-08_16-51-56_009.jpg\"]'),
('84', 'PK158', 'จิตรกรรมฝาผนัง มหาพน 81 พระคาถา', 'จิตรกรรมฝาผนัง มหาพน 81 พระคาถา วัดป่าหนองสะแนนกัณฑ์มหาพน (กัณฑ์ที่ ๗) เล่าเหตุการณ์ที่ชูชกเดินทางผ่านป่าใหญ่จนมาพบพระอัจจุตฤาษี แล้วใช้วาจาหวานล่อลวงจนฤาษีหลงเชื่อและบอกทางไปยังอาศรมพระเวสสันดร แม้เริ่มแรกจะระแวงก็ตามกัณฑ์นี้เน้นภาพความงามของป่าและสัตว์ป่า พร้อมข้อคิดว่า ผู้มีปัญญาแต่ขาดไตร่ตรองอาจถูกหลอกได้ง่าย และการเชื่อใจผู้อื่นโดยไม่พิจารณาอาจก่อให้เกิดปัญหาในภายหลัง', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '83', '1', '27', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk158/2026-04-08_16-49-27_008.jpg\"]'),
('85', 'PK157', 'จิตรกรรมฝาผนัง จุลพล 34 พระคาถา', 'จิตรกรรมฝาผนัง จุลพล 34 พระคาถา วัดป่าหนองสะแนน กัณฑ์จุลพน (กัณฑ์ที่ 6) เล่าเหตุการณ์ที่ชูชกเดินทางถึงป่าโปร่งและพบพรานเจตบุตร ถูกหมาไล่จนต้องขึ้นต้นไม้ ก่อนใช้ไหวพริบหลอกพรานว่าตนเป็นราชทูตจากพระเจ้าสญชัยมาขอพระเวสสันดรกลับเมือง พรานเจตบุตรจึงหลงเชื่อและพาเขาไปยังเขาวงกตกัณฑ์นี้สะท้อนความเจ้าเล่ห์ของชูชก และความซื่อสัตย์ต่อหน้าที่ของพรานเจตบุตร พร้อมความเชื่อว่า ผู้บูชากัณฑ์นี้จะได้สมบัติและบริวารสมบูรณ์', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '90', '1', '29', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk157/2026-04-08_16-34-18_007.jpg\"]'),
('86', 'PK156', 'จิตรกรรมฝาผนัง ชูชก 79 พระคาถา', 'จิตรกรรมฝาผนัง ชูชก 79 พระคาถา วัดป่าหนองสะแนน กัณฑ์ชูชก (กัณฑ์ที่ 5) เล่าเรื่องพราหมณ์เฒ่าชูชก ผู้โลภและเจ้าเล่ห์ มีภรรยาสาวชื่อ นางอมิตตดา ซึ่งถูกพราหมณีในหมู่บ้านอิจฉาและกลั่นแกล้งจนบีบให้นางสั่งชูชกไปขอ พระชาลี–พระกัณหา จากพระเวสสันดรมาเป็นทาสรับใช้ชูชกจึงออกเดินทางอย่างลำบาก และใช้เล่ห์กลหลอกพรานเจตบุตรเพื่อผ่านทางไปยังเขาวงกต จุดเด่นของกัณฑ์นี้คือการสะท้อนความโลภ ความริษยา และผลเสียของการฝากทรัพย์ไว้กับผู้อื่น อีกทั้งยังชูคุณสมบัติของภรรยาที่ซื่อสัตย์และกตัญญู', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '103', '1', '32', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk156/2026-04-08_16-25-52_006.jpg\"]'),
('87', 'PK155', 'จิตรกรรมฝาผนัง กัณฑ์ประเวศน์ 57 พระคาถา', 'จิตรกรรมฝาผนัง กัณฑ์ประเวศน์ 57 พระคาถา วัดป่าหนองสะแนน กัณฑ์วนประเวศน์ (กัณฑ์ที่ 4) เล่าเหตุการณ์ที่พระเวสสันดร พระนางมัทรี ชาลี และกัณหา เดินทางสู่เขาวงกตหลังถูกเนรเทศ ระหว่างทางพบกษัตริย์เจตราช ผู้เชิญพระเวสสันดรครองเมือง แต่พระองค์ปฏิเสธเพราะตั้งใจจะบำเพ็ญพรต กษัตริย์เจตราชจึงส่งเสด็จจนถึงเขาวงกต ซึ่งท้าวสักกะโปรดให้ท้าววิษณุกรรมเนรมิตอาศรมถวาย และเทพยดาย่นระยะทางให้ถึงในวันเดียวข้อคิด: มิตรแท้ช่วยเหลือกันในยามทุกข์ และความมั่นคงในความดีแม้ต้องฝ่าความลำบาก', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '102', '1', '32', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk155/2026-04-08_16-22-30_005.jpg\"]'),
('88', 'PK154', 'จิตรกรรมฝาผนัง ทานกันฑ์ 209 พระคาถา', 'จิตรกรรมฝาผนัง ทานกันฑ์ 209 พระคาถา วัดป่าหนองสะแนนทานกัณฑ์ เป็นกัณฑ์ที่ 3 ในมหาเวสสันดรชาดก ประกอบด้วย 209 พระคาถา เนื้อหากล่าวถึงเหตุการณ์ที่พระเวสสันดรทรงประกอบ “สัตตสดกมหาทาน” คือการบริจาคทรัพย์ครั้งใหญ่ที่สุดก่อนเสด็จออกจากเมืองสีพี โดยพระองค์ประทานสิ่งของ 7 ประเภท อย่างละ 700 ได้แก่ ช้าง ม้า รถ นารี ทาส ทาสี และแม่โคนม เพื่อสั่งสมทานบารมีให้ถึงขั้นสูงสุดกัณฑ์นี้บรรยายช่วงเวลาสำคัญก่อนที่พระเวสสันดร พระนางมัทรี รวมทั้งพระชาลีและพระกัณหาจะออกเดินทางเข้าสู่ป่าหิมพานต์ การทำทานครั้งใหญ่กินเวลาถึง 7 วัน 7 คืน แสดงให้เห็นถึงความไม่หวั่นไหวของพระโพธิสัตว์แม้จะถูกชาวเมืองขับไล่ในด้านอานิสงส์ เชื่อว่าผู้บูชาหรือฟังทานกัณฑ์จะได้รับความสมบูรณ์ด้วยทรัพย์สินเงินทอง มีบริวารมาก และเมื่อสิ้นชีวิตจะได้ไปเกิดในสวรรค์ชั้นสูงมีปราสาท 7 ชั้นกัณฑ์นี้จึงเป็นตอนสำคัญที่นิยมใช้ในการเทศน์มหาชาติ เพื่อย้ำคุณค่าของการให้และการสั่งสมทานบารมีอย่างยิ่งยวด', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '185', '1', '56', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk154/2026-04-08_16-19-47_004.jpg\"]'),
('89', 'PK153', 'จิตรกรรมฝาผนัง หิมพานต์ 134 พระคาถา', 'จิตรกรรมฝาผนัง หิมพานต์ 134 พระคาถา วัดป่าหนองสะแนน กัณฑ์หิมพานต์ เป็นกัณฑ์ที่ 2 ในมหาเวสสันดรชาดก รวมทั้งสิ้น 134 พระคาถา เล่าเหตุการณ์สำคัญที่เป็นจุดเริ่มต้นของเส้นทางแห่งทานบารมีอันยิ่งใหญ่ของพระเวสสันดร โดยเนื้อหาครอบคลุมตั้งแต่ช่วงประสูติ การได้รับช้างมงคลคู่บ้านคู่เมือง จนถึงเหตุการณ์ที่พระองค์บริจาคช้างปัจจัยนาเคนทร์ให้แก่พราหมณ์จากกลิงคราษฎร์ ซึ่งนำไปสู่การเนรเทศพระองค์ในที่สุดเรื่องเริ่มจากพระนางผุสดีจุติมาเกิดในโลกมนุษย์และให้ประสูติพระเวสสันดร ณ ตรอกพ่อค้า ในวันเดียวกันนั้น ช้างมงคล “ปัจจัยนาเคนทร์” ก็ได้มาปรากฏในเมือง ถือเป็นลางบอกเหตุแห่งความอุดมสมบูรณ์ของแผ่นดิน ต่อมาเมื่อพระเวสสันดรเจริญวัย พระองค์ทรงเป็นผู้เอื้อเฟื้อต่อการให้เป็นนิจ การบริจาคทานเป็นเสมือนธรรมชาติประจำใจภายหลังเกิดภาวะแห้งแล้งในเมืองกลิงคราษฎร์ พราหมณ์กลุ่มหนึ่งจึงเดินทางมาขอช้างปัจจัยนาเคนทร์เพื่อแก้ภัยแล้ง พระเวสสันดรเห็นว่าเป็นประโยชน์แก่ผู้คนจำนวนมาก จึงทรงประทานช้างมงคลให้โดยไม่ลังเล แต่เหตุการณ์นี้ทำให้ชาวเมืองสีพีพากันไม่พอใจอย่างยิ่ง เพราะช้างมงคลถือเป็นสิริมงคลของบ้านเมือง พวกเขาจึงร่วมกันกราบทูลพระเจ้าสญชัยเพื่อขอให้เนรเทศพระเวสสันดรออกจากเมืองท้ายที่สุด พระเจ้าสญชัยจำต้องยอมตามเสียงประชาชน พระเวสสันดรจึงเตรียมออกจากเมืองไปยังเขาวงกตในป่าหิมพานต์ พระนางมัทรีพร้อมพระโอรสชาลีและพระธิดากัณหาก็ขอติดตามไปด้วย เพื่อร่วมบำเพ็ญตบะและทานบารมีกับพระองค์อานิสงส์ของการฟังเทศน์กัณฑ์หิมพานต์ เชื่อว่าผู้ฟังจะสมปรารถนาสิ่งที่ตั้งใจไว้ และเป็นการสั่งสมบารมีเพื่อความก้าวหน้าทางธรรม', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '301', '1', '89', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk153/2026-04-08_15-48-45_003.jpg\"]'),
('90', 'PK152', 'จิตรกรรมฝาผนัง ทศพร 19 พระคาถา', 'จิตรกรรมฝาผนัง ทศพร 19 พระคาถา วัดป่าหนองสะแนนกัณฑ์ทศพร เป็นกัณฑ์แรกของมหาเวสสันดรชาดก เล่าเรื่องพระนางผุสดี เทพอัปสรที่กำลังจะจุติลงมาเกิดเป็นพระมารดาของพระเวสสันดร ท้าวสักกะได้ประทานพร 10 ประการแก่พระนาง เช่น ความงาม ความเป็นที่รัก และการมีโอรสผู้ยิ่งใหญ่ เมื่อจุติมาแล้ว พระนางผุสดีได้เกิดเป็นพระราชธิดากรุงมัทราช และภายหลังอภิเษกกับพระเจ้าสัญชัย กัณฑ์นี้จึงเป็นบทนำที่กล่าวถึงบุญบารมีและเหตุปัจจัยที่รองรับการบังเกิดของพระโพธิสัตว์ในชาติสุดท้าย', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '97', '1', '31', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk152/2026-04-08_15-31-43_002.jpg\"]'),
('91', 'PK151', 'จิตรกรรมฝาผนัง ปฐมเหตุเทศมหาชาติ', 'จิตรกรรมฝาผนัง ปฐมเหตุเทศมหาชาติ วัดป่าหนองสะแนน ปฐมเหตุพระเวสสันดรชาดก คือจุดเริ่มต้นของเรื่องราวมหาชาติทั้ง 13 กัณฑ์ อธิบายว่าทำไมพระเวสสันดรจึงทรงเป็นผู้บำเพ็ญทานบารมีอย่างยิ่งใหญ่ และเหตุใดเหตุการณ์สำคัญต่าง ๆ จึงเกิดขึ้นตามลำดับตามคติเดิม กล่าวว่าพระโพธิสัตว์ได้ตั้งความปรารถนามาช้านานว่าจะบำเพ็ญทานบารมีให้ถึงที่สุด เพื่อเป็นปัจจัยให้ได้ตรัสรู้ในชาติสุดท้าย เมื่อเสวยพระชาติเป็นพระเวสสันดร พระองค์จึงมีสันดานแห่งการให้เต็มเปี่ยม ทั้งทรงบริจาคทรัพย์สิ่งของและดูแลบ้านเมืองด้วยใจเมตตาไม่เลือกผู้ใดเหตุการณ์สำคัญที่ถือเป็น “ปฐมเหตุ” ของความโกลาหลในเรื่อง คือการที่พระเวสสันดรทรงบริจาค ช้างปัจจัยนาค ช้างคู่บ้านคู่เมืองซึ่งเป็นสัญลักษณ์แห่งความอุดมสมบูรณ์แก่พราหมณ์จากเมืองกลิงคราษฎร์ การให้ครั้งนี้สร้างความเดือดร้อนแก่ประชาชนอย่างมาก เพราะช้างเป็นเครื่องหมายแห่งโชคลาภและความมั่นคงของรัฐ ชาวเมืองจึงพร้อมใจกันทูลขอให้พระเจ้าสญชัย พระราชบิดา ส่งพระเวสสันดรออกจากเมืองเมื่อถูกเนรเทศไปยังป่าหิมพานต์ เหตุการณ์ต่าง ๆ ในมหาชาติจึงดำเนินตามลำดับ จนกลายเป็นการบำเพ็ญทานบารมีขั้นสูงสุด ได้แก่– การมอบทรัพย์สิ่งของทั้งหมด– การบริจาคพระราชโอรสชาลีและพระธิดากัณหา– และท้ายที่สุดคือการบริจาคพระนางมัทรีเหตุการณ์เหล่านี้ทำให้พระเวสสันดรถูกยกย่องว่าเป็นผู้ทรงบำเพ็ญทานบารมีสูงสุดในชาดกทั้งปวง และเป็นรากฐานสำคัญของเรื่องมหาเวสสันดรชาดกทั้ง 13 กัณฑ์', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '273', '1', '81', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk151/2026-04-08_15-17-54_001.jpg\"]'),
('92', 'PK150', 'จิตรกรรมฝาผนัง แบ่งสารีริกธาตุ', 'จิตรกรรมฝาผนัง แบ่งสารีริกธาตุ วัดป่าหนองสะแนน หลังจากพระสัมมาสัมพุทธเจ้าปรินิพพาน ณ สาลวโนทยาน เมืองกุสินารา ได้เกิดความขัดแย้งระหว่างกษัตริย์จากหลายแคว้นที่ต่างต้องการอัญเชิญพระบรมสารีริกธาตุไปบรรจุสถูปเพื่อถวายบูชา เพื่อระงับความวุ่นวาย โทณพราหมณ์ จึงได้รับมอบหมายให้เป็นผู้แบ่งพระบรมธาตุอย่างเป็นธรรม โดยใช้ ทะนานทอง เป็นเครื่องตวง แบ่งพระบรมธาตุออกเป็น 8 ส่วนเท่า ๆ กันกษัตริย์และเมืองที่ได้รับพระบรมธาตุทั้ง 8 ส่วน ได้แก่กุสินารา (มัลลกษัตริย์)ราชคฤห์ (พระเจ้าอชาตศัตรู)เวสาลี (ลิจฉวี)กบิลพัสดุ์ (ศากยะ)อัลลกัปปะ (ถูลวิกะกษัตริย์)รามคาม (โกลิยะ)เวฏฐทีปกะ (พราหมณ์)ปาวา (มัลลกษัตริย์)ส่วนทะนานทองที่ใช้ตวงนั้น โทณพราหมณ์เก็บไว้เป็นที่ระลึกและสร้างสถูปบรรจุในภายหลังลักษณะของพระบรมสารีริกธาตุ แบ่งออกเป็นสองประเภทนวิปปกิณหาธาตุ หรือ ธาตุไม่แตก เช่น พระเขี้ยวแก้วทั้ง 4 องค์ และพระรากขวัญวิปปกิณหาธาตุ หรือ ธาตุแตก ซึ่งพบได้ 3 ขนาด คือ• ขนาดเล็ก เท่าเมล็ดผักกาด• ขนาดกลาง เท่าเมล็ดข้าวสารหัก• ขนาดใหญ่ เท่าเมล็ดถั่วเขียวผ่าซีกเหตุการณ์แบ่งพระบรมสารีริกธาตุครั้งนี้จึงเป็นจุดเริ่มต้นที่ทำให้พระบรมธาตุกระจายไปตามแคว้นสำคัญต่าง ๆ และภายหลังได้ถูกบูชาในสถูปเจดีย์ทั่วชมพูทวีป ถือเป็นหลักฐานสำคัญที่แสดงถึงความศรัทธาอย่างสูงสุดของกษัตริย์และประชาชนต่อพระพุทธเจ้า', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '265', '1', '79', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk150/2026-04-08_14-54-24_32.jpg\"]'),
('93', 'PK149', 'จิตรกรรมฝาผนัง พระพุทธเจ้าปรินิพพาน', 'จิตรกรรมฝาผนัง พระพุทธเจ้าปรินิพพาน วัดป่าหนองสะแนน เหตุการณ์ปรินิพพานของพระสัมมาสัมพุทธเจ้า : บทสุดท้ายแห่งพุทธจริยาเหตุการณ์ ปรินิพพานของพระสัมมาสัมพุทธเจ้า ถือเป็นหนึ่งในช่วงเวลาสำคัญที่สุดของพระพุทธศาสนา เป็นบทอวสานของพระพุทธองค์ผู้ทรงตรัสรู้ธรรม และบำเพ็ญพุทธกิจตลอด 45 พรรษา เพื่อโปรดเวไนยสัตว์ให้พ้นทุกข์ พระพุทธเจ้าทรงเสด็จดับขันธปรินิพพานเมื่อพระชนมายุ 80 พรรษา ณ สาลวโนทยาน เมืองกุสินารา ในคืนวันเพ็ญเดือน 6 ตรงกับวันวิสาขบูชาอันเป็นมงคลใหญ่ในพระพุทธศาสนาก่อนทรงปรินิพพานประมาณ 3 เดือน พระองค์ได้ประกาศปลงอายุสังขารที่ ปาวาลเจดีย์ โดยทรงตรัสว่า “บัดนี้เราล่วงความป่วยไข้มิได้” แสดงให้เห็นว่าพระองค์เตรียมเสด็จดับขันธ์ด้วยจิตที่สงบและมั่นคง พร้อมฝากภารกิจสำคัญที่สุดไว้แก่พระสาวกทั้งหลายว่า“ธรรมและวินัยที่เราตถาคตแสดงไว้แล้วจักเป็นศาสดาของเธอทั้งหลายต่อไป”คำสอนนี้ยังคงเป็นหลักนำทางของชาวพุทธทั่วโลกมาจนถึงปัจจุบันในช่วงท้ายของพระชนมชีพ พระพุทธองค์ทรงประชวรหลังเสวยภัตตาหารชื่อ “สุกรมัททวะ” ที่นายจุนทะถวาย แม้ภัตนี้จะเป็นเหตุให้พระองค์ทรงอาพาธหนัก แต่กลับทรงย้ำว่า ผู้ถวายภัตตาหารทั้งสองมื้อ คือมื้อก่อนตรัสรู้กับมื้อก่อนปรินิพพาน ล้วนมีอานิสงส์แรงกล้าไม่ยิ่งหย่อนกว่ากัน เพื่อป้องกันความเสื่อมศรัทธาของนายจุนทะคืนสุดท้าย ณ ใต้ต้นสาละคู่ พระพุทธองค์ทรงประทาน ปัจฉิมโอวาท ซึ่งกลายเป็นคำสอนที่สำคัญและทรงคุณค่าที่สุดบทหนึ่งในพระพุทธศาสนา“สังขารทั้งหลายมีความเสื่อมไปเป็นธรรมดาท่านทั้งหลายจงยังความไม่ประมาทให้ถึงพร้อมเถิด”(อปฺปมาเทน สมฺปาเทถ)คำสอนนี้คือเครื่องเตือนใจให้มนุษย์ตระหนักถึงความไม่เที่ยงของสรรพสิ่ง และมุ่งมั่นทำความดีในทุกลมหายใจก่อนปรินิพพานไม่นาน พระองค์ได้อุปสมบท สุภัททะปริพาชก ให้เป็นภิกษุ ซึ่งนับเป็นพระสาวกรูปสุดท้าย จากนั้นจึงเข้าสู่สมาบัติชั้นต่าง ๆ ด้วยจิตสงบและบริสุทธิ์ จนเสด็จดับขันธ์ปรินิพพานอย่างสง่างามเหตุการณ์ทั้งหมดถูกบันทึกไว้อย่างละเอียดใน มหาปรินิพพานสูตร ซึ่งเป็นหลักฐานสำคัญทางประวัติศาสตร์และเป็นแหล่งกำเนิดแนวคิดเรื่อง ไตรลักษณ์ คือ อนิจจัง ทุกขัง อนัตตา ที่แสดงให้เห็นว่าปรากฏการณ์เกิดขึ้น ตั้งอยู่ ดับไป เป็นธรรมชาติของสรรพสัตว์ แม้แต่พระสัมมาสัมพุทธเจ้าก็ไม่ทรงอยู่นอกกฎเกณฑ์นี้การปรินิพพานของพระพุทธองค์จึงไม่ใช่เพียงการสิ้นพระชนม์ แต่เป็นการประกาศธรรมสูงสุดให้ปรากฏอย่างสมบูรณ์', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '447', '1', '131', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk149/2026-04-08_14-42-09_31.jpg\"]'),
('94', 'PK148', 'จิตรกรรมฝาผนัง โปรดองคุลีมาล', 'จิตรกรรมฝาผนัง โปรดองคุลีมาล วัดป่าหนองสะแนน องคุลิมาล : จากมหาโจรสู่พระอรหันต์ ผู้พิสูจน์พลังแห่งเมตตาและการกลับใจเรื่องราวของ องคุลิมาล ถือเป็นหนึ่งในพุทธประวัติที่สะเทือนใจและทรงคุณค่าที่สุด เพราะแสดงให้เห็นว่ามนุษย์สามารถเปลี่ยนจากความมืดมนที่สุด ไปสู่แสงสว่างแห่งธรรมได้ด้วยพลังของเมตตาและปัญญาองคุลิมาล เดิมมีนามว่า อหิงสกะ เป็นศิษย์เอกผู้เฉลียวฉลาดของอาจารย์ทิศาปาโมกข์ แต่ด้วยความริษยาและกลลวงของเพื่อนร่วมสำนัก ทำให้อาจารย์เข้าใจผิดจนอยากกำจัดเขา จึงสั่งให้ไปฆ่าคนให้ครบ 1,000 คนเพื่อ “สำเร็จวิชา” อหิงสกะหลงเชื่อและเริ่มฆ่าผู้คน พร้อมตัดนิ้วทำเป็นพวงมาลัยจนได้รับฉายาว่า องคุลิมาลเมื่อฆ่าคนครบ 999 คนแล้ว ผู้ที่จะตกเป็นเหยื่อคนสุดท้ายกลับเป็น มารดาของตนเอง พระพุทธเจ้าทรงเล็งเห็นว่าหากปล่อยไว้ องคุลิมาลจะทำบาปหนักจนไม่มีโอกาสกลับใจ จึงเสด็จไปโปรดก่อนที่เขาจะลงมือฆ่าแม่องคุลิมาลวิ่งไล่พระพุทธเจ้าอย่างสุดกำลัง แต่ไม่อาจตามทันแม้พระองค์จะเพียง “เดินธรรมดา” ปาฏิหาริย์นี้ทำให้โจรผู้โหดเหี้ยมเกิดความสงสัยและตะโกนบ่นว่า“สมณะ หยุดก่อน!”พระพุทธเจ้าได้ตรัสตอบด้วยวาจาที่เปลี่ยนชีวิตเขาตลอดกาลว่า“เราหยุดแล้วจากการทำบาป แต่ท่านยังไม่หยุด”ถ้อยคำนั้นทำให้องคุลิมาลเกิดสติทันที เขาตระหนักว่าชีวิตที่ผ่านมาเต็มไปด้วยความเขลาและการหลงผิด จึงทิ้งดาบ ก้มลงกราบพระพุทธเจ้า และทูลขอบรรพชา พระองค์ก็ทรงรับเขาเข้าสู่สมณเพศโดยกล่าวเพียงว่า“เอหิภิกขุ – จงเป็นภิกษุเถิด”หลังจากนั้น องคุลิมาลตั้งใจปฏิบัติธรรมอย่างจริงจัง แม้ต้องเผชิญกับการถูกประชาชนขว้างตีเพราะความแค้นในอดีต แต่เขาก็อดทนและสำรวมใจ จนในที่สุดได้บรรลุเป็น พระอรหันต์ ผู้สิ้นกิเลสโดยสมบูรณ์เรื่องราวขององคุลิมาลสอนให้รู้ว่าคนเลวที่สุดยังสามารถกลับใจได้เมตตาธรรมมีพลังเปลี่ยนชีวิตความอดทนและการปฏิบัติธรรมสามารถชำระบาปกรรมในอดีตไม่มีใครต่ำต้อยเกินกว่าจะเริ่มต้นใหม่องคุลิมาลจึงกลายเป็นสัญลักษณ์แห่งการให้อภัย การกลับตัวจากความผิด และชัยชนะของธรรมะเหนือความมืดแห่งอวิชชา เป็นเรื่องที่ยังคงให้ข้อคิดแก่คนทุกยุคทุกสมัยว่า ตราบใดที่ยังมีสติและศรัทธา มนุษย์ย่อมมีโอกาสเริ่มต้นใหม่เสมอ', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '406', '1', '119', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk148/2026-04-08_14-29-28_30.jpg\"]'),
('95', 'PK129', 'จิตรกรรมฝาผนัง หนีบรรพชา', 'จิตรกรรมฝาผนัง หนีบรรพชา วัดป่าหนองสะแนน เจ้าชายสิทธัตถะทรงเสด็จออกบรรพชาเมื่อพระชนมายุได้ 29 พรรษา เหตุการณ์นี้เกิดขึ้นในยามสามของคืนหนึ่ง ซึ่งเป็นช่วงที่ทุกสิ่งในวังเงียบสงบ พระองค์เสด็จออกจากวังพร้อมนายฉันนะและม้ากัณฐกะ มุ่งหน้าไปสู่หนทางแห่งการแสวงหาความหลุดพ้น การตัดสินใจครั้งนี้มีจุดกำเนิดจากการทอดพระเนตรเทวทูตทั้งสี่ คือ คนแก่ คนเจ็บ คนตาย และสมณะ ภาพเหล่านี้ทำให้พระองค์ตระหนักถึงความไม่เที่ยงและความทุกข์ของชีวิต จนเกิดความตั้งใจแน่วแน่ว่าต้องค้นหาวิธีดับทุกข์ให้กับมวลมนุษย์แม้ในวันนั้นพระโอรสราหุลเพิ่งประสูติ และพระองค์ทรงมีความรักลึกซึ้งต่อครอบครัว แต่กระนั้นพระองค์ก็เลือกละทิ้งความสุขสบายในชีวิตราชาตระกูล เพื่อเดินหน้าสู่เส้นทางที่ยากลำบากและไม่แน่นอน แต่เปี่ยมด้วยความหมายยิ่งใหญ่มีบันทึกเชิงวิชาการบางส่วนเสนอว่า การออกบรรพชาอาจไม่ได้เกิดขึ้นในเวลากลางคืนตามคตินิทานพุทธศาสนาที่เล่าต่อกันมา แต่อาจเป็นการเสด็จออกในเวลากลางวันต่อหน้าพระราชบิดาตามธรรมเนียมของเจ้าชายชนชั้นสูง ซึ่งเป็นประเด็นที่นักประวัติศาสตร์ยังถกเถียงกันอยู่อย่างไรก็ตาม ไม่ว่ารายละเอียดจะเป็นเช่นไร เหตุการณ์นี้ถูกเรียกว่า “มหาภิเนษกรมณ์” หมายถึงการเสด็จออกเพื่อภารกิจอันยิ่งใหญ่ นั่นคือ การค้นพบหนทางพ้นทุกข์ และนำพาสัตว์โลกสู่การรู้แจ้งในสัจธรรม อันนำไปสู่การตรัสรู้เป็นพระสัมมาสัมพุทธเจ้าในเวลาต่อมา', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '260', '1', '77', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk129/2026-04-07_14-55-03_09.jpg\"]'),
('96', 'PK128', 'จิตรกรรมฝาผนัง เทวทูต 4', 'จิตรกรรมฝาผนัง เทวทูต 4 วัดป่าหนองสะแนน เทวทูตทั้ง 4 หรือ “นิมิต 4” เป็นเหตุการณ์สำคัญในพุทธประวัติ เมื่อเจ้าชายสิทธัตถะเสด็จออกประพาสอุทยานและได้ทอดพระเนตรภาพที่สะเทือนพระทัยจนกลายเป็นจุดเริ่มต้นของการออกผนวช ภาพทั้งสี่นี้เป็นสัจธรรมของชีวิตที่ไม่มีผู้ใดหลีกเลี่ยงได้ และทำให้พระองค์ตระหนักถึงความไม่เที่ยงของสังขารมนุษย์ครั้งแรก พระองค์พบชายชรา ผู้มีร่างกายหลังค่อม ผิวเหี่ยวย่น เดินอย่างลำบาก ภาพนั้นทำให้ทรงรู้ว่าทุกชีวิตไม่ว่าใครก็ต้องเผชิญกับความแก่ตามกาลเวลา ต่อมา พระองค์พบคนป่วยนอนครวญครางด้วยความเจ็บไข้ ส่งผลให้ทรงตระหนักว่าความเจ็บป่วยเป็นทุกข์ที่เกิดขึ้นได้กับทุกคนอย่างหลีกเลี่ยงไม่ได้ครั้งที่สาม พระองค์เห็นศพของมนุษย์ที่ไร้ลมหายใจ การจากไปของชีวิตทำให้ทรงสลดพระทัยและเห็นชัดว่า ความตายเป็นปลายทางของสรรพสัตว์ สุดท้าย พระองค์พบสมณะผู้สงบสำรวม สงัดจากโลกย์ ความสงบในดวงหน้านั้นทำให้พระองค์เกิดความเลื่อมใสว่าเส้นทางแห่งความสงบนี้อาจนำไปสู่ความหลุดพ้นจากทุกข์ทั้งปวงเทวทูตทั้ง 4 จึงเป็นเหตุการณ์ที่จุดประกายให้เจ้าชายสิทธัตถะหันหลังให้กับความสุขในราชสำนักและออกแสวงหาหนทางพ้นทุกข์ จนในที่สุดนำไปสู่การตรัสรู้เป็นพระสัมมาสัมพุทธเจ้า', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '229', '1', '68', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk128/2026-04-07_14-41-16_08.jpg\"]'),
('97', 'PK127', 'จิตรกรรมฝาผนัง พระพุทธเจ้าราชาภิเษก', 'จิตรกรรมฝาผนัง พระพุทธเจ้าราชาภิเษก วัดป่าหนองสะแนนพระราชพิธีบรมราชาภิเษกเป็นโบราณราชประเพณีที่ใช้สถาปนาพระมหากษัตริย์ไทยให้ทรงมีพระราชอิสริยยศอย่างสมบูรณ์ ทั้งตามคติพราหมณ์–ฮินดูและพุทธศาสนา ในพระราชพิธีบรมราชาภิเษก พ.ศ. 2562 พระบาทสมเด็จพระวชิรเกล้าเจ้าอยู่หัว (รัชกาลที่ 10) ได้เสด็จฯ ไปยังพระอุโบสถ วัดพระศรีรัตนศาสดาราม เพื่อทรงนมัสการพระพุทธมหามณีรัตนปฏิมากร และประกาศพระองค์เป็นพุทธศาสนูปถัมภก อันเป็นการแสดงพระราชปณิธานว่าจะทรงคุ้มครองและทำนุบำรุงพระพุทธศาสนาในพระราชพิธีประกอบด้วยขั้นตอนสำคัญหลายประการ เช่น การสรงพระมุรธาภิเษก การทรงรับน้ำอภิเษกจากทิศทั้งหลาย และการถวายเครื่องราชกกุธภัณฑ์ ซึ่งเป็นสัญลักษณ์แห่งพระราชอำนาจและพระราชฐานะของพระมหากษัตริย์ การประกอบพระราชพิธีเหล่านี้ไม่เพียงเป็นการสถาปนาพระองค์ขึ้นครองราชย์เท่านั้น แต่ยังสะท้อนถึงแนวคิดเรื่อง “ธรรมราชา” ผู้ทรงปกครองบ้านเมืองด้วยหลักธรรมและทรงเป็นองค์อัครศาสนูปถัมภกตามประเพณีของไทยสืบมา', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '192', '1', '58', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk127/2026-04-07_14-34-50_07.jpg\"]'),
('98', 'PK126', 'จิตรกรรมฝาผนัง พระพุทธเจ้ายกคันศร', 'จิตรกรรมฝาผนัง พระพุทธเจ้ายกคันศร วัดป่าหนองสะแนนเมื่อเจ้าชายสิทธัตถะทรงเจริญวัยจนสำเร็จศิลปศาสตร์ทุกแขนง พระเจ้าสุทโธทนะพระราชบิดามีพระประสงค์จะให้อภิเษกสมรส จึงส่งเทียบเชิญไปยังเหล่าพระญาติวงศ์เพื่อคัดเลือกสตรีผู้เหมาะสม อย่างไรก็ตาม ฝ่ายพระญาติกลับมีคำทักท้วงว่าพระกุมารแม้จะทรงมีสติปัญญาเป็นเลิศ แต่ทรงเรียนเพียงศาสตร์ด้านตำรา ไม่เคยฝึกการใช้อาวุธหรือการรบ จึงอาจไม่เหมาะเป็นกษัตริย์ผู้ปกครองแคว้นได้เพื่อให้พระญาติคลายความกังขา พระเจ้าสุทโธทนะจึงโปรดให้จัดการประลองศิลปศาสตร์ขึ้นอย่างเป็นทางการ มีการนำคันศรศักดิ์สิทธิ์ซึ่งมีน้ำหนักมหาศาลมาเป็นอาวุธสำหรับการทดสอบ ความหนักของคันศรนั้นมากเสียจนไม่มีใครสามารถยกขึ้นได้ แม้บรรดานักรบผู้แข็งแรงก็ไม่อาจแม้แต่ขยับคันศรให้ลอยจากพื้นเมื่อถึงคราวของเจ้าชายสิทธัตถะ เหล่าผู้เฝ้าชมต่างจับจ้องด้วยความหวังจะพิสูจน์ว่าพระองค์จะสามารถทำได้จริงหรือไม่ เจ้าชายก้าวเข้าหาคันศรด้วยความสงบ ไม่ได้แสดงอาการออกแรงหรือยากลำบากแม้แต่น้อย เพียงจับคันศรด้วยพระหัตถ์เดียวก็สามารถยกมันขึ้นได้อย่างง่ายดายราวกับสิ่งไร้น้ำหนัก ต่อจากนั้นทรงขึ้นสายศรและดีดปลายสายหนึ่งครั้ง เสียงดังคล้ายฟ้าผ่าดังก้องไปทั่วทั้งเมืองกบิลพัสดุ์ เป็นสัญญาณที่ทำให้ทุกคนยอมรับในพระกำลังและความสามารถของพระองค์อย่างสิ้นเชิงเหตุการณ์ครั้งนี้ทำให้ความสงสัยของพระญัติวงศ์ถูกลบล้าง เจ้าชายได้รับการยอมรับว่าเป็นผู้มีทั้งปัญญาและพละกำลังควรค่าแก่การเป็นกษัตริย์ในอนาคต จากนั้นไม่นาน เจ้าชายสิทธัตถะก็ได้อภิเษกสมรสกับนางพิมพา หรือพระนางยโสธรา ผู้เป็นคู่ครองสำคัญในพุทธประวัตินอกจากเหตุการณ์ประลองคันศรแล้ว ยังมีเรื่องราวที่เกี่ยวข้องกับพระเมตตาของเจ้าชายในวัยเยาว์ เมื่อครั้งหนึ่งทรงยิงธนูถูกพญาหงส์ แต่เมื่อเห็นว่านกได้รับบาดเจ็บก็ทรงเกิดความสงสาร อุ้มพญาหงส์ขึ้นมาดูแลและเยียวยา แทนที่จะนำไปเป็นอาหารอย่างที่ใครหลายคนคาดคิด เหตุการณ์นี้เป็นอีกตัวอย่างหนึ่งที่แสดงถึงพระมหากรุณาธิคุณของพระองค์ตั้งแต่วัยเยาว์ ซึ่งต่อมากลายเป็นพื้นฐานสำคัญของพระพุทธจริยาในภายหลัง', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '385', '1', '113', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk126/2026-04-07_14-29-54_06.jpg\"]'),
('99', 'PK125', 'จิตรกรรมฝาผนัง พระพุทธเจ้าแรกนาขวัญ', 'จิตรกรรมฝาผนัง พระพุทธเจ้าแรกนาขวัญ วัดป่าหนองสะแนน พิธีแรกนาขวัญในพุทธประวัติ หรือ “วัปปมงคล” เกิดขึ้นเมื่อเจ้าชายสิทธัตถะมีพระชนมายุ 7 พรรษา ขณะพระเจ้าสุทโธทนะทรงไถนาในทุ่งนานอกเมืองกบิลพัสดุ์ เจ้าชายประทับนั่งอยู่เพียงลำพังใต้ต้นหว้า และเข้าฌานจนบรรลุปฐมฌาน เกิดเหตุอัศจรรย์เมื่อเงาต้นหว้าคงอยู่เหนือพระองค์ตลอดเวลา ไม่เอนตามดวงอาทิตย์ พระเจ้าสุทโธทนะทอดพระเนตรเห็น จึงทรงกราบพระกุมารเป็นครั้งที่สองในพระชนม์ชีพสรุปรายละเอียดสำคัญ• สถานที่: ทุ่งนานอกเมืองกบิลพัสดุ์• พระยาแรกนา: พระเจ้าสุทโธทนะ• เจ้าชายสิทธัตถะประทับสมาธิใต้ต้นหว้าเพียงลำพัง• ปาฏิหาริย์: เงาต้นหว้าคงอยู่เหนือพระองค์ตลอดเวลา• พระเจ้าสุทโธทนะกราบพระกุมารเมื่อเห็นปาฏิหาริย์ความแตกต่างกับพิธีไทย• ในพุทธประวัติ “วัปปมงคล” เป็นพิธีหว่านพืชโดยพระราชาทรงไถนาเอง• ในไทย “พระราชพิธีพืชมงคลจรดพระนังคัลแรกนาขวัญ” รวมพิธีพราหมณ์และพิธีสงฆ์ เพื่อให้ขวัญกำลังใจเกษตรกร', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '191', '1', '58', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk125/2026-04-07_14-19-24_05.jpg\"]'),
('100', 'PK124', 'จิตรกรรมฝาผนัง พระพุทธเจ้าทำนายลักษณะ', 'จิตรกรรมฝาผนัง พระพุทธเจ้าทำนายลักษณะ วัดป่าหนองสะแนน เจ้าชายสิทธัตถะเมื่อประสูติ ได้มี พราหมณ์ 8 ท่าน มาทำนายพระลักษณะ โดยเห็นว่าเป็น ลักษณะมหาบุรุษ 32 ประการ ซึ่งบ่งบอกถึงอนาคตอันยิ่งใหญ่ หากครองเรือนจะเป็นพระเจ้าจักรพรรดิ แต่ถ้าออกบวชจะได้ตรัสรู้เป็นพระพุทธเจ้า หนึ่งในนั้นคือ โกณฑัญญะพราหมณ์ ซึ่งมั่นใจที่สุดและทำนายว่าเจ้าชายจะออกบวชแน่นอนสรุปรายละเอียดสำคัญ• พราหมณ์ 7 ท่านทำนายว่าอาจเป็นทั้งจักรพรรดิหรือศาสดา• โกณฑัญญะพราหมณ์ทำนายชัดเจนว่าจะได้ตรัสรู้เป็นพระพุทธเจ้า• ลักษณะที่สังเกตได้สอดคล้องกับ “มหาปุริสลักษณะ 32 ประการ”ตัวอย่างลักษณะสำคัญ• ฝ่าเท้าเรียบเสมอ และมีเครื่องหมายจักร• ผิวกายละเอียดดุจทอง• ร่างกายสูงสมส่วน บ่าเต็ม ผึ่งผาย• พระขนงโค้งดุจคันธนู ดวงตาคมเข้มผลของการทำนาย• เจ้าชายสิทธัตถะเติบโตขึ้นตามคำพยากรณ์ และภายหลังทรงออกผนวช• ในที่สุดตรัสรู้เป็น พระสัมมาสัมพุทธเจ้า', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '179', '1', '54', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk124/2026-04-07_14-14-49_04.jpg\"]')
INSERT INTO `places` (`id`, `place_code`, `place_name`, `description`, `opening_time`, `closing_time`, `latitude`, `longitude`, `subdistrict`, `district`, `province`, `created_at`, `updated_at`, `word_count`, `photo_count`, `expected_read_time`, `images_json`) VALUES
('101', 'PK123', 'จิตรกรรมฝาผนัง พระพุทธเจ้าประสูติ', 'จิตรกรรมฝาผนัง พระพุทธเจ้าประสูติ วัดป่าหนองสะแนน พระพุทธเจ้าทรงประสูติในวันเพ็ญ เดือน 6 ตรงกับวันวิสาขบูชา ณ สวนลุมพินีวัน ระหว่างกรุงกบิลพัสดุ์และกรุงเทวทหะ ซึ่งปัจจุบันอยู่ในประเทศเนปาล เหตุการณ์เกิดขึ้นก่อนพุทธศักราช 80 ปี พระองค์เป็นพระราชโอรสของ พระเจ้าสุทโธทนะ และ พระนางสิริมหามายา แห่งศากยวงศ์เหตุการณ์สำคัญในวันประสูติพระนางสิริมหามายากำลังเสด็จแปรพระราชฐาน เมื่อทรงเจ็บครรภ์และประสูติใต้ร่มไม้สาละเจ้าชายสิทธัตถะประสูติในท่ายืน เป็นเหตุการณ์ประสูติที่ถือว่าน่าอัศจรรย์ในคติพุทธหลังประสูติทรงก้าวเดิน 7 ก้าว โดยมีดอกบัวผุดขึ้นรองรับทุกย่างก้าวข้อมูลสำคัญเกี่ยวกับการประสูติสถานที่: สวนลุมพินีวัน ประเทศเนปาลในปัจจุบันวันประสูติ: วันเพ็ญ เดือน 6 (วันวิสาขบูชา)พระราชบิดา–พระราชมารดา: พระเจ้าสุทโธทนะ และพระนางสิริมหามายาการถวายพระนาม: หลังประสูติ 5 วัน ได้รับพระนามว่า “สิทธัตถะ” หมายถึง “ผู้สำเร็จตามความมุ่งหมาย”', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '187', '1', '56', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk123/2026-04-07_14-11-42_03.jpg\"]'),
('102', 'PK122', 'จิตรกรรมฝาผนัง พระพุทธเจ้าสุบินนิมิต', 'จิตรกรรมฝาผนัง พระพุทธเจ้าสุบินนิมิต วัดป่าหนองสะแนนพระพุทธเจ้าทรงสุบินนิมิตสำคัญก่อนตรัสรู้ เรียกว่า มหาสุบิน 5 ประการ ซึ่งเป็นนิมิตบอกเหตุถึงการตรัสรู้และการเผยแผ่ธรรมไปอย่างกว้างขวาง โดยสรุปได้ดังนี้:ทรงบรรทมเหนือแผ่นดิน มีภูเขาหิมพานต์เป็นหมอนเป็นนิมิตถึงความยิ่งใหญ่ และจะตรัสรู้เป็นพระสัมมาสัมพุทธเจ้าหญ้าแพรกงอกขึ้นจากพระนาภีจนถึงท้องฟ้าสื่อถึงการเกิดขึ้นและการแผ่ขยายของพระธรรม คือ อริยมรรคมีองค์ 8หนอนสีขาวหัวดำไต่ขึ้นมาถึงพระชานุ (เข่า)หมายความว่า คฤหัสถ์จำนวนมากจะเข้ามาเป็นสาวกและนับถือพระองค์นกหลากสีบินมาตกที่พระบาทเป็นสัญลักษณ์ว่าผู้คนจากทุกทิศจะเข้ามาศึกษาและปฏิบัติตามพระธรรมทรงเดินจงกรมบนกองถ่านไฟไม่ร้อนและไม่ระคายเท้าหมายถึงการดำรงชีวิตสมณะอย่างมั่นคง สงบ และสันโดษ', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '153', '1', '47', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk122/2026-04-07_14-01-29_02.jpg\"]'),
('103', 'PK121', 'จิตรกรรมฝาผนัง พระพุทธเจ้าอันเชิญจุติ', 'จิตรกรรมฝาผนัง พระพุทธเจ้าอันเชิญจุติ วัดป่าหนองสะแนนเหตุการณ์อัญเชิญพระพุทธเจ้าอันเชิญจุติ หรือการอัญเชิญท้าวสันดุสิตเทพบุตรให้จุติลงมาเกิด เป็นช่วงสำคัญตอนต้นของพุทธประวัติ เมื่อพระโพธิสัตว์สิ้นอายุชาติสุดท้ายในภพเป็นพระเวสสันดรแล้วไปบังเกิดเป็นท้าวสันดุสิตบนสวรรค์ชั้นดุสิต ซึ่งเป็นที่ประทับของพระโพธิสัตว์ก่อนจะมาตรัสรู้เป็นพระพุทธเจ้า เมื่อบารมีทั้งหลายของพระโพธิสัตว์เต็มบริบูรณ์ หมู่เทวดาและพรหมในหมื่นจักรวาลจึงพร้อมใจกันประชุมเพื่ออัญเชิญให้จุติลงมายังโลกมนุษย์ เพื่อโปรดสัตว์และเปิดโลกแห่งธรรมก่อนจะรับคำอัญเชิญนั้น พระโพธิสัตว์ได้ทรงพิจารณาเงื่อนไขสำคัญ 5 ประการ หรือ “ปัญจมหาวิโลกนะ” ได้แก่ เวลาอันเหมาะสม ทวีปที่จะอุบัติ ประเทศหรือเมืองที่ควรเกิด ตระกูลที่เหมาะสม และพระชนมายุของพระพุทธมารดา หลังจากพิจารณาแล้วเห็นว่าทุกประการสมควรแก่การอุบัติ พระโพธิสัตว์จึงทรงรับคำอัญเชิญและจุติลงมายังครรภ์ของพระนางสิริมหามายา แห่งกรุงกบิลพัสดุ์ เพื่อเสด็จมาตรัสรู้เป็นพระสัมมาสัมพุทธเจ้าต่อไปเหตุการณ์นี้สะท้อนให้เห็นว่าการอุบัติของพระพุทธเจ้าแต่ละพระองค์เกิดจากการสั่งสมบารมีอันยาวนาน และเป็นเหตุการณ์ที่หมู่เทวดาและโลกทั้งสามเห็นพร้อมกันว่าเป็นกาลอันควรแก่การเสด็จมาสั่งสอนสัตว์โลกให้พ้นทุกข์.', NULL, NULL, '15.7230603', '103.5362875', 'เหล่าหลวง', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '242', '1', '72', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk121/2026-04-07_13-58-03_01.jpg\"]'),
('104', 'PK120', 'แท่นหินมงคล', 'แท่นหินมงคล พบที่ปราสาทกู่กาสิงห์ ศิลปะเขมรแบบบาป่วน อายุราวพุทธศตวรรษที่ 16', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '17', '2', '10', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk120/2026-04-07_10-51-40_S__35471405_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk120/2026-04-07_10-51-43_S__35471406_0.jpg\"]'),
('105', 'PK119', 'บันแถลง หรือ บรรพแถลง', 'บันแถลง/บรรพแถลง เป็นเครื่องประดับชั้นหลังคา พบที่ปราสาทกู่โพนระฆัง ศิลปะเขมรแบบบายน อายุราวพุทธศตวรรษที่ 18', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '25', '2', '13', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk119/2026-04-07_10-43-50_S__35471402_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk119/2026-04-07_10-43-53_S__35471403_0.jpg\"]'),
('106', 'PK118', 'กลีบขนุน', 'กลีบขนุน เป็นเครื่องประดับชั้นหลังคาปราสาท พบที่ปราสาทกูโพนระฆัง ศิลปะเขมรแบบบายน อายุราวพุทธศตวรรษที่ 18 ปัจจุบันจัดแสดงที่ศูนย์จัดแสดงโบราณวัตถุ กู่กาสิงห์', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '34', '2', '15', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk118/2026-04-07_10-41-07_S__35471399_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk118/2026-04-07_10-41-10_S__35471400_0.jpg\"]'),
('107', 'PK117', 'ปลายกรอบหน้าบันสลักลายรวยระกา', 'ปลายกรอบหน้าบันสลักลายรวยระกา พบที่ปราสาททู่กาสิงห์ ศิลปะเขมรแบบบาปวนอายุราวพุทธศตวรรษที่ 16', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '21', '2', '11', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk117/2026-04-07_10-20-08_S__35471396_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk117/2026-04-07_10-20-12_S__35471397_0.jpg\"]'),
('108', 'PK116', 'ทับหลังสลักรูปพระอินทร์ประทับนั่งเหนือหน้ากาล', 'ทับหลังสลักรูปพระอินทร์ประทับนั่งเหนือหน้ากาล พบที่ปราสาทกู่กาสิงห์ ศิลปะเขมรแบบบาป่วน อายุราวพุทธศตวรรษที่ 16', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '25', '2', '13', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk116/2026-04-07_10-11-36_S__35471393_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk116/2026-04-07_10-11-40_S__35471394_0.jpg\"]'),
('109', 'PK115', 'ชิ้นส่วนบัวยอดปราสาท', 'ชิ้นส่วนบัวยอดปราสาท เป็นเครื่องประดับชั้นหลังคาปราสาท พบที่ปราสาทกู่กาสิงห์ ศิลปะเขมรแบบบาปวน อายุราวพุทธศตวรรษที่ 16', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '26', '2', '13', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk115/2026-04-07_10-01-44_S__35471388_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk115/2026-04-07_10-01-48_S__35471389_0.jpg\"]'),
('110', 'PK114', 'ปราสาทจำลอง', 'ปราสาทจำลองเป็นเครื่องประดับชั้นหลังคา พบที่ ปราสาทกู่กาสิงห์ ศิลปเขมรแบบบาปวน อายุราวพุทธศตวรรษที่ 16', NULL, NULL, '15.5770331', '103.6736785', 'เมืองบัว', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:22:27', '23', '2', '12', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk114/2026-04-07_09-36-43_S__35471385_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk114/2026-04-07_09-36-46_S__35471386_0.jpg\"]'),
('111', 'PK113', 'หน้าบันสลักภาพกฤษณะโควรรธนะ', 'หน้าบันสลักภาพกฤษณะโควรรธนะ พบที่ปราสาทกู่กาสิงห์ ศิลปะเขมรบาปวน อายุราวพุทธศตวรรษที่ 16', NULL, NULL, '15.577049', '103.676178', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '20', '2', '11', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk113/2026-04-07_09-29-32_S__35471378_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk113/2026-04-07_09-29-36_S__35471379_0.jpg\"]'),
('112', 'PK112', 'ศูนย์จัดแสดงโบราณวัตถุ กู่กาสิงห์ กู่โพนวิจ และกู่โพนระฆัง', 'ศูนย์จัดแสดงโบราณวัตถุ กู่กาสิงห์ กู่โพนวิจ และกู่โพนระฆัง ตั้งอยู่ภายในบริเวณโบราณสถานกู่กาสิงห์ จังหวัดร้อยเอ็ด เป็นพื้นที่รวบรวมโบราณวัตถุที่ค้นพบจากแหล่งโบราณคดีรอบพื้นที่กู่กาสิงห์และกู่ในละแวกเดียวกัน เช่น กู่โพนวิจและกู่โพนระฆัง ภายในศูนย์มีการจัดแสดงวัตถุโบราณที่สะท้อนประวัติศาสตร์และความเชื่อในสมัยโบราณ อาทิ ชิ้นส่วนศิลปกรรม เครื่องใช้ดินเผา และวัตถุที่เกี่ยวข้องกับศาสนสถานโบราณศูนย์แห่งนี้ทำหน้าที่เป็นแหล่งเรียนรู้ให้กับนักท่องเที่ยว นักเรียน และผู้สนใจด้านประวัติศาสตร์ท้องถิ่น โดยให้ข้อมูลเกี่ยวกับความสำคัญของโบราณสถานในพื้นที่ รวมถึงพัฒนาการในยุคต่างๆ', NULL, NULL, '15.5770331', '103.6736785', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '123', '4', '46', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk112/2026-04-07_09-06-59_IMG_1342.JPG\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk112/2026-04-09_14-09-04_IMG_4791.jpeg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk112/2026-04-09_14-09-09_IMG_4786.jpeg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk112/2026-04-09_14-09-13_IMG_4771.jpeg\"]'),
('113', 'PK111', 'ศูนย์ข้อมูลนักท่องเที่ยวกู่กาสิงห์', 'ศูนย์ข้อมูลนักท่องเที่ยวกู่กาสิงห์ ตั้งอยู่บริเวณกลุ่มโบราณสถานกู่กาสิงห์ ทำหน้าที่เป็นจุดต้อนรับและให้บริการข้อมูลแก่นักท่องเที่ยวที่มาเยี่ยมชมพื้นที่', NULL, NULL, '15.577036', '103.676267', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '34', '2', '15', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk111/2026-04-07_08-58-30_IMG_4768.jpeg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk111/2026-04-07_08-58-35_IMG_4769.jpeg\"]'),
('114', 'PK110', 'คลังเก็บวัตถุจัดแสดง โบราณวัตถุ', 'คลังเก็บวัตถุจัดแสดง โบราณวัตถุ อยู่ในบริเวณ กู่กาสิงห์ เป็นอาคารที่สร้างขึ้นเพื่อใช้เป็นสถานที่จัดเก็บ ดูแล และอนุรักษ์โบราณวัตถุที่พบในพื้นที่กู่กาสิงห์', NULL, NULL, '15.57706', '103.676327', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '33', '2', '15', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk110/2026-04-03_16-36-37_S__26058765.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk110/2026-04-07_09-03-55_IMG_1340.JPG\"]'),
('115', 'PK109', 'ก๋วยเตี๋ยวเรืออร่อยสุดในกู่กาสิงห์', 'ก๋วยเตี๋ยวเรืออร่อยสุดในกู่กาสิงห์ เป็นร้านอาหารท้องถิ่นประเภทก๋วยเตี๋ยวเรือ ตั้งอยู่ในตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด ประเทศไทย ร้านนี้ขึ้นชื่อด้านน้ำซุปเข้มข้นและรสชาติจัดจ้านในแบบต้นตำรับ โดยเป็นหนึ่งในจุดแวะยอดนิยมของคนพื้นที่และนักเดินทางที่ผ่านเส้นทางจังหวัดร้อยเอ็ดร้านมีบรรยากาศแบบเรียบง่ายสไตล์ชนบท เน้นความสะดวกสบายและการต้อนรับแบบเป็นกันเอง เหมาะสำหรับทั้งครอบครัวและผู้ที่ต้องการมื้อกลางวันรวดเร็ว ราคาย่อมเยา การจัดพื้นที่ภายในร้านเปิดโล่ง โปร่งสบาย รองรับลูกค้าได้หลายโต๊ะเมนูและจุดเด่นเมนูหลักคือก๋วยเตี๋ยวเรือหมูและเนื้อ ที่ปรุงด้วยน้ำซุปเข้มข้นตามแบบฉบับก๋วยเตี๋ยวเรือไทย เสิร์ฟพร้อมถั่วงอกสดและกากหมูกรอบที่เจียวใหม่ทุกวัน เครื่องเคียงยอดนิยม ได้แก่ หมูตุ๋น เนื้อเปื่อย ลูกชิ้น และหมูสด สำหรับผู้ที่ชอบรสจัดสามารถปรุงเพิ่มด้วยพริกป่นและน้ำส้มพริกดองตามใจชอบความนิยมและความสำคัญแม้จะเป็นร้านขนาดเล็กในชุมชน แต่ “ก๋วยเตี๋ยวเรืออร่อยสุดในกู่กาสิงห์” ได้รับความนิยมในหมู่คนท้องถิ่นและนักท่องเที่ยวที่มาเยือน เนื่องจากรสชาติกลมกล่อมและราคาที่เข้าถึงได้ ร้านยังสะท้อนวัฒนธรรมการกินแบบพื้นบ้านอีสานที่เน้นความเรียบง่ายและความจริงใจในรสชาติ', NULL, NULL, '15.5804378', '103.6678921', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '233', '3', '75', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk109/2026-04-03_14-58-40_LINE_ALBUM_ก๋วยเตี๋ยวเรือ_260402_2.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk109/2026-04-03_14-58-43_LINE_ALBUM_ก๋วยเตี๋ยวเรือ_260402_3.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk109/2026-04-03_14-58-47_LINE_ALBUM_ก๋วยเตี๋ยวเรือ_260402_4.jpg\"]'),
('116', 'PK108', 'ดอนปู่ตา', 'ดอนปู่ตา กู่กาสิงห์ ตั้งอยู่ในเขตบ้านกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นป่าศักดิ์สิทธิ์กลางชุมชนที่ชาวบ้านเคารพนับถือ “ญาพ่อป้องคำสิงห์” ผีปู่ตาบรรพบุรุษผู้คุ้มครองหมู่บ้าน พื้นที่แห่งนี้ถือเป็นเขตต้องห้ามในการตัดฟันต้นไม้และรบกวนธรรมชาติ เนื่องจากเชื่อว่าเป็นที่ประทับของผีปู่ตาหรือผีอารักษ์ประจำหมู่บ้านชาวบ้านจะมีการประกอบพิธีบวงสรวงเป็นประจำทุกปี โดยมักจัดในช่วงบุญบั้งไฟ เพื่อความเป็นสิริมงคลและเพื่อแสดงความกตัญญูกตเวทีต่อผีปู่ตาที่คอยดูแลปกปักรักษาชุมชนอยู่เสมอ', NULL, NULL, '15.5794975', '103.670754', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '106', '4', '41', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk108/2026-04-03_14-28-17_LINE_ALBUM_ดอนปู่ตา_260402_6.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk108/2026-04-03_14-28-21_LINE_ALBUM_ดอนปู่ตา_260402_1.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk108/2026-04-03_14-28-24_LINE_ALBUM_ดอนปู่ตา_260402_3.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk108/2026-04-03_14-28-28_LINE_ALBUM_ดอนปู่ตา_260402_9.jpg\"]'),
('117', 'PK107', 'สวนป่าหลังโรงสี', 'สวนป่าหลังโรงสี กู่กาสิงห์ เป็นพื้นที่สีเขียวที่ชุมชนร่วมกันดูแลและพัฒนาให้เป็นแหล่งปลูกต้นไม้ของหมู่บ้าน', NULL, NULL, '15.5731594', '103.6678909', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '23', '2', '12', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk107/2026-04-03_11-28-58_S__26050579_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk107/2026-04-03_11-29-01_S__26050580_0.jpg\"]'),
('118', 'PK106', 'บินหลา การ์เด้น', 'บินหลา การ์เด้น คือ แหล่งท่องเที่ยวเชิงเกษตร-ธรรมชาติ ในพื้นที่ตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ดเป็นสวนหรือพื้นที่จัดเป็นแหล่งเรียนรู้และพักผ่อน ที่คนมักแวะมาเดินชมสวน บรรยากาศธรรมชาติถ่ายรูป เช็คอินดูการปลูกพืชผัก/ไม้ดอกไม้ประดับพักผ่อนแบบชิล ๆ แนวสวนเกษตรเป็นที่พักบรรยากาศดี ใกล้แหล่งท่องเที่ยวทางประวัติศาสตร์อย่างกู่กาสิงห์ (วัดสว่างอารมณ์) ซึ่งเป็นพื้นที่ชุมชนที่มีวัฒนธรรมเก่าแก่ และมักมีที่พักรองรับนักท่องเที่ยว โดยเฉพาะช่วงเทศกาลอย่างบุญบั้งไฟ การจอง/ติดต่อ: ข้อมูลในโซเชียลมีเดียระบุว่ามีการเปิดรับจอง โดยแนะนำให้เช็คข้อมูลการติดต่อจากชาวบ้านหรือหน่วยงานท้องถิ่นในช่วงเทศกาล เนื่องจากอาจมีการจองล่วงหน้า https://www.facebook.com/Binlarcoffee/', NULL, NULL, '15.5697575', '103.6645104', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '141', '12', '71', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-32_LINE_ALBUM_บินหลาการ์เดนท์_260402_1.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-35_LINE_ALBUM_บินหลาการ์เดนท์_260402_2.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-39_LINE_ALBUM_บินหลาการ์เดนท์_260402_3.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-42_LINE_ALBUM_บินหลาการ์เดนท์_260402_4.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-46_LINE_ALBUM_บินหลาการ์เดนท์_260402_5.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-49_LINE_ALBUM_บินหลาการ์เดนท์_260402_6.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-53_LINE_ALBUM_บินหลาการ์เดนท์_260402_7.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-56_LINE_ALBUM_บินหลาการ์เดนท์_260402_8.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-18-59_LINE_ALBUM_บินหลาการ์เดนท์_260402_9.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-19-03_LINE_ALBUM_บินหลาการ์เดนท์_260402_10.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-19-06_LINE_ALBUM_บินหลาการ์เดนท์_260402_11.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk106/2026-04-03_11-19-10_LINE_ALBUM_บินหลาการ์เดนท์_260402_12.jpg\"]'),
('119', 'PK105', 'สวนป่าเทศบาลหลังโรงเรียนกู่กาสิงห์ประชาสรรค์', 'สวนป่าหลังโรงเรียนกู่กาสิงห์ประชาสรรค์ ตั้งอยู่ในเขตตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นพื้นที่สีเขียวที่อยู่ภายใต้การดูแลของเทศบาลตำบลกู่กาสิงห์ พื้นที่แห่งนี้มีลักษณะเป็นป่าร่มรื่น เหมาะสำหรับการพักผ่อนหย่อนใจของชุมชน และสามารถใช้เป็นแหล่งเรียนรู้ด้านสิ่งแวดล้อมให้แก่เด็กนักเรียนและประชาชนในพื้นที่ได้สวนป่าแห่งนี้ยังถูกใช้เป็นสถานที่จัดกิจกรรมเพื่อสาธารณประโยชน์ เช่น การปลูกต้นไม้ การฟื้นฟูระบบนิเวศ และกิจกรรมอนุรักษ์ธรรมชาติของหน่วยงานท้องถิ่นและชุมชน ทำให้พื้นที่ดังกล่าวเป็นทั้งแหล่งพักผ่อน พื้นที่สีเขียว และแหล่งเรียนรู้ที่ช่วยส่งเสริมความร่วมมือในการดูแลรักษาสิ่งแวดล้อมของคนในตำบลกู่กาสิงห์', NULL, NULL, '15.5691578', '103.6602803', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '135', '1', '42', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk105/2026-04-03_09-48-44_S__26050568.jpg\"]'),
('120', 'PK104', 'อนุสาวรีย์ สามปู่ ผู้ก่อตั้งบ้านกู่กาสิงห์', 'อนุสาวรีย์สามปู่ ผู้ก่อตั้งบ้านกู่กาสิงห์ ตั้งอยู่ที่ตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด สร้างขึ้นเพื่อเชิดชูเกียรติบรรพชนผู้บุกเบิกตั้งถิ่นฐานในบริเวณนี้เมื่อปี พ.ศ. 2446 โดยบุคคลทั้งสามประกอบด้วยพ่อใหญ่ตาแสงลือ ศรีกู่กาพ่อใหญ่จัน ศรีเที่ยงพ่อใหญ่เพียราชอุปวงษาอนุสาวรีย์แห่งนี้เป็นสัญลักษณ์ของความกตัญญูต่อบรรพบุรุษ และเป็นศูนย์รวมจิตใจของชุมชนบ้านกู่กาสิงห์แนวคิดในการสร้างอนุสาวรีย์เริ่มต้นขึ้นราวปี พ.ศ. 2540 เมื่อชาวบ้านต้องการอนุรักษ์เรื่องราวการก่อตั้งบ้านเรือน และสืบทอดเกียรติคุณบรรพชนทั้งสามผู้พาผู้คนมาตั้งถิ่นฐานใกล้แหล่งโบราณสถานสำคัญอย่าง “กู่กาสิงห์” ซึ่งเป็นโบราณสถานเก่าแก่ในพื้นที่ทุ่งกุลาร้องไห้ การก่อสร้างจึงเป็นการผสานทั้งประวัติศาสตร์ท้องถิ่น ความเชื่อ และความผูกพันของผู้คนในชุมชนอนุสาวรีย์สามปู่ยังเป็นสถานที่ประกอบพิธีกรรมสำคัญทางวัฒนธรรม เช่น พิธีสู่ขวัญบ้าน การบวงสรวงขอพร และกิจกรรมรำลึกถึงบรรพบุรุษในโอกาสต่าง ๆ สะท้อนความเคารพต่อรากเหง้าและภูมิปัญญาท้องถิ่นของชาวกู่กาสิงห์ที่สืบทอดต่อกันมายาวนานด้วยคุณค่าทั้งด้านประวัติศาสตร์และวัฒนธรรม อนุสาวรีย์แห่งนี้จึงถือเป็นมรดกที่สำคัญของชุมชน และเป็นสถานที่ที่ชาวบ้านใช้ยึดเหนี่ยวจิตใจและเสริมสร้างความสามัคคีภายในหมู่บ้านจนถึงปัจจุบัน', NULL, NULL, '15.5788056', '103.67', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '248', '6', '86', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk104/2026-04-03_09-05-46_S__30097417_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk104/2026-04-03_09-05-49_S__30097418_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk104/2026-04-03_09-05-52_S__30097419_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk104/2026-04-03_09-05-56_S__30097420_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk104/2026-04-03_09-05-59_S__30097421_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk104/2026-04-03_09-06-03_S__30097422_0.jpg\"]'),
('121', 'PK103', 'บือบ้านหรือหลักบ้านชุมชนกู่กาสิงห์', 'บือบ้าน หรือหลักบ้านชุมชนกู่กาสิงห์ ตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด เป็นเสาหลักกลางหมู่บ้านที่มีความสำคัญยิ่งต่อชุมชน เปรียบเสมือน “หลักเมือง” อันเป็นสัญลักษณ์แห่งการปกปักคุ้มครองและความมั่นคงของหมู่บ้าน ชาวบ้านเชื่อว่าเป็นที่สถิตของผู้มีอำนาจเหนือธรรมชาติหรือ “ผีดอนปู่ตา” ตามความเชื่อดั้งเดิมของกลุ่มคนลาวในภาคอีสาน ซึ่งถือว่าผีปู่ตาคือบรรพบุรุษผู้ล่วงลับที่คอยดูแลและคุ้มครองลูกหลานศาลปู่ตาจึงถูกสร้างขึ้นในพื้นที่สาธารณะ เพื่อให้เป็นศูนย์รวมจิตใจของคนในชุมชน เป็นสถานที่ประกอบพิธีกรรมและงานบุญสำคัญ โดยเฉพาะ “บุญบือบ้าน” หรือพิธีทำบุญหลักบ้าน ซึ่งจัดขึ้นเป็นประจำทุกปีในช่วงเดือนพฤษภาคม เพื่อความสิริมงคล ความเจริญรุ่งเรือง และความสงบสุขของชาวบ้านในหมู่บ้านกู่กาสิงห์บือบ้านจึงเป็นทั้งสัญลักษณ์ทางจิตวิญญาณและวัฒนธรรมที่สะท้อนความผูกพันของชุมชนต่อบรรพบุรุษและธรรมชาติ พร้อมทั้งเป็นมรดกท้องถิ่นที่สืบทอดจากรุ่นสู่รุ่นอย่างไม่เสื่อมคลาย', NULL, NULL, '15.5789157', '103.667735', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '190', '4', '65', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk103/2026-04-03_08-38-47_S__13156355_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk103/2026-04-03_08-38-51_S__13156356_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk103/2026-04-03_08-38-54_S__13156357_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk103/2026-04-03_08-38-58_S__13156358_0.jpg\"]'),
('122', 'PK102', 'ศูนย์ทอผ้าไหม หมู่ที่ 1', 'ศูนย์ทอผ้าไหม ตั้งอยู่ศูนย์ส่งเสริมการท่องเที่ยวเชิงเกษตร หมู่ที่ 1 บ้านกู่กาสิงห์ ตำบลกู่กาสิงห์ อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด (ตั้งอยู่ทางเข้าหมู่บ้าน)โดยกลุ่มแม่บ้านเกษตรกรหมู่ที่ 1 ก่อตั้งเมื่อวันที่ 14 มกราคม พ.ศ. 2538 โดยมีสมาชิกเริ่มต้นจำนวน 69 คน มีจุดมุ่งหมายในการก่อตั้งกลุ่มคือการอนุรักษ์และสืบทอดภูมิปัญญาการทอผ้าไหมพื้นบ้าน สร้างรายได้เสริมจากอาชีพทำนา และร่วมกันบริหารจัดการกลุ่มให้มีความเข้มแข็งและยั่งยืนกิจกรรมของกลุ่มทอผ้าไหมพื้นบ้านทั้งแบบย้อมสีธรรมชาติและสีเคมีจัดแสดงผ้าไหมลวดลายและรูปแบบต่าง ๆ ผลงานของสมาชิกจำหน่ายผลิตภัณฑ์ผ้าไหมในศูนย์จำหน่ายและตามงานเทศกาลเป็นแหล่งเรียนรู้ด้านภูมิปัญญาชาวบ้าน เช่น การทอผ้า การย้อมสีธรรมชาติ การมัดหมี่ และการค้นหูกกิจกรรมเหล่านี้ช่วยส่งเสริมศักยภาพการท่องเที่ยวโดยชุมชน สร้างปฏิสัมพันธ์ที่เป็นกันเองกับนักท่องเที่ยว และเปิดโอกาสให้เลือกซื้อ', NULL, NULL, '15.5821389', '103.6650556', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '178', '2', '56', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk102/2026-04-02_13-33-35_S__26042394.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk102/2026-04-02_13-33-38_S__26042396.jpg\"]'),
('123', 'PK101', 'ลำน้ำเสียว', 'ลำเสียวเป็นลำน้ำธรรมชาติสายสำคัญที่ไหลพาดผ่านใจกลางทุ่งกุลาร้องไห้ และมีความเกี่ยวข้องอย่างลึกซึ้งกับพื้นที่บ่อพันขัน ชื่อ \"ลำเสียว\" มาจากชื่อต้นไม้ชนิดหนึ่งที่ขึ้นหนาแน่นตามริมฝั่ง ลำน้ำสายนี้เป็นทั้งแหล่งอาหาร แหล่งทำประมงพื้นบ้าน และเส้นทางคมนาคมโบราณที่เชื่อมโยงชุมชนบ่อพันขันเข้ากับลุ่มแม่น้ำมูลและแม่น้ำชี ทำให้เกิดการแลกเปลี่ยนสินค้า เช่น เกลือและข้าวหอมมะลิในช่วงฤดูร้อนผิวดินรอบห้วยเค็มจะปรากฏคราบเกลือสีขาวหรือ \"ส่าเกลือ\" ซึ่งเป็นที่มาของภูมิปัญญาการต้มเกลือสินเธาว์ของชาวบ้านในสมัยก่อน ห้วยเค็มจึงไม่ได้เป็นเพียงลำน้ำ แต่เป็นสัญลักษณ์ของทรัพยากรเศรษฐกิจโบราณที่สร้างรายได้ให้แก่คนทุ่งกุลาร้องไห้มาหลายชั่วอายุคนลำเสียวเป็นส่วนหนึ่งของระบบอุทกภาค (Hydrosphere) ที่สำคัญในบ่อพันขัน การจัดการน้ำจากลำน้ำเหล่านี้ผ่านระบบฝายและบึงพันขันช่วยให้ชาวบ้านมีน้ำใช้ในเกษตรกรรมตลอดปี นอกจากนี้ ลำน้ำทั้งสองสายยังเป็นจุดที่นักท่องเที่ยวสามารถมาศึกษาสิ่งมีชีวิตในน้ำและการเปลี่ยนแปลงของภูมิประเทศที่เกิดจากการกัดเซาะและการสะสมของแร่ธาตุได้อย่างชัดเจน', NULL, NULL, '15.5836624', '103.6617508', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '208', '2', '65', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk101/2026-04-29_07-24-33_IMG_8847.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk101/2026-04-29_07-24-28_IMG_8608.jpg\"]'),
('124', 'bmp009', 'ผลิตภัณฑ์แปรรูปจากหมากเม่า บ้านป่าเม้า', 'แนวคิด (Concept)ผลิตภัณฑ์ชุดนี้เกิดจากการนำ“หมากเม่า” พืชพื้นถิ่นของชุมชนบ้านป่าเม้ามาต่อยอดจากวัตถุดิบธรรมชาติสู่ผลิตภัณฑ์อาหารและเครื่องดื่มร่วมสมัย โดยเชื่อมโยง เพื่อสร้าง “Soft Power อาหารอีสาน”ที่กินได้ เล่าเรื่องได้ และขายได้ภูมิปัญญาดั้งเดิม (การหมัก / การถนอมอาหาร)ความคิดสร้างสรรค์ของคนรุ่นใหม่จุดเด่น (Highlight)ใช้ “หมากเม่า” วัตถุดิบเอกลักษณ์ของชุมชนแปรรูปหลากหลาย ตอบโจทย์หลายกลุ่มลูกค้าผสมผสาน “สูตรพื้นบ้าน + ความร่วมสมัย”รสชาติเป็นเอกลักษณ์ (เปรี้ยวอมหวาน สีม่วงธรรมชาติ)สร้างมูลค่าเพิ่มจากผลไม้ท้องถิ่น', NULL, NULL, NULL, NULL, 'เมืองเปลือย', 'ศรีสมเด็จ ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:23:28', '119', '1', '37', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp009/2026-03-30_07-47-09_ผลิตภัณฑ์แปรรูป.jpg\"]'),
('125', 'bmp008', 'โคมไฟโฮแซว คอลเลคชั่นบุญผะเหวด', 'โคมไฟโฮแซว คอลเลคชั่นบุญผะเหวดแนวคิด (Concept)โคมไฟโฮแซวคอลเลคชั่นนี้ ได้รับแรงบันดาลใจจาก “บุญผะเหวด”ซึ่งเป็นบุญใหญ่ประจำปีของจังหวัดร้อยเอ็ด โดยนำองค์ประกอบทางวัฒนธรรมมาถ่ายทอดผ่านงานออกแบบ ผลิตภัณฑ์จึงไม่ใช่เพียงโคมไฟ แต่เป็น “เรื่องเล่าของวัฒนธรรม” ที่สามารถสัมผัสได้ ได้แก่ผ้าลายขาวม้า → สะท้อนภูมิปัญญาท้องถิ่นพู่พลิ้วไหว → แทนธงบุญในขบวนแห่สีสันสดใส → สื่อถึงความศรัทธาและความรื่นเริงของชุมชนจุดเด่น (Highlight)ถ่ายทอด “บุญผะเหวด” ผ่านงานออกแบบร่วมสมัยใช้ผ้าขาวม้า เป็นเอกลักษณ์อีสานพู่ตกแต่ง สื่อถึงขบวนแห่วัฒนธรรมงานทำมือ 100% ทุกชิ้นเป็นทั้งของตกแต่ง และสื่อวัฒนธรรม (Cultural Object)', NULL, NULL, NULL, NULL, 'เมืองเปลือย', 'ศรีสมเด็จ ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:25:53', '130', '7', '55', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp008/2026-03-30_07-09-00_LINE_ALBUM_โคมไฟโฮแซว_260330_1.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp008/2026-03-30_07-09-04_LINE_ALBUM_โคมไฟโฮแซว_260330_2.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp008/2026-03-30_07-09-07_LINE_ALBUM_โคมไฟโฮแซว_260330_3.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp008/2026-03-30_07-09-11_LINE_ALBUM_โคมไฟโฮแซว_260330_4.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp008/2026-03-30_07-09-15_LINE_ALBUM_โคมไฟโฮแซว_260330_5.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp008/2026-03-30_07-09-18_LINE_ALBUM_โคมไฟโฮแซว_260330_6.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp008/2026-03-30_07-57-46_โคมไฟโฮแซว_jpg.jpg\"]'),
('126', 'bmp007', 'โคมไฟโฮแซว คอลเลคชั่น 13 กัณฑ์', 'โคมไฟโฮแซว ลาย 13 กัณฑ์HO SAEW 13 LIGHTS – The Light of Thirteen Chapters1. ชื่อผลิตภัณฑ์โคมไฟโฮแซว ลาย 13 กัณฑ์HO SAEW 13 LIGHTS – The Light of Thirteen Chaptersแนวคิด (Concept)คอลเลคชั่นนี้ได้รับแรงบันดาลใจจาก “มหาเวสสันดรชาดก 13 กัณฑ์”ซึ่งเป็นหัวใจของงานบุญผะเหวดประเพณีสำคัญของชาวอีสานโดยถ่ายทอด “เรื่องราวแห่งการให้”การเสียสละ และบทเรียนชีวิตผ่านงานออกแบบร่วมสมัย ที่ผสานศิลปะ วัฒนธรรม และภูมิปัญญาชุมชน เปลี่ยน “ธรรมะ” ให้กลายเป็น “ดีไซน์ที่จับต้องได้”จุดเด่น (Highlight)ถ่ายทอด “13 กัณฑ์” ผ่านลวดลายโคมไฟเชื่อมโยงพุทธศาสนา + ศิลปะร่วมสมัยใช้ผ้าขาวม้าและสีอัตลักษณ์บ้านป่าเม้างานทำมือ 100% ทุกชิ้นเป็นทั้งของตกแต่งและ “สื่อทางวัฒนธรรม” แนวคิดการออกแบบ (Design Concept)13 ลวดลาย → แทน 13 กัณฑ์ผ้าขาวม้า → อัตลักษณ์อีสานสีม่วง–ชมพู → ตัวแทนบ้านป่าเม้าพู่และองค์ประกอบพลิ้วไหว → สื่อถึงขบวนบุญผะเหวด ทุกลายคือ “เรื่องเล่าของศรัทธา”', NULL, NULL, NULL, NULL, 'เมืองเปลือย', 'ศรีสมเด็จ ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:27:33', '186', '7', '71', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp007/2026-03-30_07-04-53_LINE_ALBUM_โคม13กัณฑ์_260330_1.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp007/2026-03-30_07-04-57_LINE_ALBUM_โคม13กัณฑ์_260330_2.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp007/2026-03-30_07-05-01_LINE_ALBUM_โคม13กัณฑ์_260330_3.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp007/2026-03-30_07-05-04_LINE_ALBUM_โคม13กัณฑ์_260330_4.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp007/2026-03-30_07-05-08_LINE_ALBUM_โคม13กัณฑ์_260330_5.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp007/2026-03-30_07-05-12_LINE_ALBUM_โคม13กัณฑ์_260330_6.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp007/2026-03-30_07-05-16_LINE_ALBUM_โคม13กัณฑ์_260330_7.jpg\"]'),
('127', 'bmp004', 'งานศิลปะสาธารณะ (Street Art) Community Street Art', 'งานศิลปะสาธารณะ (Street Art) Community Street Artวาดภาพผนัง (Street Art)เพ้นท์ลายอัตลักษณ์ชุมชนสร้างแลนด์มาร์กทางวัฒนธรรม เปลี่ยน “กำแพง” ให้เป็น “เรื่องเล่าของชุมชน”', NULL, NULL, NULL, NULL, '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '36', '5', '23', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp004/2026-03-30_07-52-25_LINE_ALBUM_2026_3_29_260330_24.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp004/2026-03-30_07-52-29_LINE_ALBUM_2026_3_29_260330_27.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp004/2026-03-30_07-52-32_LINE_ALBUM_2026_3_29_260330_28.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp004/2026-03-30_07-52-36_LINE_ALBUM_2026_3_29_260330_29.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bmp004/2026-03-30_07-53-08_กิจกรรมงานcraft.jpg\"]'),
('128', 'bpm002', 'ผลิตภัณฑ์ชุมชนบ้านป่าเม้า', 'ผลิตภัณฑ์ชุมชนบ้านป่าเม้าผลิตภัณฑ์บ้านป่าเม้า ไม่ใช่แค่สินค้าแต่คือ “เรื่องเล่าของชุมชน”ที่ถูกถ่ายทอดผ่านมือของคนในพื้นที่สู่โลกแห่งความร่วมสมัยกลุ่มหัตถกรรมและงานสร้างสรรค์ Craft & Creative Productsโคมไฟโฮแซวโคมไฟ 13 กัณฑ์จักรสานไม้ไผ่ (ไซ / เครื่องใช้พื้นบ้าน)จักรสานหวายเทียมจุดเด่น: งานฝีมือ + ดีไซน์ร่วมสมัย + Soft Powerกลุ่มสิ่งทอและแฟชั่น Textile & Fashionผ้าสะไบทอมือผ้าย้อมสีธรรมชาติเสื้อผ้าแบรนด์ “E-san Minimal” (Thaniqe by Palitrak)จุดเด่น: สีธรรมชาติ + อัตลักษณ์อีสาน + ดีไซน์ร่วมสมัยกลุ่มผลิตภัณฑ์สุขภาพ Health & Wellness Productsหมอนมะละกอยาดมสมุนไพร และหมากเม่าผลิตภัณฑ์สมุนไพรจุดเด่น: ใช้งานจริง + ตอบโจทย์สุขภาพ กลุ่มอาหารและแปรรูป Food & Processed Productsน้ำหมักหมากเม่าสาโทหมากเม่าแยมหมากเม่าเค้กหมากเม่า (เค้กพบรัก)หมากเม่านมสดข้าวโป่งแครกเกอร์แยมหมากเม่าจุดเด่น: Local food + Creative food + Soft Power กลุ่มของใช้และของตกแต่ง Lifestyle & Decorative Productsเบาะรองนั่งของตกแต่งบ้านจากผ้าทอโคมไฟตกแต่งจุดเด่น: ใช้ได้จริง + ดีไซน์พื้นถิ่นกลุ่มของที่ระลึกและสร้างสรรค์ Souvenir & Creative Goodsตุ๊กตาน้องขอของที่ระลึกมาสคอตไพ่ “น้องขอ”จุดเด่น: เชื่อมคนรุ่นใหม่กับวัฒนธรรม', NULL, NULL, NULL, NULL, 'เมืองเปลือย', 'ศรีสมเด็จ ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:29:52', '238', '3', '76', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bpm002/2026-03-30_07-36-16_LINE_ALBUM_2026_3_29_260330_62.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bpm002/2026-03-30_07-39-24_LINE_ALBUM_2026_3_29_260330_11.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bpm002/2026-03-30_07-39-27_LINE_ALBUM_2026_3_29_260330_7.jpg\"]'),
('129', 'bpm001', 'ศูนย์วัฒนธรรมบ้านป่าเม้า', 'ศูนย์วัฒนธรรมบ้านป่าเม้าเกิดจากแนวคิด “เก็บราก สร้างร่องรอย”เป็นพื้นที่กลางของชุมชนที่รวบรวมภูมิปัญญาท้องถิ่นวัฒนธรรม วิถีชีวิตและความคิดสร้างสรรค์ของคนในชุมชนโดยมุ่งพัฒนาให้เป็น“ศูนย์การเรียนรู้วัฒนธรรมร่วมสมัย” ที่เชื่อมโยงอดีต ปัจจุบัน และอนาคตเข้าด้วยกัน', NULL, NULL, NULL, NULL, 'เมืองเปลือย', 'ศรีสมเด็จ ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:30:09', '60', '2', '23', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bpm001/2026-03-30_07-27-46_LINE_ALBUM_2026_3_29_260330_65.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/bpm001/2026-03-30_07-48-39_ศูนยบ้านป่าเม้า.jpg\"]'),
('130', 'PK096', 'กิจกรรมศึกษาระบบนิเวศ', 'เส้นทางท่องเที่ยวเชิงนิเวศนี้จะพาไปสัมผัสความงดงามของธรรมชาติที่บ่อพันขัน ด้วยมุมมองของความยั่งยืนและการอยู่ร่วมกันกับสิ่งแวดล้อม ผ่านบึงน้ำธรรมชาติที่ยังคงความสมบูรณ์ของระบบนิเวศ ทั้งพืชน้ำ ปลา และนกท้องถิ่น เส้นทางนี้เชื่อมโยงความรู้เรื่องสิ่งแวดล้อมกับวิถีชีวิตชาวบ้านที่พึ่งพาธรรมชาติอย่างพอเพียง ไม่เพียงแค่ชมความงามของธรรมชาติ แต่ยังได้เรียนรู้การใช้ทรัพยากรอย่างรู้คุณค่า ปลูกจิตสำนึก “รักษ์โลก” ผ่านทุกย่างก้าวของการเดินทาง', NULL, NULL, '15.574362202973', '103.94120337189', 'จำปาขัน', 'สุวรรณภูมิ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '95', '48', '148', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-43-41__1RL7838.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-43-47__1RL7841.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-43-53__1RL7852.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-43-59__1RL7856.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-04__1RL7857.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-09__1RL7859.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-15__1RL7860.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-21__1RL7862.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-26__1RL7864.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-32__1RL7872.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-38__1RL7874.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-44__1RL7877.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-01-23_09-44-50__1RL7878.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/pk096/2026-