('207', 'KP67-C-023', 'นางทองสุก คุ้มศรีไว', 'นางทองสุก คุ้มศรีไวที่อยู่ : บ้านเลขที่ 64 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : หัตกรรมพื้นบ้าน (การทอผ้า)', NULL, NULL, '16.3638359', '103.8241713', 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:35:14', '32', '1', '12', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c023/2024-03-25_10-17-44_นางทองสุก คุ้มศรีไว.jpg\"]'),
('208', 'KP67-C-022', 'นางบุญชู มะอาจเลิศ', 'นางบุญชู มะอาจเลิศที่อยู่ : บ้านเลขที่ 111 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอลำ', NULL, NULL, '16.3638359', '103.8241713', 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:35:24', '29', '1', '11', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c022/2024-03-25_10-16-15_นางบุญชู  มะอาจเลิศ.jpg\"]'),
('209', 'KP67-C-021', 'นางอนงค์ พินิจพนธ์', 'นางอนงค์ พินิจพนธ์ที่อยู่ : บ้านเลขที่ 99 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอลำ', NULL, NULL, '16.3638359', '103.8241713', 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:35:32', '29', '1', '11', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c021/2024-03-25_10-15-04_นางอนงค์  พินิจพนธ์.jpg\"]'),
('210', 'KP67-C-020', 'นายบุญมา สุ่มมาตย์', 'ที่อยู่ : บ้านเลขที่ 92 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน เล่นเครื่องดนตรีกั๊บแก๊บ', NULL, NULL, '16.3638359', '103.8241713', 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:35:38', '30', '1', '12', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c020/2024-03-25_10-13-52_นายบุญมา สุ่มมาตย์.jpg\"]'),
('211', 'KP67-C-019', 'นายดำรง มะอาจเลิศ', 'นายดำรง มะอาจเลิศที่อยู่ : บ้านเลขที่ 81 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน แต่งกลอนพื้นบ้าน เช่น กลอนลำล่องภูกุ้มข้าว', NULL, NULL, '16.3638359', '103.8241713', 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:35:44', '37', '1', '14', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c019/2024-03-25_10-12-13_นายดำรง มะอาจเลิศ.jpg\"]'),
('212', 'KP67-C-018', 'นายหนู โพธิ์ศรีแก้ว', 'นายหนู โพธิ์ศรีแก้วที่อยู่ : บ้านเลขที่ 110 หมู่8 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอแคน', NULL, NULL, '16.3638359', '103.8241713', 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:35:50', '30', '1', '12', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c018/2024-03-25_10-11-03_นายหนู โพธิ์ศรีแก้ว.jpg\"]'),
('213', 'KP67-C-017', 'พิธีบวงสรวงองค์ปู่วิรูปักโขนาคราช', '', NULL, NULL, NULL, NULL, 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:36:20', '0', '12', '30', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-13_175629_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-23_175632_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-26_175633_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-29_175634_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-33_175635_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-39_175637_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-43_175638_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-46_175639_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-49_175640_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-58-55_175642_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-59-02_175644_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c017/2024-03-25_09-59-05_175633_0 - สำเนา.jpg\"]'),
('214', 'KP67-C-016', 'กระบวย', 'ชื่อชิ้นงาน : กระบวยชื่ออื่นๆ : -ขนาดวัตถุ : กว้าง 6.3-11.4 เซนติเมตร ยาว 26.6-42 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายบุญมี มะอาจเลิศคำอธิบาย : เป็นภาชนะใช้ตักน้ำดื่มน้ำใช้ในครัวเรือนมักจะวางไว้ภายในซุ้มโอ่งน้ำหรือโอ่งน้ำเย็น', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '51', '1', '18', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c016/2024-03-25_09-38-28_k10.jpg\"]'),
('215', 'KP67-C-015', 'ไซ', 'ชื่อชิ้นงาน : ไซชื่ออื่นๆ : -ขนาดวัตถุ : กว้าง - เซนติเมตรยาว 142.2 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายสมจิตร แดนขนบคำอธิบาย : เป็นเครื่องดักสัตว์น้ำ ใช้ดักตามช่องทางระบายน้ำขนาดเล็กส่วนมากใช้ดักระหว่างแปลงนาโดยขุดทางระบายน้ำที่คันนาในช่วงต้นฤดูการทำนาที่น้ำเริ่มไหลหลาก', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '64', '1', '21', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c015/2024-03-25_09-37-11_k9.jpg\"]'),
('216', 'KP67-C-014', 'ตะเกียงรั้ว', 'ชื่อชิ้นงาน : ตะเกียงรั้วชื่ออื่นๆ : ตะเกียงโป๊ะขนาดวัตถุ : กว้าง 17.7 เซนติเมตร ยาว 142 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายสมจิตร แดนขนบคำอธิบาย : ตัวตะเกียงทำด้วยสังกะสีและแก้ว มีหูหิ้วและครอบแก้วกันลม ไส้ตะเกียงทำด้วยด้ายหรือผ้า ใช้สำหรับให้แสงสว่าง โดยการใช้น้ำมันก๊าดเป็นเชื้อเพลิง', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '65', '1', '22', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c014/2024-03-25_09-35-41_k8.jpg\"]'),
('217', 'KP67-C-013', 'ไม้คาน', 'ชื่อชิ้นงาน : ไม้คานชื่ออื่นๆ : -ขนาดวัตถุ : กว้าง - เซนติเมตร ยาว 135.8 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายบุญมี มะอาจเลิศคำอธิบาย : เป็นเครื่องมือทำจากไม้สำหรับหาบหรือหามสิ่งของต่างๆ เช่น กระจาดหาบ กระบุง เป็นต้น', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '50', '1', '17', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c013/2024-03-25_09-34-11_k7.jpg\"]'),
('218', 'KP67-C-012', 'สะนูว่าว', 'ชื่อชิ้นงาน : สะนูว่าวชื่ออื่นๆ : ธนูว่าว, ทะนูว่าว, อูด, หมากตื้อ, แอกขนาดวัตถุ : กว้าง 127 เซนติเมตร ยาว 66 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายบุญมี มะอาจเลิศคำอธิบาย : ใช้ติดอยู่บนหัวของว่าว ทำให้ว่าวมีความสมดุลและยังสามารถทำให้เกิดเสียงดนตรีบรรเลงได้จะเรียกว่า \"ว่าวสะนู\"', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '68', '1', '22', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c012/2024-03-25_09-32-11_k6.jpg\"]'),
('219', 'KP67-C-011', 'หมากกอลอ', 'ชื่อชิ้นงาน : หมากกอลอชื่ออื่นๆ : เกราะขนาดวัตถุ : กว้าง 19 เซนติเมตร ยาว 19 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายบุญมี มะอาจเลิศคำอธิบาย : ทำจากไม้ประดู่ ใช้เป็นเครื่องตีที่บอกสัญญาณ แขวนไว้ตามบ้านเจ้าบ้านเจ้าเมืองสำหรับตีประชุมลูกบ้านลูกเมือง เมื่อเวลามีกิจการบ้านเมือง เรียกรวมคนในบ้านมาทำกิจกรรมหรือเคาะเมื่อมีเหตุด่วน', NULL, NULL, '16.3638359', '103.8241713', 'กู่กาสิงห์', 'เกษตรวิสัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:37:50', '74', '1', '24', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c011/2024-03-25_09-29-06_k5.jpg\"]'),
('220', 'KP67-C-010', 'อุดเตา', 'ชื่อชิ้นงาน : อุดเตาชื่ออื่นๆ : เตารีดถ่านขนาดวัตถุ : กว้าง 10 เซนติเมตร ยาว 22.8 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายบุญมี มะอาจเลิศคำอธิบาย : ทำด้วยเหล็กเป็นอุปกรณ์สำหรับทำเสื้อผ้าให้เรียบเพื่อความสวยงาม', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '48', '1', '17', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c010/2024-03-25_09-26-04_k4.jpg\"]'),
('221', 'KP67-C-009', 'เลื่อยมือ', 'ชื่อชิ้นงาน : เลื่อยมือชื่ออื่นๆ : -ขนาดวัตถุ : กว้าง 48.2 ยาว 172.7 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายบุญมี มะอาจเลิศคำอธิบาย : ด้ามจับทำจากไม้ประดู่ มีท่อนไม้ไผ่เพื่อยึดระหว่างตัวเลื่อย โดยตัวตัวเลื่อยจะยึดกันโดยใช้เหล็กยึดและมีใบเลื่อยสำหรับเลื่อยไม้ ในการนำไม้ไปใช้ประโยชน์ต่างๆ', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '65', '1', '22', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c009/2024-03-25_09-24-22_k3.jpg\"]'),
('222', 'KP67-C-008', 'เขียงกะบอง', 'ชื่ออื่นๆ : โฮงกะบอง, ไต้กะบองขนาดวัตถุ : กว้าง 22.8 ยาว 48.2 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายอาวุธ โหลทองคำอธิบาย : มีฐานเป็นไม้หนาขุดร่องรองรับขี้กะบองที่ทำด้วยไม้ผุคลุกเคล้ากับน้ำมันยางใช้สำหรับจุดไฟให้แสงสว่าง ขาทำเป็นง่ามไว้รองรับตัวกะบอง ในอดีตยังไม่มีไฟฟ้า ชาวบ้านจึงทำกะบองไว้จุดไฟให้แสงสว่างยามค่ำคืน', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '72', '1', '24', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c008/2024-03-25_09-22-36_k2.jpg\"]'),
('223', 'KP67-C-007', 'ปืนเพลิง', 'ชื่ออื่นๆ : ปืนแก๊ปขนาดวัตถุ : กว้าง 25 เซนติเมตร ยาว 115.5 เซนติเมตรชื่อ-สกุล เจ้าของชิ้นงาน : นายสมาท งามผิวเหลืองคำอธิบาย : เป็นเครื่องมือล่าสัตว์ที่มีความอันตรายมากกว่าเครื่องมือชนิดอื่น ๆ มีอานุภาพใช้ล่าสัตว์เล็กถึงสัตว์ขนาดใหญ่เป็นอาวุธป้องกันปราบปรามโจรผู้ร้ายในสมัยก่อนใช้ในศึกสงคราม', NULL, NULL, '16.3638359', '103.8241713', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '66', '1', '22', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c007/2024-03-25_09-20-09_k1.jpg\"]'),
('224', 'YK67-C-001', 'ปราสาทคันธนาม', 'ปราสาทคันธนาม (กู่บ้านด่าน) เป็นปราสาทที่สร้างในพุทธศตวรรษที่ 18 เพื่อเป็นอโรคยาศาลตามแบบวัฒนธรรมเขมรแห่งหนึ่งใน 102 แห่งในสมัยพระเจ้าชัยวรมันที่ 7 (พ.ศ.1724 - 1761) ตามจารึกปราสาทตาพรหม ประเทศกัมพูชา ชื่อกู่คันธนามเป็นชื่อที่เรียกขึ้นในภายหลังตามนิทานชาดกนอกนิบาตเรื่องคันธนโพธิสัตว์ชาดกที่นิยมเล่ากันในกลุ่มชนเชื้อสายลาวโดยผูกเรื่องพุทธประวัติเข้ากับสถานที่ในท้องถิ่นให้บริเวณกู่คันธนามและโดยรอบเป็นพื้นที่ซึ่งพระพุทธเจ้าเสด็จมาโปรดเวไนยสัตว์ บริเวณกู่คันธนามประกอบด้วยอาคาร 2 หลัง ในกำแพง ได้แก่ ปราสาทประธาน 1 หลังตอนกลาง และอาคารบรรณาลัยอีก 1 หลังทางทิศตะวันออกเฉียงใต้ของปราสาท ด้านนอกกำแพงด้านทิศตะวันออกเฉียงเหนือเป็นสระน้ำที่มีผังเช่นเดียวกับผังกู่โพนระฆังลักษณะสถาปัตยกรรมกู่คันธนาม เป็นปราสาทแบบเขมรที่ใช้ศิลาแลงเป็นวัสดุหลักในการก่อสร้าง ตั้งบนฐานสูงในผังสี่เหลี่ยมย่อเก็จ สร้างหันหน้าไปทางทิศตะวันออก ด้านหน้าปราสาทก่อมุขยื่นออกมาเชื่อมกับลานหิน ส่วนบรรณาลัยเป็นอาคารก่อด้วยศิลาแลงในผังสี่เหลี่ยมผืนผ้า ด้านหน้าบรรณาลัยพบศิลาจารึกหินทราย จารึกอักษรเขมรโบราณภาษาสันสกฤต มีเนื้อหาเกี่ยวกับการสร้างอโรคยาศาลให้เป็นสถานพยาบาลสำหรับประชาชน (ปัจจุบันเก็บรักษาไว้ที่พิพิธภัณฑ์แห่งชาติร้อยเอ็ด) การแต่งตั้งผู้ทำหน้าที่ในอโรคยาศาล และการพระราชทานสิ่งของตามขนาดของโรงพยาบาลของพระเจ้าชัยวรมันที่ 7 ส่วนกำแพงก่อด้วยศิลาแลงมีผังรูปสี่เหลี่ยมผืนผ้า กึ่งกลางกำแพงด้านทิศตะวันออกเป็นซุ้มประตู (โคปุระ) รูปกากบาท ก่อด้วยศิลาแลง แต่ส่วนที่เป็นคานใช้หินทรายสีชมพู ภายในประดิษฐานพระโพธิสัตว์อวโลกิเตศวร 4 กร ทำจากหินทรายในลักษณะศิลปะเขมรแบบบายน นอกจากนี้ภายในปราสาทยังพบพระไภสัชยคุรุไวฑูรยประภาและพระวัชรธร กึ่งกลางกำแพงด้านทิศเหนือและใต้มีห้องเล็กๆ ที่สามารถเปิดสู่ภายในได้ ส่วนสระน้ำนอกกำแพงกรุด้วยศิลาแลงในผังรูปสี่เหลี่ยมผืนผ้า', NULL, NULL, '15.4592737', '103.9809492', 'ยางคำ', 'โพนทราย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:42:17', '362', '10', '129', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-24_YK67-C-001.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-27_YK67-C-001-1.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-30_YK67-C-001-2.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-33_YK67-C-001-3.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-36_YK67-C-001-4.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-40_YK67-C-001-5.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-43_YK67-C-001-6.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-46_YK67-C-001-7.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-49_YK67-C-001-8.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/yk67c001/2024-05-30_15-02-53_YK67-C-001-9.jpg\"]'),
('225', 'KP67-C-006', 'พระพุทธรูปเมตตามหานิยม', '', NULL, NULL, '16.4266875', '103.8469876', 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:43:06', '0', '1', '3', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c006/2024-03-22_14-19-51_ความเชื่อคติชน23 [Autosaved]_page-0008.jpg\"]'),
('226', 'KP67-C-005', 'พระธาตุภูมิกุ้มข้าว', '', NULL, NULL, '16.4266875', '103.8469876', 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:43:24', '0', '1', '3', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c005/2024-03-22_14-18-21_ความเชื่อคติชน23 [Autosaved]_page-0007.jpg\"]'),
('227', 'KP67-C-004', 'พระไม้', '', NULL, NULL, '16.4266875', '103.8469876', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '0', '1', '3', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c004/2024-03-22_13-53-44_ความเชื่อคติชน23 [Autosaved]_page-0006.jpg\"]'),
('228', 'KP67-C-003', 'ประเพณีบุญบั้งไฟตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ด', 'ประชากรในพื้นที่ส่วนมากประกอบอาชีพทำนา ทำไร่ เป็นหลัก ห้วงก่อนการทำนา ทำไร่ เดือนพฤษภาคมเป็นต้นไป จะทำพิธีกรรมบูชาพญาแถน ตามความเชื่อมาตั้งแต่บรรพบุรุษว่าพญาแถนเป็นผู้ทำให้ฝนตกต้องตามฤดูกาล จึงได้มีการจัดประเพณีบุญบั้งไฟเพื่อบูชาพญาแถน เพื่อเกิดศิริมงคลและกำลังใจแก่ชาวนา ชาวไร่', '08:00:00', '18:00:00', NULL, NULL, 'คำพอุง', 'โพธิ์ชัย ', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:45:46', '60', '24', '78', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-13_173670_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-16_173671_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-09_173669_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-06_173668_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-19_173672_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-22_173673_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-25_173674_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-32_173676_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-35_173677_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-38_173678_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-41_173679_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-44_173680_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-47_173681_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-51_173682_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-54_173683_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-26-57_173684_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-27-00_173685_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-27-03_173686_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-27-07_173687_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-27-10_173688_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-27-13_173689_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-27-16_173690_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-27-19_173691_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c003/2024-03-22_11-27-23_173692_0.jpg\"]'),
('229', 'KP67-C-002', 'ประเพณีบุญข้าวจี่ของดีเมืองโพธิ์ชัย', 'ประเพณีบุญข้าวจี่ เป็นประเพณีที่ปฏิบัติสืบทอดกันมาช้านานของคนอีสานจากอดีตจนถึงปัจจุบัน ซึ่งมีความสัมพันธ์กับพระพุทธศาสนา โดยเฉพาะคำสอนและข้อปฏิบัติที่บรรพบุรุษได้สืบทอดกันมา สะท้อนให้เห็นถึงคุณค่าวิถีชีวิตคนในชุมชนประเพณีบุญข้าวจี่ มีเรื่องเล่าในสมัยพุทธกาลว่า มีหญิงคนหนึ่งชื่อ นางปุณณทาสี เป็นคนยากจนต้องไปเป็นทาสีรับใช้เศรษฐีในกรุงราชคฤห์ วันหนึ่งเศรษฐีให้นางปุณณทาสีไปซ้อมข้าว นางซ้อมตลอดทั้งวันก็ไม่หมด ตกเย็นนางก็จุดไฟซ้อมต่อไป ได้รับความเหน็ดเหนื่อยเป็นอันมาก พอถึงตอนเช้านางก็เอารำทำเป็นแป้งจี่เผาไฟให้สุกแล้วใส่ไว้ในผ้าของตน แล้วเดินไปตักน้ำปราถนาจะบริโภคด้วยตนเอง ครั้นถึงกลางทางได้พบพระสัมมาสัมพุทธเจ้าและพระอานนท์เถระ เกิดความเลื่อมใส คิดว่าเราเป็นคนยากจนในชาตินี้ ก็เพราะมิได้ทำบุญตั้งแต่ชาติปางก่อนและชาตินี้เราก็ยังไม่เคยทำบุญเลย เมื่อคิดเช่นนั้นนางก็น้อมเอาข้าวแจ้งจี่นั้นเข้าไปถวายแด่พระศาสดา พระองค์ทรงรับแล้ว และนางก็คิดอีกว่าพระศาสดาคงไม่เสวย และอาจเอาทิ้งให้สุนัขหรือกากิน เพราะอาหารที่นางถวายไม่ประณีตน่ารับประทาน เมื่อพระศาสดาทรงทราบวาระจิตของนางเช่นนั้น พระองค์จึงรีบสั่งให้พระอานนท์ ปูลาดอาสนะแล้วทรงประทับนั่งฉัน ณ ที่นางถวายนั้น ครั้นเสวยเสร็จแล้วก็ตรัสอนุโมถนากถาโปรดนางจนสำเร็จโสดาปัตติผล เป็นอริยบุคคลในพระพุทธศาสนา ครั้นนางทำกาลกิริยาแล้วก็ได้ไปเกิดบนดาวดึงส์สวรรค์เสวยทิพย์สมบัติอยู่ในวิมานทองอันผุดผ่องโสภา มีนางฟ้าแวดล้อมเป็นยศบริวาร ด้วยเหตุนี้ ชาวนาในภาคอีสาน เมื่อเสร็จสิ้นฤดูเก็บเกี่ยวและเอาข้าวขึ้นเล้า (ยุ้งฉาง) เสร็จแล้วนิยมพากันทำข้าวจี่ เพราะถือว่าการถวายข้าวจี่มีอานิสงฆ์มาก ด้วยความเชื่อเช่นนี้ คนอีสานโบราณจึงได้ทำบุญประเพณีบุญข้าวจี่ สืบต่อกันมาจนถึงปัจจุบัน', NULL, NULL, NULL, NULL, 'ขามเปี้ย', 'โพธิ์ชัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:47:15', '327', '20', '144', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-55-34_172960_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-55-37_172961_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-55-40_172962_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-55-43_172963_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-55-50_173698_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-55-53_173699_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-55-56_173700_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-55-59_173701_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-02_173702_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-09_173704_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-15_173706_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-19_173707_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-22_173708_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-25_173709_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-28_173710_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-32_173711_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-35_173712_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-38_173713_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-41_173714_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c002/2024-03-22_10-56-45_173715_0.jpg\"]'),
('230', 'KP67-C-001', 'ประเพณีลอยกระทงตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ด', 'ประเพณีลอยกระทง เป็นประเพณีโบราณของไทยมีมาแต่โบราณกาล ซึ่งตรงกับวันขึ้น15 ค่ำ เดือน 12 (ตามปฏิทินจันทรคติ) จัดขึ้นเพื่อเป็นการรำลึกถึงความสำคัญของแม่น้ำที่มีประโยชน์ต่อชีวิตมนุษย์ และเป็นการขอขมาต่อพระแม่คงคา เป็นพิธีเก่าแก่ของไทยที่สืบทอดกันมาแต่สมัยโบราณ', '08:00:00', '18:00:00', NULL, NULL, 'คำพอุง', 'โพธิ์ชัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:47:37', '58', '15', '55', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-40-43_160675_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-40-59_160677_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-41-07_160678_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-41-12_160679_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-41-17_160680_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-41-22_160681_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-41-36_160683_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-41-46_160685_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-41-54_160686_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-42-01_160687_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-42-07_160688_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-42-14_160689_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-42-24_160690_0 - Copy.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-42-32_160691_0.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp67c001/2024-03-21_14-42-38_160692_0.jpg\"]'),
('231', 'KP0013', 'หอยเม็ดมะม่วงดึกดำบรรพ์ใหญ่', 'หอยเห็ดมะม่วงดึกดำบรรพ์ Yunnannocha sp. cf Y. khoratensis เปลือกรูปยาวเรียว มีความยาวเปลือกกว่าความสูงของเปลือกมากกว่า 1 เท่า ผิวเปลือกด้านนอกไม่มีลวดลาย ยกเว้นเส้นการเจริญเติบโต', NULL, NULL, '16.4588515', '103.8694619', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '37', '2', '16', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0013/2021-10-12_23-41-11_IMG20211007130105.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0013/2021-10-12_23-41-45_IMG20211007130112.jpg\"]'),
('232', 'KP0012', 'หอยสบนกดึกดำบรรพ์เล็ก', 'แหล่งซากดึกดำบรรพ์หอยสองฝาน้ำจืดของหมวดหินเส่าขัว อายุ 125-130 ล้านปี มีรายงานการค้นพบแหล่งซากดึกดำบรรพ์กหอยสองฝาน้ำจืดจากหมวดหินเสาขัวหลายแหล่ง ซึ่งมี 2 แหล่งที่มีการคันพบปริมาณมากและหลากหลายชนิด ได้แก่ 1. แหล่งข้านห้วยเดื่อ อำเภอเมือง จังหวัดหนองบัวลำภู 2. แหล่งภูเวียง อำเภอเมืองเก่า จังหวัดขอนแก่น ซึ่งแหล่งภูกุ้มข้าว บ้านภูเขาทอง ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ด คือ เป็นแหล่งใหญ่ 3 ที่พบซากดึกดำบรรพ์หอยสองฝาน้ำจืดจำนวนมากมีความหลากหลายชนิดสูงที่สุดและสภาพตัวอย่างสมบูรณ์ที่สุด', NULL, NULL, '16.4588515', '103.8694619', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '106', '3', '38', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0012/2021-10-12_23-36-08_IMG20211007125507.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0012/2021-10-12_23-36-38_IMG20211007125518.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0012/2021-10-12_23-37-10_IMG20211007125623.jpg\"]'),
('233', 'KP0011', 'หอยเล็บม้าดึกดำบรรพ์อาจารย์เรือน', 'ภูกุ้มข้าวเป็นแหล่งขุดค้นที่ค้นพบซากดึกดำบรรพ์หอยสองฝาน้ำจืดของหมวดหินเส่าขัว อายุ 125-130 ล้านปี มีรายงานการค้นพบแหล่งซากดึกดำบรรพ์กหอยสองฝาน้ำจืดจากหมวดหินเสาขัวหลายแหล่ง ซึ่งมี 2 แหล่งที่มีการคันพบปริมาณมากและหลากหลายชนิด ได้แก่ 1. แหล่งข้านห้วยเดื่อ อำเภอเมือง จังหวัดหนองบัวลำภู 2. แหล่งภูเวียง อำเภอเมืองเก่า จังหวัดขอนแก่น ซึ่งแหล่งภูกุ้มข้าว บ้านภูเขาทอง ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ด คือ เป็นแหล่งใหญ่ 3 ที่พบซากดึกดำบรรพ์หอยสองฝาน้ำจืดจำนวนมากมีความหลากหลายชนิดสูงที่สุดและสภาพตัวอย่างสมบูรณ์ที่สุด', NULL, NULL, '16.4266865', '103.847385', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '112', '4', '42', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0011/2021-10-12_23-30-16_IMG20211007125914.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0011/2021-10-12_23-30-43_IMG20211007125922.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0011/2021-10-12_23-31-19_IMG20211007125934.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0011/2021-10-12_23-31-51_IMG20211007125946.jpg\"]'),
('234', 'KP0010', 'หอยสบนกดึกดำบรรพ์ใหญ่', 'แหล่งซากดึกดำบรรพ์หอยสองฝาน้ำจืดของหมวดหินเส่าขัว อายุ 125-130 ล้านปี มีรายงานการค้นพบแหล่งซากดึกดำบรรพ์กหอยสองฝาน้ำจืดจากหมวดหินเสาขัวหลายแหล่ง ซึ่งมี 2 แหล่งที่มีการคันพบปริมาณมากและหลากหลายชนิด ได้แก่ 1. แหล่งข้านห้วยเดื่อ อำเภอเมือง จังหวัดหนองบัวลำภู 2. แหล่งภูเวียง อำเภอเมืองเก่า จังหวัดขอนแก่น ซึ่งแหล่งภูกุ้มข้าว บ้านภูเขาทอง ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ด คือ เป็นแหล่งใหญ่ 3 ที่พบซากดึกดำบรรพ์หอยสองฝาน้ำจืดจำนวนมากมีความหลากหลายชนิดสูงที่สุดและสภาพตัวอย่างสมบูรณ์ที่สุด', NULL, NULL, '16.4588515', '103.8694619', '', '', '', '2026-06-29 14:52:19', '2026-08-20 10:26:54', '106', '3', '38', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0010/2021-10-12_23-22-14_IMG20211007125717.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0010/2021-10-12_23-22-47_IMG20211007125728.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp0010/2021-10-12_23-23-18_IMG20211007125735.jpg\"]'),
