('242', 'KP30001', 'พิพิธภัณฑ์ประวัติศาสตร์ท้องถิ่น ดงแม่เผด', '', '11:00:00', '16:00:00', NULL, NULL, 'คำพอุง', 'โพธิ์ชัย', 'ร้อยเอ็ด', '2026-06-29 14:52:19', '2026-09-07 12:51:05', '0', '6', '15', '[\"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp30001/2021-09-10_14-41-47_2988.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp30001/2022-02-18_13-07-37_272709194_247063534167571_485315661255776972_n.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp30001/2022-02-18_13-07-41_273555759_276441967937246_6894838203639553210_n.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp30001/2022-02-18_13-07-44_272769097_505330790938334_770367997730993253_n.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp30001/2022-02-18_13-07-47_273777204_331584612230943_8375017443479908058_n.jpg\", \"https://www.navanurak.in.th/SDGstravelroiet/pic/bigmuse/kp30001/2022-02-18_13-07-51_272646827_302032631818779_1064510910352310030_n.jpg\"]'),
