INSERT INTO `mapping_review` (`id`, `place_code`, `place_name`, `description`, `raw_json_data`, `status`, `created_at`) VALUES
('10', 'MB67-C-008', 'นายไพจิตร วสันตเสนานนท์', 'นายไพจิตร วสันตเสนานนท์ เป็นปราชญ์ของชุมชนเมืองบัวที่มีความรู้ด้านชีวประวัติบุคคลสำคัญ และประวัติศาสตร์ของเมืองบัว และยังเคยเป็นหัวหน้าทีมวิจัยโครงการศึกษาวิจัยหลายโครงการทั้งที่เกี่ยวข้องกับพิธีกรรม แนวทางความร่วมมือของหน่วยงานที่เกี่ยวข้อง การบริหารจัดการน้ำ และหลักสู๖รประวัติศาสตร์ท้องถิ่นของตำบลเมืองบวั ร่วมถึงการจัดการขยะมูลฝอยในชุมชนบ้านเมืองบัวอย่างมีส่วนร่วมของชุมชน ตำบลเมืองบัว อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด ซวึ่งเป็นงานวิจัยเพื่อท้องถิ่น ที่ได้รับงบประมาณสนับสนุนจากสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม และยังเป็นนักวิจัยร่วมในอีกหลายโครงการ', '{\"Latitude\": \"15.609067\", \"Longitude\": \"103.601038\", \"obj_title\": \"นายไพจิตร วสันตเสนานนท์\", \"obj_refcode\": \"MB67-C-008\", \"category_name\": \"บุคคลสำคัญ\", \"obj_physicals\": \"นายไพจิตร วสันตเสนานนท์ เป็นปราชญ์ของชุมชนเมืองบัวที่มีความรู้ด้านชีวประวัติบุคคลสำคัญ และประวัติศาสตร์ของเมืองบัว และยังเคยเป็นหัวหน้าทีมวิจัยโครงการศึกษาวิจัยหลายโครงการทั้งที่เกี่ยวข้องกับพิธีกรรม แนวทางความร่วมมือของหน่วยงานที่เกี่ยวข้อง การบริหารจัดการน้ำ และหลักสู๖รประวัติศาสตร์ท้องถิ่นของตำบลเมืองบวั ร่วมถึงการจัดการขยะมูลฝอยในชุมชนบ้านเมืองบัวอย่างมีส่วนร่วมของชุมชน ตำบลเมืองบัว อำเภอเกษตรวิสัย จังหวัดร้อยเอ็ด ซวึ่งเป็นงานวิจัยเพื่อท้องถิ่น ที่ได้รับงบประมาณสนับสนุนจากสำนักงานคณะกรรมการส่งเสริมวิทยาศาสตร์ วิจัยและนวัตกรรม และยังเป็นนักวิจัยร่วมในอีกหลายโครงการ&nbsp;\"}', 'pending', '2026-06-29 14:52:19'),
('11', 'KP67-C-024', 'ลำล่องภูกุ้มข้าว', '', '{\"Latitude\": \"16.3638359\", \"Longitude\": \"103.8241713\", \"obj_title\": \"ลำล่องภูกุ้มข้าว\", \"obj_refcode\": \"KP67-C-024\", \"category_name\": \"วิถีชีวิต\", \"obj_physicals\": \"\"}', 'pending', '2026-06-29 14:52:19'),
('12', 'KP67-C-023', 'นางทองสุก คุ้มศรีไว', 'นางทองสุก คุ้มศรีไวที่อยู่ : บ้านเลขที่ 64 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : หัตกรรมพื้นบ้าน (การทอผ้า)', '{\"Latitude\": \"16.3638359\", \"Longitude\": \"103.8241713\", \"obj_title\": \"นางทองสุก คุ้มศรีไว\", \"obj_refcode\": \"KP67-C-023\", \"category_name\": \"บุคคลสำคัญ\", \"obj_physicals\": \"นางทองสุก คุ้มศรีไวที่อยู่ : บ้านเลขที่ 64 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : หัตกรรมพื้นบ้าน (การทอผ้า)\"}', 'pending', '2026-06-29 14:52:19'),
('13', 'KP67-C-022', 'นางบุญชู มะอาจเลิศ', 'นางบุญชู มะอาจเลิศที่อยู่ : บ้านเลขที่ 111 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอลำ', '{\"Latitude\": \"16.3638359\", \"Longitude\": \"103.8241713\", \"obj_title\": \"นางบุญชู มะอาจเลิศ\", \"obj_refcode\": \"KP67-C-022\", \"category_name\": \"บุคคลสำคัญ\", \"obj_physicals\": \"นางบุญชู มะอาจเลิศที่อยู่ : บ้านเลขที่ 111 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอลำ\"}', 'pending', '2026-06-29 14:52:19'),
('14', 'KP67-C-021', 'นางอนงค์ พินิจพนธ์', 'นางอนงค์ พินิจพนธ์ที่อยู่ : บ้านเลขที่ 99 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอลำ', '{\"Latitude\": \"16.3638359\", \"Longitude\": \"103.8241713\", \"obj_title\": \"นางอนงค์ พินิจพนธ์\", \"obj_refcode\": \"KP67-C-021\", \"category_name\": \"บุคคลสำคัญ\", \"obj_physicals\": \"นางอนงค์ พินิจพนธ์ที่อยู่ : บ้านเลขที่ 99 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอลำ\"}', 'pending', '2026-06-29 14:52:19'),
('15', 'KP67-C-020', 'นายบุญมา สุ่มมาตย์', 'ที่อยู่ : บ้านเลขที่ 92 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน เล่นเครื่องดนตรีกั๊บแก๊บ', '{\"Latitude\": \"16.3638359\", \"Longitude\": \"103.8241713\", \"obj_title\": \"นายบุญมา สุ่มมาตย์\", \"obj_refcode\": \"KP67-C-020\", \"category_name\": \"บุคคลสำคัญ\", \"obj_physicals\": \"ที่อยู่ : บ้านเลขที่ 92 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน เล่นเครื่องดนตรีกั๊บแก๊บ\"}', 'pending', '2026-06-29 14:52:19'),
('16', 'KP67-C-019', 'นายดำรง มะอาจเลิศ', 'นายดำรง มะอาจเลิศที่อยู่ : บ้านเลขที่ 81 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน แต่งกลอนพื้นบ้าน เช่น กลอนลำล่องภูกุ้มข้าว', '{\"Latitude\": \"16.3638359\", \"Longitude\": \"103.8241713\", \"obj_title\": \"นายดำรง มะอาจเลิศ\", \"obj_refcode\": \"KP67-C-019\", \"category_name\": \"บุคคลสำคัญ\", \"obj_physicals\": \"นายดำรง มะอาจเลิศที่อยู่ : บ้านเลขที่ 81 หมู่5 ตำบลคำพอุง อำเภอโพธิ์ชัย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน แต่งกลอนพื้นบ้าน&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; เช่น กลอนลำล่องภูกุ้มข้าว\"}', 'pending', '2026-06-29 14:52:19'),
('17', 'KP67-C-018', 'นายหนู โพธิ์ศรีแก้ว', 'นายหนู โพธิ์ศรีแก้วที่อยู่ : บ้านเลขที่ 110 หมู่8 ตำบลคำพอุง อำเภอโพธิ์ชัย จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอแคน', '{\"Latitude\": \"16.3638359\", \"Longitude\": \"103.8241713\", \"obj_title\": \"นายหนู โพธิ์ศรีแก้ว\", \"obj_refcode\": \"KP67-C-018\", \"category_name\": \"บุคคลสำคัญ\", \"obj_physicals\": \"นายหนู โพธิ์ศรีแก้วที่อยู่ : บ้านเลขที่ 110 หมู่8 ตำบลคำพอุง อำเภอโพธิ์ชัย&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp;&nbsp; จังหวัดร้อยเอ็ดภูมิปัญญา ความถนัด : ศิลปินพื้นบ้าน หมอแคน\"}', 'pending', '2026-06-29 14:52:19')
